// Content for Friend or Frenemy? (node g09, ages 6–9, Chapter 2) — reworked to GDD 09 v2 (mechanic-embodying).
// "Spot a real friend, be one." The healthy-friendship game (the protocol's first reference implementation):
// 82 researched, India-grounded scenarios across six categories, each re-encoded to one of the shared v2 play
// actions (reflect / role-play / strike-rewrite / branch / sort / match / build / spot) — no binary "tap the
// right card", led by real friendship DILEMMAS (branch ×28 — decide, see the ripple, get a debrief) +
// say-the-line comebacks (role-play) + frenemy-flag SPOT scenes. Teaches friendship-quality literacy: what a
// real friend is, the frenemy flags (mean teasing, jealousy, control, exclusion, hot-and-cold, online), the
// everyday dilemmas, assertive + ally lines, and repair. AUTONOMY OVER VERDICTS (dilemmas have several good
// moves; the game backs the child's reasoning, never one "right" tap); SAFE TO BE WRONG (a weaker choice gets
// a kind consequence + a second look, no buzzer); NAME BEHAVIOURS NOT "BAD KIDS"; bullying / not-feeling-safe
// routes to a trusted adult (Childline 1098), help-seeking framed as brave. Builds on g03 (My Family Garden).
// Rendered by the shared engine (components/games/v2-engine.tsx). gameId "friend-frenemy". DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // — Real friends —
  {"id":"ff-001","cat":"real-friend","type":"build","hook":"Lensy: let's build a real friend, what goes in?","prompt":"Drag the real-friend qualities into the jar.","pieces":["is kind to you","listens to you","is happy when you do well","laughs AT you","includes you","only plays when no one better is around","keeps your secrets","tells you the truth gently"],"mode":"assemble","key":["is kind to you","listens to you","is happy when you do well","includes you","keeps your secrets","tells you the truth gently"],"relearn":"A real friend is kind, listens, includes you, and is glad when you do well.","persona":"any","source":"friendship-quality research"},
  {"id":"ff-002","cat":"real-friend","type":"match","hook":"What a good friend does, and how it makes you feel.","pairs":[{"left":"Cheers when you score","right":"You feel proud"},{"left":"Listens when you're sad","right":"You feel understood"},{"left":"Shares the snack","right":"You feel cared for"},{"left":"Saves you a seat","right":"You feel included"},{"left":"Keeps your secret","right":"You feel trusted"}],"relearn":"Good friends leave you feeling proud, understood, cared for, trusted and included.","persona":"any","source":"friendship-quality"},
  {"id":"ff-003","cat":"real-friend","type":"sort","hook":"Sort what you'd want in a friend.","items":[{"id":"a","text":"Happy when you win"},{"id":"b","text":"Sulks when you win"},{"id":"c","text":"Tells you the truth kindly"},{"id":"d","text":"Teases you in front of others"},{"id":"e","text":"Sticks around when you're sad"},{"id":"f","text":"Only calls when bored"}],"bins":[{"id":"real","label":"Real friend","valence":"pos"},{"id":"not","label":"Not so much","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"not","e":"real","f":"not"},"relearn":"Real friends are glad for you, honest-but-kind, and there in the hard moments.","persona":"any","source":"friendship-quality"},
  {"id":"ff-004","cat":"real-friend","type":"strike-rewrite","hook":"Someone says you can only have ONE best friend.","myth":{"un":"You're only allowed one real friend.","re":"You can have lots of friends, of different kinds.","why":"Friendship isn't a prize only one person can hold."},"relearn":"You can have many friends, and a wide circle is a strong one.","persona":"Reyansh","source":"social development"},
  {"id":"ff-005","cat":"real-friend","type":"reflect","hook":"Think of a friend who makes you feel good.","prompt":"What is one thing they do?","options":["They make me laugh","They listen to me","They include me","They're kind when I mess up"],"affirm":"That feeling, safe and glad, is what a real friend gives. Look for it, and give it.","relearn":"Notice who leaves you feeling good; that's a clue to a real friend.","persona":"any","source":"reflection / friendship-quality"},
  {"id":"ff-006","cat":"real-friend","type":"branch","hook":"A new kid is sitting alone at lunch.","options":[{"text":"Wave them over to your group","consequence":"They light up; your table gets more fun.","outcome":"kind"},{"text":"Go sit with them","consequence":"They relax; you make their day.","outcome":"kind","best":true},{"text":"Leave them; not your problem","consequence":"They eat alone again; you both miss out.","outcome":"missed"}],"debrief":"Going over to sit with them is the warmest move. Including someone is friendship.","relearn":"Including a lonely kid is an easy way to be kind.","persona":"Faizan","source":"inclusion"},
  {"id":"ff-007","cat":"real-friend","type":"role-play","hook":"You want to make friends with the new kid.","setup":"You walk over. What do you say?","yourLine":[{"text":"\"Hi, I'm ___. Want to play with us?\"","best":true},{"text":"Say nothing and hope they notice you"},{"text":"\"Why are you sitting alone?\""}],"relearn":"A warm, simple \"want to join us?\" is how most friendships start.","persona":"Reyansh","source":"social skills"},
  {"id":"ff-008","cat":"real-friend","type":"strike-rewrite","hook":"\"Real friends always say yes to you.\"","myth":{"un":"A real friend never says no to you.","re":"A real friend can say no and still care about you.","why":"Respect, not obedience, is what holds a friendship."},"relearn":"A friend who can say no honestly is a friend you can trust.","persona":"Ananya","source":"boundaries in friendship"},
  {"id":"ff-009","cat":"real-friend","type":"sort","hook":"Which of these are about being a GOOD friend yourself?","items":[{"id":"a","text":"Take turns"},{"id":"b","text":"Always be the boss"},{"id":"c","text":"Say sorry when you slip"},{"id":"d","text":"Keep score of favours"},{"id":"e","text":"Cheer your friend on"},{"id":"f","text":"Tease them to look cool"}],"bins":[{"id":"good","label":"Good friend move","valence":"pos"},{"id":"no","label":"Not really","valence":"neg"}],"key":{"a":"good","b":"no","c":"good","d":"no","e":"good","f":"no"},"relearn":"Being a good friend means turns, repair and cheering, not bossing or scorekeeping.","persona":"any","source":"prosocial skills"},
  {"id":"ff-010","cat":"real-friend","type":"match","hook":"A friend has a problem. Match a kind response.","pairs":[{"left":"They failed a test","right":"\"That's hard. Want to study together?\""},{"left":"They're left out","right":"\"Come play with us.\""},{"left":"They're scared","right":"\"I'm here. You're not alone.\""},{"left":"They lost their pen","right":"\"Let's go look for it.\""},{"left":"They're new in class","right":"\"Sit with me at lunch.\""}],"relearn":"Real friendship shows up most when a friend is struggling.","persona":"any","source":"empathy / support"},
  {"id":"ff-011","cat":"real-friend","type":"reflect","hook":"Lensy: what kind of friend do YOU want to be?","prompt":"Pick one to grow this week.","options":["A better listener","More including","Quicker to say sorry","More honest-but-kind"],"affirm":"Choosing how you show up is how good friends are made, not born.","relearn":"You can practise being a good friend, like any skill.","persona":"any","source":"growth mindset"},
  {"id":"ff-012","cat":"real-friend","type":"build","hook":"Build your friendship recipe.","prompt":"Pick the three ingredients you value most.","pieces":["honesty","fun","loyalty","kindness","respect","always agreeing"],"mode":"assemble","key":["honesty","fun","loyalty","kindness","respect"],"relearn":"Good friendships are built on respect and kindness, never on always agreeing.","persona":"any","source":"friendship-quality"},

  // — Frenemy flags —
  {"id":"ff-013","cat":"frenemy-flags","type":"sort","hook":"A 'friend' does a few things. Which are flags?","items":[{"id":"a","text":"Shares their colours with you"},{"id":"b","text":"\"Be my friend only if you give me your snack\""},{"id":"c","text":"Saves you a seat"},{"id":"d","text":"\"Do my dare or I'll drop you\""},{"id":"e","text":"Asks how your day went"},{"id":"f","text":"Takes your turn, won't give it back"}],"bins":[{"id":"friend","label":"Friend move","valence":"pos"},{"id":"flag","label":"Frenemy flag","valence":"neg"}],"key":{"a":"friend","b":"flag","c":"friend","d":"flag","e":"friend","f":"flag"},"relearn":"A friend who uses 'or else' to get their way is waving a control flag.","persona":"any","source":"coercion / friendship-quality"},
  {"id":"ff-014","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"She's just jealous because she cares about me.\"","myth":{"un":"A jealous friend is just being protective.","re":"Real friends celebrate you; they don't compete with you.","why":"Jealousy that sulks at your wins works against you, not for you."},"relearn":"A real friend is happy when good things happen to you.","persona":"Aanya","source":"friendship-quality / jealousy"},
  {"id":"ff-015","cat":"frenemy-flags","type":"sort","hook":"Sort these into Friend or Frenemy.","items":[{"id":"a","text":"Keeps your secret"},{"id":"b","text":"Tells your secret to be funny"},{"id":"c","text":"Includes you"},{"id":"d","text":"Leaves you out to feel powerful"},{"id":"e","text":"Is glad you did well"},{"id":"f","text":"Copies then mocks you"}],"bins":[{"id":"friend","label":"Friend","valence":"pos"},{"id":"frenemy","label":"Frenemy","valence":"neg"}],"key":{"a":"friend","b":"frenemy","c":"friend","d":"frenemy","e":"friend","f":"frenemy"},"relearn":"Frenemy moves use you, belittle you, or leave you out on purpose.","persona":"any","source":"friendship-quality"},
  {"id":"ff-016","cat":"frenemy-flags","type":"sort","hook":"In the group chat, which messages are flags?","items":[{"id":"a","text":"\"Great goal today!\""},{"id":"b","text":"\"Do my homework or you're out\""},{"id":"c","text":"\"Who wants to play after school?\""},{"id":"d","text":"\"Agree with me or we kick you out\""},{"id":"e","text":"\"Welcome to the group!\""},{"id":"f","text":"\"Send your answers or else\""}],"bins":[{"id":"friend","label":"Friend message","valence":"pos"},{"id":"flag","label":"Control flag","valence":"neg"}],"key":{"a":"friend","b":"flag","c":"friend","d":"flag","e":"friend","f":"flag"},"relearn":"\"Do this or you're out\" uses the group to control you, online too.","persona":"Reyansh","source":"relational aggression"},
  {"id":"ff-017","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"If they tease me, I must have earned it.\"","myth":{"un":"If a friend is mean to me, it's my fault.","re":"Unkindness is a choice the other person makes, not something you earn.","why":"You don't deserve cruelty for being yourself."},"relearn":"How a friend treats you is about their choices, not your worth.","persona":"Faizan","source":"self-worth / bullying"},
  {"id":"ff-018","cat":"frenemy-flags","type":"sort","hook":"Which is actually a frenemy flag? Sort them.","items":[{"id":"a","text":"Disagrees with you sometimes"},{"id":"b","text":"Only nice when they need something"},{"id":"c","text":"Likes different games than you"},{"id":"d","text":"Drops you when you're no use"},{"id":"e","text":"Has other friends too"},{"id":"f","text":"Sweet-talks you only before a favour"}],"bins":[{"id":"ok","label":"Not a flag","valence":"pos"},{"id":"flag","label":"Frenemy flag","valence":"neg"}],"key":{"a":"ok","b":"flag","c":"ok","d":"flag","e":"ok","f":"flag"},"relearn":"Disagreeing and liking different things aren't flags; being used only when convenient is.","persona":"Ananya","source":"friendship-quality"},
  {"id":"ff-019","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"To keep my friends, I have to do whatever they say.\"","myth":{"un":"You must do whatever your friends say or lose them.","re":"Friends worth keeping respect your no.","why":"A friendship that needs you to obey isn't a safe one."},"relearn":"You can keep your own mind and still keep real friends.","persona":"Reyansh","source":"peer pressure"},
  {"id":"ff-020","cat":"frenemy-flags","type":"sort","hook":"Teasing: good fun, or a flag? Sort each.","items":[{"id":"a","text":"You both laugh, stops when you ask"},{"id":"b","text":"It keeps going after you say stop"},{"id":"c","text":"It's about hurting, not fun"},{"id":"d","text":"Gentle, you're both smiling"},{"id":"e","text":"You can tease back, stays kind"},{"id":"f","text":"It's only ever aimed at you"}],"bins":[{"id":"ok","label":"Friendly fun","valence":"pos"},{"id":"flag","label":"Frenemy flag","valence":"neg"}],"key":{"a":"ok","b":"flag","c":"flag","d":"ok","e":"ok","f":"flag"},"relearn":"Fun teasing stops when you ask and goes both ways; mean teasing keeps going and aims to hurt.","persona":"any","source":"teasing vs bullying"},
  {"id":"ff-021","cat":"frenemy-flags","type":"branch","hook":"Your friend laughs at your drawing in front of others.","options":[{"text":"Laugh along so you fit in","consequence":"It stings, and it recurs.","outcome":"unkind-to-self"},{"text":"Say \"that wasn't kind\" and step back","consequence":"They're surprised; a real friend apologises.","outcome":"assertive","best":true},{"text":"Quietly tell them later how it felt","consequence":"They listen; you get each other.","outcome":"repair"}],"debrief":"Naming it in the moment stops the sting fastest.","relearn":"Name unkindness and still leave room to mend.","persona":"Aanya","source":"friendship"},
  {"id":"ff-022","cat":"frenemy-flags","type":"reflect","hook":"After playing with someone, how do you usually feel?","prompt":"Check in with yourself.","options":["Happy and relaxed","Worn out or put down","A mix","Not sure yet"],"affirm":"How a friend leaves you feeling is real information. Trust it.","relearn":"If someone often leaves you feeling small, that's worth noticing.","persona":"any","source":"emotional cues"},
  {"id":"ff-023","cat":"frenemy-flags","type":"sort","hook":"At the party, which moves are flags?","items":[{"id":"a","text":"Invites all but you, then tells you"},{"id":"b","text":"Invites the whole class"},{"id":"c","text":"Asks what games you like"},{"id":"d","text":"Tells you how fun it was without you"},{"id":"e","text":"Saves you a slice of cake"},{"id":"f","text":"\"Invite-only, and you're not invited\""}],"bins":[{"id":"in","label":"Includes you","valence":"pos"},{"id":"out","label":"Leaves you out","valence":"neg"}],"key":{"a":"out","b":"in","c":"in","d":"out","e":"in","f":"out"},"relearn":"Leaving you out on purpose, then making sure you know, is a frenemy move, even with a smile.","persona":"Ananya","source":"relational aggression"},
  {"id":"ff-024","cat":"frenemy-flags","type":"match","hook":"Match the frenemy move to what it really is.","pairs":[{"left":"\"Only joking!\" after a mean dig","right":"Hurting, then hiding it"},{"left":"\"Best friends\" today, ignores you tomorrow","right":"Hot and cold control"},{"left":"Shares your secret for a laugh","right":"Betraying trust"},{"left":"\"Do it or you're out\"","right":"Threatening to exclude you"},{"left":"Sulks when you do well","right":"Competing with your wins"}],"relearn":"Naming a frenemy move takes away its power to confuse you.","persona":"any","source":"relational aggression"},
  {"id":"ff-025","cat":"frenemy-flags","type":"branch","hook":"A friend says \"give me your pen or I'll tell everyone your secret.\"","options":[{"text":"Hand over the pen","consequence":"It works once, so they do it again.","outcome":"gives-in"},{"text":"Say \"that's not how friends act\" and tell a trusted adult","consequence":"The threat loses power; a grown-up can help.","outcome":"assertive","best":true}],"debrief":"A secret used as a threat isn't friendship.","relearn":"A friend who blackmails you isn't one; tell a trusted adult.","persona":"any","source":"safeguarding"},
  {"id":"ff-026","cat":"frenemy-flags","type":"sort","hook":"Online 'friend' behaviour: friend or frenemy?","items":[{"id":"a","text":"Likes your post, cheers you on"},{"id":"b","text":"Makes a group to leave you out"},{"id":"c","text":"Shares a screenshot to embarrass you"},{"id":"d","text":"Tags you in something fun"},{"id":"e","text":"\"Reply now or you're blocked\""},{"id":"f","text":"Wishes you on your birthday"}],"bins":[{"id":"friend","label":"Friend","valence":"pos"},{"id":"frenemy","label":"Frenemy","valence":"neg"}],"key":{"a":"friend","b":"frenemy","c":"frenemy","d":"friend","e":"frenemy","f":"friend"},"relearn":"Online, the same flags fly: cheering and tagging are friendship; the rest are not.","persona":"Reyansh","source":"digital friendships"},
  {"id":"ff-027","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"Popular kids can treat others however they like.\"","myth":{"un":"Being popular means you can be unkind.","re":"Kindness, not popularity, is what makes someone worth following.","why":"Status never earns the right to hurt people."},"relearn":"No amount of cool makes unkindness okay.","persona":"Reyansh","source":"status / values"},
  {"id":"ff-028","cat":"frenemy-flags","type":"reflect","hook":"Lensy: a tricky one. Can someone be a friend sometimes and a frenemy other times?","prompt":"What do you think?","options":["Yes, and that mix is confusing","Friends should be steady","I've felt that before"],"affirm":"That on-off feeling is real and tiring. You deserve friends who are steady-kind.","relearn":"Ambivalent 'frenemy' ties are uniquely stressful; steady kindness is worth holding out for.","persona":"any","source":"ambivalent ties research"},
  {"id":"ff-072","cat":"frenemy-flags","type":"sort","hook":"Which are kind, and which are flags?","items":[{"id":"a","text":"\"Be my friend or I'll tell your secret\""},{"id":"b","text":"\"You can't sit here, it's our table\""},{"id":"c","text":"\"Want to share my umbrella?\""},{"id":"d","text":"\"Come walk home with us\""},{"id":"e","text":"\"Do what I say or you're out\""},{"id":"f","text":"\"I saved you a seat\""}],"bins":[{"id":"kind","label":"Kind move","valence":"pos"},{"id":"flag","label":"Frenemy flag","valence":"neg"}],"key":{"a":"flag","b":"flag","c":"kind","d":"kind","e":"flag","f":"kind"},"relearn":"Threats and shutting people out are flags; sharing and welcoming are the real-friend signals.","persona":"any","source":"friendship-quality"},
  {"id":"ff-078","cat":"frenemy-flags","type":"sort","hook":"Last flag check: sort each fast.","items":[{"id":"a","text":"Happy for your win"},{"id":"b","text":"Makes you prove your loyalty"},{"id":"c","text":"Keeps your secrets"},{"id":"d","text":"Blows hot and cold"},{"id":"e","text":"Has your back when it's hard"},{"id":"f","text":"Drops you for someone cooler"}],"bins":[{"id":"friend","label":"Friend","valence":"pos"},{"id":"frenemy","label":"Frenemy","valence":"neg"}],"key":{"a":"friend","b":"frenemy","c":"friend","d":"frenemy","e":"friend","f":"frenemy"},"relearn":"Gladness, trust and having your back are friend signals; loyalty-tests and hot-cold are flags.","persona":"any","source":"friendship-quality"},

  // — Friend dilemmas —
  {"id":"ff-029","cat":"dilemmas","type":"branch","hook":"Your group wants to leave one kid out of the game.","options":[{"text":"Go along with the group","consequence":"The kid is hurt; you feel off.","outcome":"bystander"},{"text":"Say \"let's all play\"","consequence":"Some grumble, but the kid joins.","outcome":"ally","best":true},{"text":"Quietly go play with the left-out kid","consequence":"You make a friend and set an example.","outcome":"ally"}],"debrief":"Speaking up for 'everyone plays' helps the whole group, not just one kid.","relearn":"One voice for 'everyone plays' can shift a group.","persona":"Faizan","source":"bystander"},
  {"id":"ff-030","cat":"dilemmas","type":"branch","hook":"A friend dares you to take chocolate from a shop without paying.","options":[{"text":"Do it so they don't call you scared","consequence":"You could get caught, and feel bad after.","outcome":"risky"},{"text":"Say \"no thanks, that's stealing\"","consequence":"A real friend backs off; a frenemy pushes harder.","outcome":"assertive","best":true}],"debrief":"A dare doesn't cancel right and wrong.","relearn":"Real friends don't make you choose them over right.","persona":"Reyansh","source":"peer pressure"},
  {"id":"ff-031","cat":"dilemmas","type":"branch","hook":"Two friends have fallen out and each wants you to pick a side.","options":[{"text":"Pick one, drop the other","consequence":"Someone loses two friends.","outcome":"escalates"},{"text":"Stay kind to both, don't carry messages","consequence":"You keep both friendships, dodge the storm.","outcome":"wise","best":true},{"text":"Help them talk it out when ready","consequence":"They cool down.","outcome":"peacemaker"}],"debrief":"Staying kind to both without carrying messages keeps you out of the storm.","relearn":"Care for two friends without taking sides.","persona":"Ananya","source":"loyalty"},
  {"id":"ff-032","cat":"dilemmas","type":"branch","hook":"Your best friend wants to copy your homework.","options":[{"text":"Let them copy to avoid upset","consequence":"It doesn't help them learn, and risks trouble.","outcome":"short-term"},{"text":"Help them understand it instead","consequence":"They actually learn; better help.","outcome":"caring","best":true},{"text":"Say no and feel bad","consequence":"No is okay; helping is better.","outcome":"okay"}],"debrief":"The kindest help isn't always what's asked.","relearn":"Helping a friend learn beats letting them copy.","persona":"any","source":"integrity"},
  {"id":"ff-033","cat":"dilemmas","type":"branch","hook":"A classmate says \"that game's for girls\" when you reach for it.","options":[{"text":"Put it down so you're not teased","consequence":"You miss out, and the myth wins.","outcome":"gives-in"},{"text":"Say \"games are for everyone\" and play","consequence":"Some pause, some join; the myth loses power.","outcome":"comeback","best":true}],"debrief":"A calm comeback can flip a playground rule.","relearn":"Toys and games are for everyone; a good comeback travels fast.","persona":"Reyansh","source":"gender norms / peers"},
  {"id":"ff-034","cat":"dilemmas","type":"branch","hook":"Your friend is being teased and looks at you for help.","options":[{"text":"Look away so it doesn't turn on you","consequence":"Your friend feels alone.","outcome":"bystander"},{"text":"Stand next to them and say \"leave them alone\"","consequence":"The teaser often backs down.","outcome":"ally","best":true},{"text":"Get a trusted adult","consequence":"Help arrives; that's brave too.","outcome":"ally"}],"debrief":"Standing beside your friend right then stops it fastest; fetching an adult helps too.","relearn":"A bystander who steps in can stop it.","persona":"Faizan","source":"bystander"},
  {"id":"ff-035","cat":"dilemmas","type":"branch","hook":"A new friend wants you to stop seeing your old friend.","options":[{"text":"Drop your old friend to keep the new one","consequence":"You lose a real friend to please a controlling one.","outcome":"control"},{"text":"Say \"I can have both of you\"","consequence":"A good new friend is fine with that; a controlling one isn't.","outcome":"assertive","best":true}],"debrief":"A friend who makes you give up other friends is a red flag.","relearn":"You're allowed more than one friend.","persona":"any","source":"control"},
  {"id":"ff-036","cat":"dilemmas","type":"branch","hook":"You promised to keep a friend's secret, but they're being hurt at home.","options":[{"text":"Keep the secret because you promised","consequence":"Your friend stays in danger and alone.","outcome":"risky"},{"text":"Tell a trusted adult so your friend gets help","consequence":"The caring thing; some secrets are too big to keep.","outcome":"caring","best":true}],"debrief":"A promise doesn't hold when a friend's safety is at stake.","relearn":"If a friend is being hurt, tell a trusted adult.","persona":"any","source":"safeguarding (links g08)"},
  {"id":"ff-037","cat":"dilemmas","type":"branch","hook":"Everyone's laughing at a mean joke about a kid, and it IS funny.","options":[{"text":"Laugh along","consequence":"The kid feels worse; the group meaner.","outcome":"bystander"},{"text":"Stay quiet and change the subject","consequence":"You take the air out, no fight.","outcome":"okay"},{"text":"Say \"that's enough, it's not nice\"","consequence":"Brave; others often agree.","outcome":"ally","best":true}],"debrief":"Saying 'that's enough' is bravest; a joke can be funny and unkind.","relearn":"You needn't laugh at what hurts someone.","persona":"Ananya","source":"empathy"},
  {"id":"ff-038","cat":"dilemmas","type":"branch","hook":"Your friend keeps cancelling on you but always plays with others.","options":[{"text":"Keep waiting and hoping","consequence":"You feel let down again and again.","outcome":"stuck"},{"text":"Tell them how it feels, and also make other friends","consequence":"They may step up, and either way your circle grows.","outcome":"wise","best":true}],"debrief":"You can speak up AND widen your circle; you're not stuck.","relearn":"If someone keeps letting you down, it's fine to widen your circle.","persona":"any","source":"friendship-quality"},
  {"id":"ff-039","cat":"dilemmas","type":"branch","hook":"A popular kid offers to be your friend if you ignore your current best friend.","options":[{"text":"Take the offer","consequence":"You trade a real friend for a deal that can be cancelled anytime.","outcome":"control"},{"text":"Say no thanks","consequence":"You keep a real friend; worth more than status.","outcome":"wise","best":true}],"debrief":"Friendship offered as a deal with conditions isn't the real thing.","relearn":"A real friend doesn't come with a price tag of dropping others.","persona":"Reyansh","source":"status / loyalty"},
  {"id":"ff-040","cat":"dilemmas","type":"branch","hook":"You did something that hurt your friend's feelings, by accident.","options":[{"text":"Pretend you didn't notice","consequence":"The hurt sits there and grows.","outcome":"avoids"},{"text":"Say sorry and ask how to make it right","consequence":"They feel respected; the friendship gets stronger.","outcome":"repair","best":true}],"debrief":"Owning a mistake is one of the strongest friend moves there is.","relearn":"A real friend says sorry and tries to make it right.","persona":"any","source":"repair / accountability"},
  {"id":"ff-041","cat":"dilemmas","type":"reflect","hook":"Lensy: which dilemma felt most like your real life?","prompt":"Pick one to remember.","options":["Being left out","Being dared","Picking sides","Standing up for someone"],"affirm":"Noticing the ones that feel real means you'll spot them faster next time.","relearn":"Rehearsing choices now makes the real moment easier.","persona":"any","source":"transfer / metacognition"},
  {"id":"ff-073","cat":"dilemmas","type":"branch","hook":"Your friend wants you to gang up online against another kid.","options":[{"text":"Join in so your friend's happy","consequence":"It hurts someone and can spread fast.","outcome":"risky"},{"text":"Say \"I'm not doing that\" and tell a trusted adult if it continues","consequence":"You protect someone and keep your own kindness.","outcome":"assertive","best":true}],"debrief":"Ganging up online is bullying; a real friend won't ask you to.","relearn":"You can refuse to pile on, online or off.","persona":"Reyansh","source":"cyberbullying"},
  {"id":"ff-076","cat":"dilemmas","type":"branch","hook":"A friend tells you a secret, then you hear them lie about you.","options":[{"text":"Lie about them right back","consequence":"Now you're both frenemies; it spirals.","outcome":"escalates"},{"text":"Tell them what you heard and how it felt","consequence":"You give the friendship an honest chance.","outcome":"honest","best":true}],"debrief":"Meeting unkindness with honesty, not revenge, keeps you the good one.","relearn":"Answering unkindness with honesty beats revenge.","persona":"Ananya","source":"repair"},
  {"id":"ff-081","cat":"dilemmas","type":"branch","hook":"Capstone choice: a kid no one likes asks to be your friend.","options":[{"text":"Say no to protect your image","consequence":"You play it safe and miss a possible good friend.","outcome":"status"},{"text":"Give them a real chance","consequence":"You judge by how they treat you, not by gossip.","outcome":"openhearted","best":true}],"debrief":"Judge a possible friend by how they treat you, not by what others say.","relearn":"Everyone deserves a fair chance; you decide by how they treat you.","persona":"Faizan","source":"inclusion / values"},

  // — Stand up & speak —
  {"id":"ff-042","cat":"stand-up","type":"role-play","hook":"A friend keeps teasing you and won't stop.","setup":"Say the assertive line (calm, clear).","yourLine":[{"text":"\"Stop, I don't like that.\"","best":true},{"text":"Laugh and pretend it's fine"},{"text":"Tease them back harder"}],"relearn":"A calm, clear \"stop, I don't like that\" is strong, not rude.","persona":"Faizan","source":"assertiveness"},
  {"id":"ff-043","cat":"stand-up","type":"role-play","hook":"Someone says \"pink is a girl colour\" about your bag.","setup":"Reyansh wants a line for school tomorrow. Pick yours.","yourLine":[{"text":"\"Colours are for everyone.\"","best":true},{"text":"Hide the bag"},{"text":"\"No it's not!\" (just louder)"}],"relearn":"\"Colours are for everyone\" is a comeback you can actually use.","persona":"Reyansh","source":"gender norms / comebacks"},
  {"id":"ff-044","cat":"stand-up","type":"role-play","hook":"Your friend is being left out of the game.","setup":"Be the ally. What do you say to the group?","yourLine":[{"text":"\"Let's all play, it's more fun.\"","best":true},{"text":"Nothing"},{"text":"\"You're so mean!\" (and start a fight)"}],"relearn":"\"Let's all play\" includes your friend without starting a war.","persona":"Faizan","source":"bystander"},
  {"id":"ff-045","cat":"stand-up","type":"role-play","hook":"A kid is being dared to do something unsafe by the group.","setup":"Say something that helps them say no.","yourLine":[{"text":"\"You don't have to. Come on, let's go.\"","best":true},{"text":"\"Do it, do it!\""},{"text":"Watch silently"}],"relearn":"Giving a friend an exit (\"come on, let's go\") helps them say no.","persona":"any","source":"peer pressure / ally"},
  {"id":"ff-046","cat":"stand-up","type":"role-play","hook":"Someone spread a rumour about your friend.","setup":"What do you say when others repeat it?","yourLine":[{"text":"\"I don't think that's true, and it's not kind.\"","best":true},{"text":"Repeat it too"},{"text":"Say nothing and feel bad"}],"relearn":"Refusing to pass on a rumour helps it die out.","persona":"Ananya","source":"rumours / bystander"},
  {"id":"ff-047","cat":"stand-up","type":"branch","hook":"You said your assertive line, and the teasing didn't stop.","options":[{"text":"Give up and put up with it","consequence":"It keeps going; you feel worse.","outcome":"stuck"},{"text":"Walk away and tell a trusted adult","consequence":"Grown-ups can help when your words aren't enough.","outcome":"help","best":true}],"debrief":"Speaking up is step one; getting help is the brave step two.","relearn":"If standing up doesn't work, telling a trusted adult is the next move, not a failure.","persona":"Faizan","source":"escalation / help-seeking"},
  {"id":"ff-048","cat":"stand-up","type":"role-play","hook":"A friend made a mean joke about someone's family.","setup":"Say something, kindly but clear.","yourLine":[{"text":"\"That's not okay, that's their family.\"","best":true},{"text":"Laugh"},{"text":"Make a meaner joke back"}],"relearn":"You can call out a mean joke without being mean yourself.","persona":"Ananya","source":"values / assertiveness"},
  {"id":"ff-049","cat":"stand-up","type":"strike-rewrite","hook":"\"Standing up for someone is none of my business.\"","myth":{"un":"If it's not happening to me, it's none of my business.","re":"A bystander who speaks up can stop it; silence lets it grow.","why":"Friends look out for each other, and for those with no one."},"relearn":"Speaking up for someone else is exactly a friend's business.","persona":"any","source":"bystander research"},
  {"id":"ff-050","cat":"stand-up","type":"role-play","hook":"You want to check on a kid who was just teased.","setup":"What do you say to them after?","yourLine":[{"text":"\"You okay? That wasn't fair to you.\"","best":true},{"text":"Pretend nothing happened"},{"text":"\"Why do you let them do that?\""}],"relearn":"A quiet \"you okay?\" tells someone they're not alone.","persona":"Faizan","source":"support / empathy"},
  {"id":"ff-051","cat":"stand-up","type":"reflect","hook":"Lensy: which is hardest for you, saying stop, or backing up a friend?","prompt":"Be honest with yourself.","options":["Saying stop for me","Backing up someone else","Both are hard","I'm getting braver"],"affirm":"Naming the hard one is how you practise it. Bravery grows with reps.","relearn":"Standing up is a skill; it gets easier each time you try.","persona":"any","source":"self-efficacy"},
  {"id":"ff-052","cat":"stand-up","type":"branch","hook":"You see bullying happening but you're scared to step in alone.","options":[{"text":"Do nothing because you're scared","consequence":"Understandable, but it continues.","outcome":"stuck"},{"text":"Get a friend or an adult to step in with you","consequence":"It's easier and safer with backup, and it works.","outcome":"help","best":true}],"debrief":"You don't have to be a lone hero; getting backup is smart and brave.","relearn":"When it's not safe to step in alone, bring a friend or an adult.","persona":"any","source":"bystander / safety"},
  {"id":"ff-074","cat":"stand-up","type":"role-play","hook":"A friend keeps interrupting and never lets you talk.","setup":"Say the calm boundary line.","yourLine":[{"text":"\"I'd like a turn to talk too.\"","best":true},{"text":"Stop talking altogether"},{"text":"Shout over them"}],"relearn":"\"I'd like a turn too\" claims your space without a fight.","persona":"Ananya","source":"assertiveness"},
  {"id":"ff-079","cat":"stand-up","type":"branch","hook":"You stood up for someone and now the group is annoyed at you.","options":[{"text":"Wish you'd stayed quiet","consequence":"Maybe easier, but someone needed you.","outcome":"doubt"},{"text":"Feel proud, and find friends who value kindness","consequence":"The right friends respect what you did.","outcome":"values","best":true}],"debrief":"Doing the kind thing isn't always popular; the right people will respect it.","relearn":"Standing up can cost you in the moment and still be worth it.","persona":"Ananya","source":"values / courage"},

  // — Make up after a fight —
  {"id":"ff-053","cat":"repair","type":"strike-rewrite","hook":"\"Real friends never fight.\"","myth":{"un":"If you ever argue, you're not really friends.","re":"All friends disagree sometimes; what matters is how you make up.","why":"Conflict is normal; repair is the skill."},"relearn":"Good friends can disagree and still be good friends.","persona":"Ananya","source":"conflict / repair"},
  {"id":"ff-054","cat":"repair","type":"build","hook":"You and a friend argued. Build the make-up steps in order.","prompt":"Put the repair steps in a good order.","pieces":["cool down","say how you felt","listen to their side","say sorry for your part","agree what to do next"],"mode":"sequence","key":["cool down","say how you felt","listen to their side","say sorry for your part","agree what to do next"],"relearn":"Cool down, share, listen, say sorry, move on, that's how friends repair.","persona":"any","source":"conflict resolution"},
  {"id":"ff-055","cat":"repair","type":"role-play","hook":"You want to make up after a fight.","setup":"Pick the 'I' line that opens repair.","yourLine":[{"text":"\"I felt left out when that happened.\"","best":true},{"text":"\"You always ruin everything.\""},{"text":"Say nothing and stay cross"}],"relearn":"Starting with \"I felt...\" opens a door; \"you always...\" slams it.","persona":"Ananya","source":"I-statements"},
  {"id":"ff-056","cat":"repair","type":"branch","hook":"Your friend says sorry, but you're still a bit hurt.","options":[{"text":"Say \"it's fine\" but stay cold","consequence":"The hurt hides and lingers.","outcome":"avoids"},{"text":"Say \"thanks, I'm still a little sad, can we talk?\"","consequence":"Honest and kind; the friendship heals properly.","outcome":"repair","best":true}],"debrief":"You can accept a sorry and still be honest about your feelings.","relearn":"Forgiving doesn't mean hiding how you feel.","persona":"any","source":"repair / honesty"},
  {"id":"ff-057","cat":"repair","type":"sort","hook":"Repair move, or makes it worse?","items":[{"id":"a","text":"Listen to their side"},{"id":"b","text":"Bring up every old fight"},{"id":"c","text":"Say sorry for your part"},{"id":"d","text":"Give the silent treatment"},{"id":"e","text":"Find a fair fix together"},{"id":"f","text":"Tell other kids how mean they were"}],"bins":[{"id":"repair","label":"Repair","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"repair","b":"worse","c":"repair","d":"worse","e":"repair","f":"worse"},"relearn":"Listening, owning your part and a fair fix repair; scorekeeping, silence and gossip don't.","persona":"any","source":"conflict resolution"},
  {"id":"ff-058","cat":"repair","type":"branch","hook":"You apologised but your friend isn't ready to make up yet.","options":[{"text":"Demand they forgive you now","consequence":"Pushing makes them pull away.","outcome":"pushy"},{"text":"Give them a little time and stay kind","consequence":"Space plus kindness often brings them back.","outcome":"patient","best":true}],"debrief":"Repair sometimes needs time; you can't force a friend to be ready.","relearn":"After a real sorry, giving a friend some time is okay.","persona":"any","source":"repair / patience"},
  {"id":"ff-059","cat":"repair","type":"strike-rewrite","hook":"\"Saying sorry first means you lost.\"","myth":{"un":"Whoever says sorry first is the loser.","re":"Saying sorry first is a sign of strength, not defeat.","why":"Repair isn't a contest; it's care."},"relearn":"Going first to make up is brave, not weak.","persona":"Reyansh","source":"repair / values"},
  {"id":"ff-060","cat":"repair","type":"role-play","hook":"A friend is upset with you and you don't fully understand why.","setup":"What do you ask?","yourLine":[{"text":"\"Can you help me understand what upset you?\"","best":true},{"text":"\"You're overreacting.\""},{"text":"Walk off"}],"relearn":"Asking to understand beats guessing or dismissing.","persona":"Ananya","source":"perspective-taking"},
  {"id":"ff-061","cat":"repair","type":"branch","hook":"You and your friend want different games and start bickering.","options":[{"text":"Insist on your game","consequence":"One of you sulks; the fun stops.","outcome":"stuck"},{"text":"Take turns, your game then theirs","consequence":"You both get a turn and keep playing.","outcome":"fair","best":true}],"debrief":"Most small friend-fights melt with a fair turn-taking fix.","relearn":"Taking turns settles a lot of friendly disagreements.","persona":"any","source":"compromise"},
  {"id":"ff-062","cat":"repair","type":"reflect","hook":"Lensy: think of a time you made up with someone.","prompt":"What helped most?","options":["Saying sorry","Being listened to","A bit of time","A fair fix"],"affirm":"Whatever worked, you already have a repair tool. Use it again.","relearn":"You've repaired a friendship before; you can do it again.","persona":"any","source":"reflection"},
  {"id":"ff-075","cat":"repair","type":"branch","hook":"You realise YOU were the one who was unkind to a friend.","options":[{"text":"Hope they forget about it","consequence":"They don't, and trust frays.","outcome":"avoids"},{"text":"Go to them, own it, and say sorry","consequence":"They feel respected; you grow as a friend.","outcome":"repair","best":true}],"debrief":"Owning your own unkindness is the bravest repair of all.","relearn":"When you've been the frenemy, owning it and saying sorry makes it right.","persona":"any","source":"accountability"},

  // — Being a good friend —
  {"id":"ff-063","cat":"good-friend","type":"reflect","hook":"Lensy: honest check, are you sometimes the frenemy?","prompt":"We all slip. Pick one to watch.","options":["Teasing that goes too far","Leaving someone out","Sulking when a friend wins","Being only-sometimes kind"],"affirm":"Noticing your own slip is exactly what a good friend does. No shame, just a nudge.","relearn":"Being a good friend includes checking your own moves, kindly.","persona":"any","source":"self-awareness"},
  {"id":"ff-064","cat":"good-friend","type":"branch","hook":"One kid is always unkind to you, no matter what you try.","options":[{"text":"Keep chasing their approval","consequence":"You keep getting hurt.","outcome":"stuck"},{"text":"Step back and spend time with kinder friends","consequence":"You feel lighter; better friends have room now.","outcome":"wise","best":true}],"debrief":"Stepping back from someone always unkind isn't giving up; it's self-respect.","relearn":"You're allowed to step back from a friendship that keeps hurting you.","persona":"any","source":"boundaries / wellbeing"},
  {"id":"ff-065","cat":"good-friend","type":"branch","hook":"You feel lonely because your one friend moved away.","options":[{"text":"Decide you'll never find another friend","consequence":"That feels heavy and isn't true.","outcome":"stuck"},{"text":"Try one small step, sit with someone new, join a game","consequence":"New friendships start with small, brave steps.","outcome":"hopeful","best":true}],"debrief":"Friendships can be made again; it starts with one small move.","relearn":"You can always make new friends, one small step at a time.","persona":"any","source":"loneliness / agency"},
  {"id":"ff-066","cat":"good-friend","type":"strike-rewrite","hook":"\"Having lots of friends is the only thing that matters.\"","myth":{"un":"You need a big crowd of friends to be okay.","re":"A few kind, steady friends matter more than a big crowd.","why":"Quality of friendship beats quantity for how good you feel."},"relearn":"Even one or two kind friends is real richness.","persona":"any","source":"friendship-quality research"},
  {"id":"ff-067","cat":"good-friend","type":"sort","hook":"When a friendship is hard, what helps?","items":[{"id":"a","text":"Talk it out"},{"id":"b","text":"Bottle it up"},{"id":"c","text":"Ask a trusted adult"},{"id":"d","text":"Spread it as gossip"},{"id":"e","text":"Widen your circle"},{"id":"f","text":"Give the silent treatment"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"hurts","label":"Hurts","valence":"neg"}],"key":{"a":"helps","b":"hurts","c":"helps","d":"hurts","e":"helps","f":"hurts"},"relearn":"Talking it out, asking for help and widening your circle all help; bottling and gossip don't.","persona":"any","source":"coping"},
  {"id":"ff-068","cat":"good-friend","type":"branch","hook":"A friend is being bullied and asks you not to tell anyone.","options":[{"text":"Stay silent because they asked","consequence":"The bullying continues and they suffer alone.","outcome":"risky"},{"text":"Tell a trusted adult so it can stop","consequence":"Caring; bullying needs grown-up help.","outcome":"caring","best":true}],"debrief":"Helping a bullied friend means getting an adult, even if they're scared.","relearn":"For bullying, telling a trusted adult is how you truly help.","persona":"Faizan","source":"bullying"},
  {"id":"ff-069","cat":"good-friend","type":"role-play","hook":"You want to invite a lonely classmate into your group.","setup":"What's a warm way to say it?","yourLine":[{"text":"\"We're playing tag, want to join us?\"","best":true},{"text":"\"You can come if you want, I guess.\""},{"text":"Wait for them to ask first"}],"relearn":"A warm, specific invite is the kindest door to open.","persona":"any","source":"inclusion"},
  {"id":"ff-070","cat":"good-friend","type":"reflect","hook":"Lensy: what's one friend-skill you got better at today?","prompt":"Pick your win.","options":["Spotting a flag","Saying my line","Including someone","Making up after a fight"],"affirm":"That's a real skill you'll use for life, not just a sticker.","relearn":"Good friendship is a set of skills you keep growing.","persona":"any","source":"mastery"},
  {"id":"ff-071","cat":"good-friend","type":"strike-rewrite","hook":"\"If a friendship ends, you failed.\"","myth":{"un":"A friendship ending means you did something wrong.","re":"Some friendships fade or end, and that's a normal part of life.","why":"People grow and change; an ending isn't always a failure."},"relearn":"Friendships can change or end without anyone being bad.","persona":"any","source":"social development"},
  {"id":"ff-077","cat":"good-friend","type":"reflect","hook":"Lensy: who are your steady-kind friends?","prompt":"Picture one or two.","options":["I have one","I have a few","I'm still finding them","My family counts too"],"affirm":"Even one steady-kind friend is something to treasure and tend.","relearn":"Knowing who your steady friends are helps you invest in them.","persona":"any","source":"friendship-quality"},
  {"id":"ff-080","cat":"good-friend","type":"build","hook":"Build your friend-or-frenemy detector to take with you.","prompt":"Pick the green-flag signals for your detector.","pieces":["happy for me","includes me","honest and kind","uses 'or else'","leaves me out on purpose","keeps my secrets"],"mode":"assemble","key":["happy for me","includes me","honest and kind","keeps my secrets"],"relearn":"Green flags: glad for you, includes you, honest-kind, keeps trust. Hold out for those.","persona":"any","source":"friendship-quality"},
  {"id":"ff-082","cat":"good-friend","type":"reflect","hook":"Lensy: friend or frenemy, you can spot it now. What will you carry?","prompt":"Pick your motto.","options":["Real friends are glad for me","I can name a flag","I can stand up and make up","I deserve steady-kind friends"],"affirm":"Carry that. You're going to be a wonderful friend, and choose wonderful ones.","relearn":"You can spot real friends, be one, and hold out for steady-kind people.","persona":"any","source":"consolidation"},
  {"id":"ff-900","cat":"dilemmas","type":"branch","hook":"Your friend wants to copy your answers in the class test.","options":[{"text":"Slide your sheet over so they can see","consequence":"You both risk trouble, and they still don't learn it.","outcome":"risky"},{"text":"Whisper \"let's study together after\"","consequence":"They learn it properly; you stay out of trouble.","outcome":"caring","best":true}],"debrief":"Helping a friend learn beats helping them copy.","relearn":"The kindest help isn't cheating; it's helping them learn.","persona":"any","source":"integrity"},
  {"id":"ff-901","cat":"dilemmas","type":"branch","hook":"Your friend dares you to ring a stranger's doorbell and run.","options":[{"text":"Do it so they don't call you a baby","consequence":"You scare someone and feel bad after.","outcome":"risky"},{"text":"Say \"nah, let's do something else\"","consequence":"A real friend shrugs and moves on.","outcome":"assertive","best":true}],"debrief":"A dare doesn't cancel right and wrong.","relearn":"Saying no to a silly dare is the strong move.","persona":"Reyansh","source":"peer pressure"},
  {"id":"ff-902","cat":"dilemmas","type":"branch","hook":"Two best friends are fighting and both message YOU to take their side.","options":[{"text":"Side with one and block the other","consequence":"You end up losing one friend, maybe two.","outcome":"escalates"},{"text":"Stay kind to both and not pass messages","consequence":"You keep both, and dodge the storm.","outcome":"wise","best":true}],"debrief":"You don't have to pick a side to be a good friend to both.","relearn":"You can care for two friends without choosing between them.","persona":"Ananya","source":"loyalty"},
  {"id":"ff-903","cat":"dilemmas","type":"branch","hook":"A boy reaches for the skipping rope and is told \"that's for girls.\"","options":[{"text":"Let it go so no one teases you","consequence":"He misses out and the silly rule wins.","outcome":"gives-in"},{"text":"Say \"games are for everyone\" and skip together","consequence":"Others pause, then join in.","outcome":"comeback","best":true}],"debrief":"A calm comeback can flip a playground rule.","relearn":"Toys and games are for everyone.","persona":"Reyansh","source":"gender norms"},
  {"id":"ff-904","cat":"dilemmas","type":"branch","hook":"Your group is shutting one classmate out of the cricket game on purpose.","options":[{"text":"Go along so the group likes you","consequence":"That kid feels small; you feel off.","outcome":"bystander"},{"text":"Say \"come on, you can be on my team\"","consequence":"Some grumble, but the game gets bigger.","outcome":"ally","best":true}],"debrief":"One voice for 'everyone plays' can change the moment.","relearn":"One kid saying 'everyone plays' can shift a group.","persona":"Faizan","source":"bystander"},
  {"id":"ff-905","cat":"dilemmas","type":"branch","hook":"A new friend says you must stop sitting with your old friend.","options":[{"text":"Drop your old friend to please the new one","consequence":"You lose a real friend to a controlling one.","outcome":"control"},{"text":"Say \"I can be friends with both of you\"","consequence":"A good friend is fine with that.","outcome":"assertive","best":true}],"debrief":"A friend who makes you drop others is waving a control flag.","relearn":"You're allowed more than one friend.","persona":"any","source":"control"},
  {"id":"ff-906","cat":"dilemmas","type":"branch","hook":"A friend tells you a secret: someone at home keeps hurting them.","options":[{"text":"Keep it quiet because you promised","consequence":"Your friend stays hurt and alone.","outcome":"risky"},{"text":"Tell a trusted grown-up so help can come","consequence":"Some secrets are too big to keep; help arrives.","outcome":"caring","best":true}],"debrief":"A promise doesn't hold when a friend is being hurt.","relearn":"If a friend is being hurt, tell a trusted grown-up.","persona":"any","source":"safeguarding"},
  {"id":"ff-907","cat":"dilemmas","type":"branch","hook":"Everyone's laughing at a mean nickname for a quiet kid, and it's catchy.","options":[{"text":"Join the laughing so you fit in","consequence":"The kid feels worse; it spreads.","outcome":"bystander"},{"text":"Don't laugh and change the subject","consequence":"You take the air out of it.","outcome":"okay","best":true}],"debrief":"You don't have to laugh at what hurts someone.","relearn":"A joke can be funny and unkind at the same time.","persona":"Ananya","source":"empathy"},
  {"id":"ff-908","cat":"dilemmas","type":"branch","hook":"Your friend keeps cancelling on you but always plays with others.","options":[{"text":"Keep waiting and hoping each time","consequence":"You feel let down again and again.","outcome":"stuck"},{"text":"Tell them how it feels and also make new friends","consequence":"Either way, your circle grows.","outcome":"wise","best":true}],"debrief":"You can speak up AND widen your circle.","relearn":"If someone keeps letting you down, it's okay to widen your circle.","persona":"any","source":"friendship-quality"},
  {"id":"ff-909","cat":"dilemmas","type":"branch","hook":"A popular kid says they'll be your friend if you ditch your best friend.","options":[{"text":"Take the offer to be in the cool group","consequence":"You trade a real friend for a deal they can cancel.","outcome":"control"},{"text":"Say \"no thanks, I'll keep my friend\"","consequence":"You keep someone who's truly yours.","outcome":"wise","best":true}],"debrief":"Friendship with conditions isn't the real thing.","relearn":"A real friend doesn't come with a price tag.","persona":"Reyansh","source":"status / loyalty"},
  {"id":"ff-910","cat":"dilemmas","type":"branch","hook":"You bumped your friend's tiffin and the dosa fell on the floor.","options":[{"text":"Pretend it wasn't you","consequence":"They go hungry and trust frays.","outcome":"avoids"},{"text":"Say sorry and share your lunch","consequence":"They feel cared for; the friendship grows.","outcome":"repair","best":true}],"debrief":"Owning a mistake is one of the strongest friend moves.","relearn":"A real friend owns up and tries to make it right.","persona":"any","source":"accountability"},
  {"id":"ff-911","cat":"dilemmas","type":"branch","hook":"Your friend wants you to gang up in the class group chat on one kid.","options":[{"text":"Type a mean message so your friend's happy","consequence":"It hurts someone and spreads fast.","outcome":"risky"},{"text":"Say \"I'm not doing that\" and leave it alone","consequence":"You stay kind and don't pile on.","outcome":"assertive","best":true}],"debrief":"Ganging up online is bullying; a real friend won't ask.","relearn":"You can refuse to pile on, online or off.","persona":"Reyansh","source":"cyberbullying"},
  {"id":"ff-912","cat":"dilemmas","type":"branch","hook":"A kid no one talks to asks to join your game at recess.","options":[{"text":"Say it's full so your group stays the same","consequence":"You play it safe and miss a good friend.","outcome":"status"},{"text":"Say \"sure, you're in\"","consequence":"You judge them by how they treat you, not gossip.","outcome":"openhearted","best":true}],"debrief":"Give a possible friend a fair chance.","relearn":"Everyone deserves a fair chance; you decide by how they treat you.","persona":"Faizan","source":"inclusion"},
  {"id":"ff-913","cat":"dilemmas","type":"branch","hook":"Your friend wants you to skip class and hide behind the school.","options":[{"text":"Go along so they don't get cross","consequence":"You both could get into trouble and worry.","outcome":"risky"},{"text":"Say \"let's not, come back in with me\"","consequence":"A real friend comes with you.","outcome":"assertive","best":true}],"debrief":"A friend who pulls you into trouble isn't looking out for you.","relearn":"Real friends don't make you choose them over doing what's right.","persona":"any","source":"peer pressure"},
  {"id":"ff-914","cat":"dilemmas","type":"branch","hook":"A friend asks you to lie to the teacher so they're not caught.","options":[{"text":"Tell the lie to keep them happy","consequence":"If it unravels, you're both in it.","outcome":"risky"},{"text":"Say \"I won't lie, but I'll be with you\"","consequence":"You stay honest and still a friend.","outcome":"assertive","best":true}],"debrief":"Being a friend doesn't mean lying for someone.","relearn":"You can support a friend without lying for them.","persona":"any","source":"integrity"},
  {"id":"ff-915","cat":"dilemmas","type":"branch","hook":"Your friend got the lead in the school dance and you didn't.","options":[{"text":"Sulk and stop talking to them","consequence":"They feel hurt and a bit confused.","outcome":"jealous"},{"text":"Say \"well done, you'll be great\"","consequence":"You feel lighter and stay close.","outcome":"glad","best":true}],"debrief":"A real friend is glad when good things happen to you.","relearn":"You can feel a pang and still cheer your friend on.","persona":"Ananya","source":"jealousy / friendship-quality"},
  {"id":"ff-916","cat":"dilemmas","type":"branch","hook":"Your friend forgot to bring money and the canteen samosas look good.","options":[{"text":"Buy yours and eat it in front of them","consequence":"They feel left out and a bit sad.","outcome":"unkind"},{"text":"Split your samosa with them","consequence":"They feel cared for; you both enjoy it.","outcome":"kind","best":true}],"debrief":"Small sharing is a real-friend move.","relearn":"Noticing and sharing is how friends show care.","persona":"any","source":"empathy"},
  {"id":"ff-917","cat":"dilemmas","type":"branch","hook":"A friend keeps borrowing your colours and never gives them back.","options":[{"text":"Say nothing and quietly fume","consequence":"You stay annoyed and your box stays empty.","outcome":"stuck"},{"text":"Say \"I need my colours back, please\"","consequence":"A friend says sorry and returns them.","outcome":"assertive","best":true}],"debrief":"Asking for your things back is fair, not rude.","relearn":"You can speak up for your own stuff and stay friends.","persona":"any","source":"boundaries"},
  {"id":"ff-918","cat":"dilemmas","type":"branch","hook":"Your friend wants you to delete another kid from your contacts to prove loyalty.","options":[{"text":"Delete them to prove you're loyal","consequence":"Loyalty tests never end; there's always one more.","outcome":"control"},{"text":"Say \"I don't do loyalty tests\"","consequence":"A real friend trusts you without tests.","outcome":"assertive","best":true}],"debrief":"Being made to 'prove' loyalty is a control flag.","relearn":"A real friend trusts you, no tests needed.","persona":"any","source":"control"},
  {"id":"ff-919","cat":"dilemmas","type":"branch","hook":"You see a kid drop their bus pass and your friend says \"keep it.\"","options":[{"text":"Pocket it like your friend said","consequence":"That kid can't get home; you feel bad.","outcome":"risky"},{"text":"Run and return it to them","consequence":"They're so relieved; you did right.","outcome":"honest","best":true}],"debrief":"A friend's bad idea doesn't make it okay.","relearn":"Doing the right thing beats following a bad idea.","persona":"any","source":"integrity"},
  {"id":"ff-920","cat":"dilemmas","type":"branch","hook":"Your friend is being teased and looks at you, hoping you'll help.","options":[{"text":"Look away so it doesn't turn on you","consequence":"Your friend feels alone in it.","outcome":"bystander"},{"text":"Stand by them and say \"leave them alone\"","consequence":"The teaser often backs down.","outcome":"ally","best":true}],"debrief":"Standing beside a friend counts.","relearn":"A bystander who steps in can stop it.","persona":"Faizan","source":"bystander"},
  {"id":"ff-921","cat":"dilemmas","type":"branch","hook":"A friend wants to read your diary 'because best friends share everything.'","options":[{"text":"Hand it over so they don't sulk","consequence":"You feel uneasy giving up your private space.","outcome":"gives-in"},{"text":"Say \"some things are just mine\"","consequence":"A real friend respects that.","outcome":"assertive","best":true}],"debrief":"Best friends still get their own private things.","relearn":"You can keep your own mind and space and still be a good friend.","persona":"any","source":"boundaries"},
  {"id":"ff-922","cat":"dilemmas","type":"branch","hook":"Your old friend and your new friend don't get along at all.","options":[{"text":"Hide each from the other and feel stressed","consequence":"You're stuck juggling and worn out.","outcome":"stuck"},{"text":"Spend time with each in their own way","consequence":"You keep both without forcing them together.","outcome":"wise","best":true}],"debrief":"You don't have to make all your friends like each other.","relearn":"You can have many friends, of many kinds.","persona":"any","source":"friendship-quality"},
  {"id":"ff-923","cat":"dilemmas","type":"branch","hook":"A friend whispers a juicy rumour about a classmate and waits for you to spread it.","options":[{"text":"Pass it on to the next person","consequence":"The rumour grows and someone gets hurt.","outcome":"risky"},{"text":"Say \"I'd rather not spread that\"","consequence":"The rumour stops with you.","outcome":"assertive","best":true}],"debrief":"Refusing to pass on a rumour helps it die out.","relearn":"You can let a rumour stop with you.","persona":"Ananya","source":"rumours"},
  {"id":"ff-924","cat":"dilemmas","type":"branch","hook":"You won the spelling bee and your friend hasn't said anything.","options":[{"text":"Decide they're a bad friend and snap at them","consequence":"You start a fight over a guess.","outcome":"escalates"},{"text":"Say \"I'd love it if you were happy for me\"","consequence":"They explain; you sort it out.","outcome":"honest","best":true}],"debrief":"Saying how you feel beats guessing the worst.","relearn":"\"I felt...\" opens a door; jumping to anger slams it.","persona":"any","source":"communication"},
  {"id":"ff-925","cat":"dilemmas","type":"branch","hook":"Your friend wants you both to leave another kid on 'read' in the chat to be mean.","options":[{"text":"Ignore the kid like your friend says","consequence":"Being frozen out hurts, even online.","outcome":"unkind"},{"text":"Reply kindly to the left-out kid anyway","consequence":"One friendly message can change their day.","outcome":"ally","best":true}],"debrief":"Freezing someone out online is still leaving them out.","relearn":"You can be kind online even when others aren't.","persona":"Reyansh","source":"digital friendships"},
  {"id":"ff-926","cat":"dilemmas","type":"branch","hook":"A friend says you can only play with them if you wear the same colour daily.","options":[{"text":"Match them every day to keep the peace","consequence":"The rules keep growing and you feel boxed in.","outcome":"control"},{"text":"Say \"I'll wear what I like\"","consequence":"A real friend doesn't make rules for you.","outcome":"assertive","best":true}],"debrief":"\"Do this or you're out\" is a control flag, not friendship.","relearn":"A friend who makes rules for you is showing a control flag.","persona":"any","source":"control"},
  {"id":"ff-927","cat":"dilemmas","type":"branch","hook":"Your friend slipped and everyone saw; they're going red.","options":[{"text":"Laugh along with the others","consequence":"Your friend feels even more embarrassed.","outcome":"unkind"},{"text":"Help them up and say \"happens to everyone\"","consequence":"They feel less alone and the moment passes.","outcome":"kind","best":true}],"debrief":"A real friend has your back in an awkward moment.","relearn":"Real friends are there in the small hard moments too.","persona":"any","source":"empathy"},
  {"id":"ff-928","cat":"dilemmas","type":"branch","hook":"A friend wants you to break the line to let them cut in front.","options":[{"text":"Let them push in ahead of everyone","consequence":"Others are annoyed and it isn't fair.","outcome":"unfair"},{"text":"Say \"come stand with me at the back\"","consequence":"You stay fair and still together.","outcome":"fair","best":true}],"debrief":"Being a good friend doesn't mean being unfair to others.","relearn":"You can be loyal to a friend and still be fair to everyone.","persona":"any","source":"fairness"},
  {"id":"ff-929","cat":"dilemmas","type":"branch","hook":"Your friend is sad after a fight at home and goes very quiet.","options":[{"text":"Leave them be, it's not your problem","consequence":"They feel even more alone.","outcome":"bystander"},{"text":"Sit with them and say \"I'm here\"","consequence":"They feel less alone, even without words.","outcome":"kind","best":true}],"debrief":"Just being there is real friendship.","relearn":"Showing up for a sad friend is a real-friend move.","persona":"any","source":"support"},
  {"id":"ff-930","cat":"dilemmas","type":"branch","hook":"A friend dares you to throw a stone at the stray dog.","options":[{"text":"Throw it so they don't tease you","consequence":"You hurt an animal and feel awful.","outcome":"risky"},{"text":"Say \"no, that's cruel\" and walk on","consequence":"A real friend respects you for it.","outcome":"assertive","best":true}],"debrief":"A dare to be cruel is one to refuse.","relearn":"Saying no to a cruel dare is the strong move.","persona":"any","source":"peer pressure"},
  {"id":"ff-931","cat":"dilemmas","type":"branch","hook":"You and your friend both want to be team captain.","options":[{"text":"Argue until one of you storms off","consequence":"The game stops and you both fume.","outcome":"escalates"},{"text":"Take turns; one of you captains next time","consequence":"You both get a turn and keep playing.","outcome":"fair","best":true}],"debrief":"Disagreeing is normal; a fair fix settles it.","relearn":"Friends can disagree and find a fair way forward.","persona":"any","source":"compromise"},
  {"id":"ff-932","cat":"dilemmas","type":"branch","hook":"A friend texts late at night asking you to keep replying or they'll be upset.","options":[{"text":"Stay up replying so they're not cross","consequence":"You're tired and feel a bit trapped.","outcome":"control"},{"text":"Say \"goodnight, talk tomorrow\"","consequence":"A real friend understands you need sleep.","outcome":"assertive","best":true}],"debrief":"A friend who guilt-trips your time is showing a flag.","relearn":"You can set a kind limit and still be a good friend.","persona":"any","source":"boundaries / digital"},
  {"id":"ff-933","cat":"dilemmas","type":"branch","hook":"Your friend wants you to skip another classmate's birthday with them.","options":[{"text":"Skip it to stay loyal to your friend","consequence":"You hurt the birthday kid for no real reason.","outcome":"unkind"},{"text":"Go anyway and invite your friend along","consequence":"You can be kind to more than one person.","outcome":"wise","best":true}],"debrief":"Loyalty to one friend isn't a reason to be unkind to another.","relearn":"Being a good friend to one needn't mean snubbing another.","persona":"any","source":"inclusion"},
  {"id":"ff-934","cat":"dilemmas","type":"branch","hook":"A friend keeps 'joking' that you're too poor to join the trip.","options":[{"text":"Laugh so they don't see it stings","consequence":"It keeps going and hurts more each time.","outcome":"keeps-hurting"},{"text":"Say \"that's not a joke I like\"","consequence":"A real friend stops; the jab loses power.","outcome":"assertive","best":true}],"debrief":"A 'joke' that aims to hurt is a flag, not fun.","relearn":"You can name a jab as unkind without starting a war.","persona":"Faizan","source":"teasing"},
  {"id":"ff-935","cat":"dilemmas","type":"branch","hook":"Your friend wants you both to ignore the new kid who speaks a different language.","options":[{"text":"Ignore them like your friend wants","consequence":"The new kid feels shut out and alone.","outcome":"bystander"},{"text":"Smile and teach them a game with actions","consequence":"You find words aren't the only way to be friends.","outcome":"kind","best":true}],"debrief":"A wide circle is a strong one.","relearn":"Including someone different is an easy way to be a real friend.","persona":"any","source":"inclusion"},
  {"id":"ff-936","cat":"dilemmas","type":"branch","hook":"A friend asks you to take the blame for something they broke.","options":[{"text":"Take the blame so they're not in trouble","consequence":"You're punished for something you didn't do.","outcome":"unfair"},{"text":"Say \"I'll stand with you when you own it\"","consequence":"You support them without lying for them.","outcome":"wise","best":true}],"debrief":"Real friends don't ask you to carry their mistakes.","relearn":"You can support a friend without taking their blame.","persona":"any","source":"integrity"},
  {"id":"ff-937","cat":"dilemmas","type":"branch","hook":"Your friend wants the swing the whole break and won't share.","options":[{"text":"Give up and sulk on the side","consequence":"You miss the swing and feel grumpy.","outcome":"stuck"},{"text":"Say \"let's count to twenty and swap\"","consequence":"You both get a turn and stay friends.","outcome":"fair","best":true}],"debrief":"A fair turn-taking fix melts most small fights.","relearn":"Taking turns settles a lot of friendly disagreements.","persona":"any","source":"compromise"},
  {"id":"ff-938","cat":"dilemmas","type":"branch","hook":"A friend wants you to make a fake account to tease a classmate.","options":[{"text":"Help make it so your friend's happy","consequence":"It's hiding to hurt someone; it can spread.","outcome":"risky"},{"text":"Say \"I won't, and you shouldn't either\"","consequence":"You keep your kindness and maybe theirs.","outcome":"assertive","best":true}],"debrief":"Hiding behind a fake name to hurt is still bullying.","relearn":"A real friend won't ask you to hurt someone online.","persona":"Reyansh","source":"cyberbullying"},
  {"id":"ff-939","cat":"dilemmas","type":"branch","hook":"Your friend is upset you played with someone else at lunch.","options":[{"text":"Promise to only ever play with them","consequence":"You feel boxed in and can't make other friends.","outcome":"control"},{"text":"Say \"I like you AND other friends too\"","consequence":"A real friend learns there's room for both.","outcome":"assertive","best":true}],"debrief":"Friendship isn't a prize only one person can hold.","relearn":"You can have many friends; that's not betrayal.","persona":"any","source":"friendship-quality"},
  {"id":"ff-940","cat":"dilemmas","type":"branch","hook":"You overhear two friends planning to leave a third out of the group photo.","options":[{"text":"Stay quiet so you're not involved","consequence":"The third friend is hurt when they find out.","outcome":"bystander"},{"text":"Say \"let's get everyone in it\"","consequence":"One nudge and everyone's included.","outcome":"ally","best":true}],"debrief":"One voice for 'everyone's in' can change the moment.","relearn":"A bystander who speaks up can stop exclusion.","persona":"Ananya","source":"bystander"},
  {"id":"ff-941","cat":"dilemmas","type":"branch","hook":"A friend keeps changing the rules of the game so they always win.","options":[{"text":"Keep playing their unfair way","consequence":"It's no fun and you feel cheated.","outcome":"unfair"},{"text":"Say \"let's agree the rules first\"","consequence":"A real friend plays fair once you ask.","outcome":"assertive","best":true}],"debrief":"You can ask for fair play without a fight.","relearn":"Asking for fair rules keeps the fun for everyone.","persona":"any","source":"fairness"},
  {"id":"ff-942","cat":"dilemmas","type":"branch","hook":"Your friend wants you to laugh at the teacher behind their back with them.","options":[{"text":"Join in to seem cool to your friend","consequence":"If it's seen, you're both in trouble and it's unkind.","outcome":"risky"},{"text":"Give a small shrug and change the topic","consequence":"You skip it without making a scene.","outcome":"okay","best":true}],"debrief":"You can opt out of mean fun quietly.","relearn":"You don't have to join in to keep a friend.","persona":"any","source":"peer pressure"},
  {"id":"ff-943","cat":"dilemmas","type":"branch","hook":"A friend asks to copy your art project and hand it in as their own.","options":[{"text":"Let them copy yours fully","consequence":"They don't learn, and it can get found out.","outcome":"risky"},{"text":"Show them how, then let them make their own","consequence":"They learn and have something that's theirs.","outcome":"caring","best":true}],"debrief":"Helping a friend make their own beats handing over yours.","relearn":"Helping a friend learn beats helping them copy.","persona":"any","source":"integrity"},
  {"id":"ff-944","cat":"dilemmas","type":"branch","hook":"Your friend keeps saying \"if you were a real friend you'd give me your toy.\"","options":[{"text":"Hand it over each time they say it","consequence":"They keep using the line to get more.","outcome":"control"},{"text":"Say \"real friends don't make you prove it\"","consequence":"The guilt-line stops working.","outcome":"assertive","best":true}],"debrief":"\"If you were a real friend...\" used to get things is a control flag.","relearn":"A real friend doesn't make you buy their friendship.","persona":"any","source":"control"},
  {"id":"ff-945","cat":"dilemmas","type":"branch","hook":"A quieter kid wants to join your loud group but seems shy.","options":[{"text":"Carry on and let them hover at the edge","consequence":"They never quite get in.","outcome":"bystander"},{"text":"Ask them a question and make space","consequence":"A small welcome lets them in.","outcome":"kind","best":true}],"debrief":"Including a shy kid is an easy real-friend move.","relearn":"A small welcome can open the circle for someone.","persona":"any","source":"inclusion"},
  {"id":"ff-946","cat":"dilemmas","type":"branch","hook":"Your friend dares you to write something rude on the school wall.","options":[{"text":"Do it so they think you're brave","consequence":"It's damage and could get you both in trouble.","outcome":"risky"},{"text":"Say \"let's not wreck things\"","consequence":"A real friend backs off the idea.","outcome":"assertive","best":true}],"debrief":"Brave isn't the same as breaking the rules on a dare.","relearn":"Saying no to a harmful dare is the strong move.","persona":"any","source":"peer pressure"},
  {"id":"ff-947","cat":"dilemmas","type":"branch","hook":"A friend who's usually warm has been cold to you for days, with no reason given.","options":[{"text":"Decide you're done and freeze them back","consequence":"You both stay cold and confused.","outcome":"escalates"},{"text":"Ask \"are you okay? Have I upset you?\"","consequence":"Asking opens the door to sort it out.","outcome":"honest","best":true}],"debrief":"Asking beats guessing when a friend goes cold.","relearn":"Asking to understand beats freezing back.","persona":"any","source":"communication"},
  {"id":"ff-948","cat":"dilemmas","type":"reflect","hook":"Lensy: which friend dilemma feels most like YOUR week?","prompt":"Pick one to keep in mind.","options":["Being left out","Being dared","Picking sides","Helping vs cheating"],"affirm":"Noticing the real ones means you'll spot them faster next time.","relearn":"Rehearsing choices now makes the real moment easier.","persona":"any","source":"metacognition"},
  {"id":"ff-949","cat":"dilemmas","type":"reflect","hook":"Lensy: when a friend asks you to do something you're unsure about, what helps you decide?","prompt":"There's no wrong answer.","options":["Asking 'is it kind?'","Asking 'is it fair?'","Picturing how I'd feel after","Asking a grown-up"],"affirm":"Any of these is a good compass. You already have one inside you.","relearn":"A quick 'is it kind and fair?' helps you decide.","persona":"any","source":"values"},
  {"id":"ff-950","cat":"dilemmas","type":"reflect","hook":"Lensy: two friends fall out and both want you on their side. How does that feel?","prompt":"Just notice it.","options":["Stressful","A bit unfair","Like I'm stuck","I've felt this"],"affirm":"That stuck feeling is real. You can be kind to both without choosing.","relearn":"You don't have to pick a side to be a good friend to both.","persona":"any","source":"loyalty"},
  {"id":"ff-951","cat":"dilemmas","type":"reflect","hook":"Lensy: think of a time a friend dared you. What did your gut say?","prompt":"Pick what fits.","options":["It said 'don't'","It said 'maybe'","I wasn't sure","I listened to it"],"affirm":"That gut nudge is good information. It's okay to trust it.","relearn":"Your gut feeling is worth listening to in a dare.","persona":"any","source":"intuition"},
  {"id":"ff-952","cat":"dilemmas","type":"reflect","hook":"Lensy: helping a friend who's stuck on homework, what feels right to you?","prompt":"No wrong answer here.","options":["Explain it","Do an example together","Cheer them on","Ask if they want help first"],"affirm":"All of these help a friend learn, which is the kindest help.","relearn":"Helping a friend learn beats helping them copy.","persona":"any","source":"integrity"},
  {"id":"ff-953","cat":"dilemmas","type":"reflect","hook":"Lensy: you saw a kid being left out today. What could you carry from it?","prompt":"Pick one to remember.","options":["I can say 'come play'","I can sit with them","I can tell a grown-up","I noticed, that matters"],"affirm":"Noticing is the first step. Any of these is a brave next one.","relearn":"One voice for 'everyone plays' can change the moment.","persona":"any","source":"bystander"},
  {"id":"ff-954","cat":"dilemmas","type":"reflect","hook":"Lensy: when a friend and your idea of 'right' clash, what do you do?","prompt":"Be honest with yourself.","options":["Go with right","Talk it out","Find a middle way","It's hard for me"],"affirm":"Knowing it's hard is honest and brave. You're still learning, and that's fine.","relearn":"Real friends don't make you choose them over doing what's right.","persona":"any","source":"values"},
  {"id":"ff-955","cat":"dilemmas","type":"build","hook":"A friend dares you. Build your 'say no' plan in order.","prompt":"Put the steps in a good order.","pieces":["take a breath","say no clearly","offer another idea","walk away if needed"],"mode":"sequence","key":["take a breath","say no clearly","offer another idea","walk away if needed"],"relearn":"Breathe, say no, offer something else, leave if needed.","persona":"any","source":"refusal skills"},
  {"id":"ff-956","cat":"dilemmas","type":"build","hook":"Two friends fall out. Build what a good 'in-between' friend does.","prompt":"Pick the helpful moves.","pieces":["stay kind to both","don't carry messages","help them talk when ready","pick a side","spread the gossip"],"mode":"assemble","key":["stay kind to both","don't carry messages","help them talk when ready"],"relearn":"Care for both, don't carry messages, help them talk; don't pick sides or gossip.","persona":"Ananya","source":"loyalty"},
  {"id":"ff-957","cat":"dilemmas","type":"build","hook":"A friend wants to copy. Build the 'help them learn' plan.","prompt":"Put it in a good order.","pieces":["ask what's confusing","explain it simply","do one together","let them try alone"],"mode":"sequence","key":["ask what's confusing","explain it simply","do one together","let them try alone"],"relearn":"Ask, explain, do one together, let them try; that's real help.","persona":"any","source":"integrity"},
  {"id":"ff-958","cat":"dilemmas","type":"build","hook":"Build the kit for including a left-out kid.","prompt":"Pick the moves that welcome someone in.","pieces":["say 'come play'","make space","ask their name","whisper about them","leave them at the edge"],"mode":"assemble","key":["say 'come play'","make space","ask their name"],"relearn":"Inviting, making space and learning their name welcome someone in.","persona":"Faizan","source":"inclusion"},
  {"id":"ff-959","cat":"dilemmas","type":"build","hook":"A friend's secret is that they're being hurt. Build the caring plan.","prompt":"Put the steps in a good order.","pieces":["stay calm and kind","tell them you care","tell a trusted grown-up","check on your friend"],"mode":"sequence","key":["stay calm and kind","tell them you care","tell a trusted grown-up","check on your friend"],"relearn":"Some secrets are too big to keep; a grown-up helps.","persona":"any","source":"safeguarding"},
  {"id":"ff-960","cat":"dilemmas","type":"build","hook":"\"That's for boys/girls.\" Build your calm comeback kit.","prompt":"Pick what flips the silly rule.","pieces":["\"games are for everyone\"","keep playing calmly","invite them to join","push them over","shout you're wrong"],"mode":"assemble","key":["\"games are for everyone\"","keep playing calmly","invite them to join"],"relearn":"A calm comeback flips the rule; toys and games are for everyone.","persona":"Reyansh","source":"gender norms"},
  {"id":"ff-961","cat":"dilemmas","type":"build","hook":"Build the steps to decide a tricky friend dilemma.","prompt":"Put them in a good order.","pieces":["ask 'is it kind?'","ask 'is it fair?'","picture how I'd feel after","then choose"],"mode":"sequence","key":["ask 'is it kind?'","ask 'is it fair?'","picture how I'd feel after","then choose"],"relearn":"Kind? Fair? How would I feel after? Then choose.","persona":"any","source":"decision-making"},
  {"id":"ff-962","cat":"dilemmas","type":"build","hook":"A friend asks you to gang up online. Build the right response set.","prompt":"Pick the moves that keep you kind.","pieces":["say 'I'm not doing that'","be kind to the target","tell a grown-up if it grows","pile on","make a fake name"],"mode":"assemble","key":["say 'I'm not doing that'","be kind to the target","tell a grown-up if it grows"],"relearn":"You can refuse to pile on, be kind, and get help if it grows.","persona":"Reyansh","source":"cyberbullying"},
  {"id":"ff-963","cat":"dilemmas","type":"match","hook":"Match the dilemma to a good move.","pairs":[{"left":"A friend dares you","right":"Say no, suggest another idea"},{"left":"Two friends fall out","right":"Stay kind to both"},{"left":"A friend wants to copy","right":"Help them learn it"},{"left":"A kid is left out","right":"Say 'everyone plays'"},{"left":"A friend is being teased","right":"Stand beside them"}],"relearn":"Most dilemmas have a kind, fair move you can pick.","persona":"any","source":"decision-making"},
  {"id":"ff-964","cat":"dilemmas","type":"match","hook":"Match the tricky moment to what it teaches.","pairs":[{"left":"A dare to do wrong","right":"Right and wrong still count"},{"left":"Pick-a-side pressure","right":"You needn't choose"},{"left":"Helping vs cheating","right":"Learning beats copying"},{"left":"\"That's for girls\"","right":"Games are for everyone"},{"left":"A group excludes someone","right":"One voice can shift it"}],"relearn":"Each dilemma hides a friendship truth you can name.","persona":"any","source":"values"},
  {"id":"ff-965","cat":"dilemmas","type":"match","hook":"Match what a friend asks to a kind, clear reply.","pairs":[{"left":"\"Lie for me\"","right":"\"I won't lie, but I'm with you\""},{"left":"\"Drop your other friend\"","right":"\"I can have both of you\""},{"left":"\"Keep replying all night\"","right":"\"Goodnight, talk tomorrow\""},{"left":"\"Give me your snack or else\"","right":"\"That's not how friends act\""},{"left":"\"Spread this rumour\"","right":"\"I'd rather not\""}],"relearn":"You can answer a pushy ask kindly and clearly.","persona":"any","source":"assertiveness"},
  {"id":"ff-966","cat":"dilemmas","type":"match","hook":"Match the move to the friendship value it shows.","pairs":[{"left":"Sharing your lunch","right":"Care"},{"left":"Taking turns on the swing","right":"Fairness"},{"left":"Saying 'everyone plays'","right":"Including"},{"left":"Returning a lost pass","right":"Honesty"},{"left":"Not picking sides","right":"Loyalty to both"}],"relearn":"Good friend moves show care, fairness, including, honesty and loyalty.","persona":"any","source":"values"},
  {"id":"ff-967","cat":"dilemmas","type":"match","hook":"Match the choice to its likely ripple.","pairs":[{"left":"Laugh at a mean joke","right":"It spreads and hurts"},{"left":"Change the subject","right":"It fizzles out"},{"left":"Copy a friend's work","right":"Neither of you learns"},{"left":"Study together","right":"You both get it"},{"left":"Spread a rumour","right":"Someone gets hurt"}],"relearn":"Every choice has a ripple; you can pick the kind one.","persona":"any","source":"consequences"},
  {"id":"ff-968","cat":"dilemmas","type":"match","hook":"Match the dilemma to the friend-skill it needs.","pairs":[{"left":"A friend cancels often","right":"Speak up, widen circle"},{"left":"A friend goes cold","right":"Ask, don't guess"},{"left":"A loyalty test","right":"Refuse the test"},{"left":"A shy kid hovers","right":"Make space"},{"left":"A secret about being hurt","right":"Tell a grown-up"}],"relearn":"Different dilemmas call for different friend-skills.","persona":"any","source":"skills"},
  {"id":"ff-969","cat":"dilemmas","type":"match","hook":"Match the pushy line to why it's a flag.","pairs":[{"left":"\"Prove you're loyal\"","right":"Loyalty tests never end"},{"left":"\"Or you're out\"","right":"A control flag"},{"left":"\"Best friends share everything\"","right":"You still get private things"},{"left":"\"Only play with me\"","right":"You're allowed many friends"},{"left":"\"If you were a real friend...\"","right":"Buying friendship"}],"relearn":"Naming a pushy line takes away its power to confuse you.","persona":"any","source":"control"},
  {"id":"ff-970","cat":"dilemmas","type":"match","hook":"Match the situation to the brave next step.","pairs":[{"left":"Teasing won't stop","right":"Tell a trusted grown-up"},{"left":"Scared to step in alone","right":"Bring a friend or adult"},{"left":"You were unkind","right":"Own it and say sorry"},{"left":"A friend's being bullied","right":"Get an adult's help"},{"left":"You said no and feel shaky","right":"Find kinder friends"}],"relearn":"When words aren't enough, getting help is the brave step.","persona":"any","source":"help-seeking"},
  {"id":"ff-971","cat":"dilemmas","type":"sort","hook":"A friend dares you. Sort each move.","items":[{"id":"a","text":"Say no clearly"},{"id":"b","text":"Do it to look brave"},{"id":"c","text":"Offer a safe idea instead"},{"id":"d","text":"Dare them back harder"},{"id":"e","text":"Walk away calmly"},{"id":"f","text":"Tease them for asking"}],"bins":[{"id":"good","label":"Good move","valence":"pos"},{"id":"no","label":"Not so good","valence":"neg"}],"key":{"a":"good","b":"no","c":"good","d":"no","e":"good","f":"no"},"relearn":"Saying no, offering a safe idea and walking away beat copying a dare.","persona":"any","source":"refusal skills"},
  {"id":"ff-972","cat":"dilemmas","type":"sort","hook":"Two friends fall out. Sort what to do.","items":[{"id":"a","text":"Stay kind to both"},{"id":"b","text":"Carry mean messages"},{"id":"c","text":"Help them talk when ready"},{"id":"d","text":"Pick a side"},{"id":"e","text":"Keep playing with each"},{"id":"f","text":"Spread the gossip"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"hurts","label":"Hurts","valence":"neg"}],"key":{"a":"helps","b":"hurts","c":"helps","d":"hurts","e":"helps","f":"hurts"},"relearn":"You don't have to pick a side; stay kind to both and don't carry messages.","persona":"Ananya","source":"loyalty"},
  {"id":"ff-973","cat":"dilemmas","type":"sort","hook":"A friend wants help with work. Sort the help.","items":[{"id":"a","text":"Explain how it works"},{"id":"b","text":"Let them copy yours"},{"id":"c","text":"Do an example together"},{"id":"d","text":"Hand in their work for them"},{"id":"e","text":"Cheer them on to try"},{"id":"f","text":"Whisper answers in the test"}],"bins":[{"id":"real","label":"Real help","valence":"pos"},{"id":"not","label":"Not real help","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"not","e":"real","f":"not"},"relearn":"The kindest help is helping a friend learn, not copy.","persona":"any","source":"integrity"},
  {"id":"ff-974","cat":"dilemmas","type":"sort","hook":"When a friend pushes you, sort what's a green light vs a flag.","items":[{"id":"a","text":"Respects your no"},{"id":"b","text":"Says 'or you're out'"},{"id":"c","text":"Lets you have other friends"},{"id":"d","text":"Makes you prove loyalty"},{"id":"e","text":"Asks, doesn't demand"},{"id":"f","text":"Guilt-trips your time"}],"bins":[{"id":"ok","label":"Green light","valence":"pos"},{"id":"flag","label":"A flag","valence":"neg"}],"key":{"a":"ok","b":"flag","c":"ok","d":"flag","e":"ok","f":"flag"},"relearn":"Respecting your no is friendship; 'or else' and loyalty tests are control flags.","persona":"any","source":"control"},
  {"id":"ff-975","cat":"dilemmas","type":"sort","hook":"A kid is being left out. Sort each choice.","items":[{"id":"a","text":"Say 'come play'"},{"id":"b","text":"Pretend not to notice"},{"id":"c","text":"Make space for them"},{"id":"d","text":"Whisper about them"},{"id":"e","text":"Tell a grown-up if it's mean"},{"id":"f","text":"Laugh when they're shut out"}],"bins":[{"id":"ally","label":"Ally move","valence":"pos"},{"id":"by","label":"Stands by","valence":"neg"}],"key":{"a":"ally","b":"by","c":"ally","d":"by","e":"ally","f":"by"},"relearn":"Inviting, making space and telling a grown-up beat standing by.","persona":"Faizan","source":"bystander"},
  {"id":"ff-976","cat":"dilemmas","type":"sort","hook":"Online dilemma: sort each move.","items":[{"id":"a","text":"Reply kindly to a left-out kid"},{"id":"b","text":"Pile on in the group chat"},{"id":"c","text":"Refuse to forward a mean post"},{"id":"d","text":"Make a fake account to tease"},{"id":"e","text":"Tell a grown-up if it grows"},{"id":"f","text":"Leave someone on 'read' to be mean"}],"bins":[{"id":"kind","label":"Kind online","valence":"pos"},{"id":"unkind","label":"Unkind online","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"The same flags fly online; you can choose the kind move.","persona":"Reyansh","source":"digital friendships"},
  {"id":"ff-977","cat":"dilemmas","type":"sort","hook":"A friend asks you to do something. Sort: just do it, or stop and think?","items":[{"id":"a","text":"Share a snack"},{"id":"b","text":"Lie to the teacher"},{"id":"c","text":"Take turns on a game"},{"id":"d","text":"Take the blame for them"},{"id":"e","text":"Cheer them on"},{"id":"f","text":"Throw a stone at a dog"}],"bins":[{"id":"yes","label":"Kind, go ahead","valence":"pos"},{"id":"stop","label":"Stop and think","valence":"uhoh"}],"key":{"a":"yes","b":"stop","c":"yes","d":"stop","e":"yes","f":"stop"},"relearn":"Some asks are easy yeses; others need a pause and a kind no.","persona":"any","source":"decision-making"},
  {"id":"ff-978","cat":"dilemmas","type":"sort","hook":"Friend fight over a game. Sort what settles it vs what blows it up.","items":[{"id":"a","text":"Take turns"},{"id":"b","text":"Insist you're right"},{"id":"c","text":"Agree the rules first"},{"id":"d","text":"Storm off"},{"id":"e","text":"Find a fair fix"},{"id":"f","text":"Change rules to win"}],"bins":[{"id":"settle","label":"Settles it","valence":"pos"},{"id":"blow","label":"Blows it up","valence":"neg"}],"key":{"a":"settle","b":"blow","c":"settle","d":"blow","e":"settle","f":"blow"},"relearn":"Turns, agreed rules and a fair fix settle a friendly fight.","persona":"any","source":"compromise"},
  {"id":"ff-979","cat":"dilemmas","type":"strike-rewrite","hook":"\"If a friend dares you, you have to do it.\"","myth":{"un":"A dare from a friend cancels right and wrong.","re":"A dare doesn't change what's right; you can still say no.","why":"Real friends don't make you choose them over doing right."},"relearn":"Saying no to a dare is the strong move.","persona":"Reyansh","source":"peer pressure"},
  {"id":"ff-980","cat":"dilemmas","type":"strike-rewrite","hook":"\"When friends fight, you have to pick a side.\"","myth":{"un":"You must take one friend's side when two fall out.","re":"You can be a good friend to both without picking a side.","why":"Their fight is theirs; your kindness can go to both."},"relearn":"You don't have to pick a side to be a good friend to both.","persona":"Ananya","source":"loyalty"},
  {"id":"ff-981","cat":"dilemmas","type":"strike-rewrite","hook":"\"Letting a friend copy is the kind thing to do.\"","myth":{"un":"Real friends let each other copy their work.","re":"The kindest help is helping a friend learn, not copy.","why":"Copying skips the learning; helping them get it lasts."},"relearn":"Helping a friend learn beats helping them copy.","persona":"any","source":"integrity"},
  {"id":"ff-982","cat":"dilemmas","type":"strike-rewrite","hook":"\"Some games are just for boys, some just for girls.\"","myth":{"un":"Certain toys and games are only for boys or only for girls.","re":"Toys, games and colours are for everyone.","why":"What you enjoy doesn't depend on being a boy or a girl."},"relearn":"A calm comeback can flip that playground rule.","persona":"Reyansh","source":"gender norms"},
  {"id":"ff-983","cat":"dilemmas","type":"strike-rewrite","hook":"\"If you're not in the fight, it's none of your business.\"","myth":{"un":"When a group leaves someone out, it's not your problem.","re":"One voice for 'everyone plays' can change the moment.","why":"A bystander who steps in is brave and often turns it around."},"relearn":"One kid speaking up can shift a whole group.","persona":"any","source":"bystander"},
  {"id":"ff-984","cat":"dilemmas","type":"strike-rewrite","hook":"\"A real friend would do anything you ask.\"","myth":{"un":"A real friend always does whatever you tell them.","re":"A real friend can say no and is still a real friend.","why":"Friendship runs on respect, not on obeying orders."},"relearn":"You can keep your own mind and still keep real friends.","persona":"any","source":"boundaries"},
  {"id":"ff-985","cat":"dilemmas","type":"strike-rewrite","hook":"\"There's always one right answer to a friend problem.\"","myth":{"un":"Every friendship dilemma has just one correct move.","re":"Often more than one good move exists; you can reason it out.","why":"A 'weaker' choice isn't a fail, just a chance to think again."},"relearn":"More than one good move exists; back your own reasoning.","persona":"Ananya","source":"autonomy"},
  {"id":"ff-986","cat":"dilemmas","type":"strike-rewrite","hook":"\"Keeping a friend's secret always comes first.\"","myth":{"un":"You must keep every secret a friend tells you.","re":"If a friend is being hurt, telling a trusted grown-up helps them.","why":"Some secrets are too big and unsafe to keep alone."},"relearn":"If a friend is being hurt, tell a trusted grown-up.","persona":"any","source":"safeguarding"},
  {"id":"ff-987","cat":"dilemmas","type":"role-play","hook":"A friend dares you to take a chocolate without paying.","setup":"Say your line, calm and clear.","yourLine":[{"text":"\"No thanks, that's stealing.\"","best":true},{"text":"\"Fine, but just this once.\""},{"text":"Take it so they don't laugh"}],"relearn":"A dare doesn't cancel right and wrong; saying no is strong.","persona":"Reyansh","source":"peer pressure"},
  {"id":"ff-988","cat":"dilemmas","type":"role-play","hook":"Two friends fall out and one demands you pick them.","setup":"Say a line that keeps you out of the middle.","yourLine":[{"text":"\"I care about you both; I won't pick a side.\"","best":true},{"text":"\"Okay, I'm on your side.\""},{"text":"Say nothing and avoid them both"}],"relearn":"You can be a good friend to both without picking a side.","persona":"Ananya","source":"loyalty"},
  {"id":"ff-989","cat":"dilemmas","type":"role-play","hook":"A friend wants to copy your test answers.","setup":"Say a line that helps without cheating.","yourLine":[{"text":"\"Let's study together after, I'll show you.\"","best":true},{"text":"\"Okay, but be quick.\""},{"text":"Slide your sheet over"}],"relearn":"Helping a friend learn beats helping them copy.","persona":"any","source":"integrity"},
  {"id":"ff-990","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"A real friend would never make me feel small.\"","myth":{"un":"If they put me down, I must have done something wrong.","re":"A friend who keeps belittling you is waving a frenemy flag.","why":"Putting you down to feel bigger is their choice, not your fault."},"relearn":"Belittling is a frenemy flag, and it's never something you earned.","persona":"Faizan","source":"relational aggression / self-worth"},
  {"id":"ff-991","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"My friend sulks when I win. That means they really care.\"","myth":{"un":"A friend who sulks at my wins is just showing they care.","re":"A real friend cheers your wins instead of competing with them.","why":"Jealousy that sulks at your good news works against you, not for you."},"relearn":"A real friend is glad when good things happen to you.","persona":"Ananya","source":"jealousy / friendship-quality"},
  {"id":"ff-992","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"She's only nice when she needs my help. That's normal, right?\"","myth":{"un":"It's fine if a friend is only kind when they want something.","re":"Being warm only when they need you is a using-you flag.","why":"Real friends are kind on the ordinary days too, not just useful ones."},"relearn":"Being used only when convenient is a flag; steady kindness is the signal.","persona":"any","source":"friendship-quality"},
  {"id":"ff-993","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"If I don't do the dare, they'll drop me as a friend.\"","myth":{"un":"A real friend will drop you if you won't do their dare.","re":"\"Do this or you're out\" is a control flag, not friendship.","why":"A friend worth keeping respects your no instead of threatening you."},"relearn":"\"Do this or else\" is control, not friendship.","persona":"Reyansh","source":"coercion / control"},
  {"id":"ff-994","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"Best friends should never like anyone else.\"","myth":{"un":"A true friend gets to decide who else you can be friends with.","re":"Controlling who you talk to is a flag, not closeness.","why":"You can have many friends; a real one is glad your circle is wide."},"relearn":"A friend who polices your other friendships is waving a control flag.","persona":"any","source":"control / exclusion"},
  {"id":"ff-995","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"They tease me because boys can't like drawing. Maybe they're right.\"","myth":{"un":"If they tease what I like, the teasing must be fair.","re":"Mean teasing about what you enjoy is a flag, never deserved.","why":"Liking drawing is not a flaw; their cruelty is their choice."},"relearn":"Unkindness about who you are is their choice, not your worth.","persona":"Faizan","source":"self-worth / gender norms"},
  {"id":"ff-996","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"My friend reads my chats and tells me who to block. That's loyalty.\"","myth":{"un":"A loyal friend checks your phone and picks who you can talk to.","re":"Controlling your phone and chats is a flag, not loyalty.","why":"Real friends trust you; they don't run your messages for you."},"relearn":"Controlling your online life is a frenemy flag, online too.","persona":"Reyansh","source":"digital control"},
  {"id":"ff-997","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"They were sweet yesterday and ice-cold today. I must have upset them.\"","myth":{"un":"Hot-and-cold treatment means you keep doing something wrong.","re":"Blowing hot and cold to keep you guessing is a frenemy flag.","why":"Steady kindness, not a guessing game, is what a real friend gives."},"relearn":"Hot-and-cold isn't your fault; it's a flag to notice.","persona":"any","source":"hot-and-cold / ambivalent ties"},
  {"id":"ff-998","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"A good friend keeps a tally of everything they do for you.\"","myth":{"un":"Real friends keep score of every favour and remind you of it.","re":"Holding favours over your head is a frenemy flag.","why":"Kindness with a price tag is control dressed up as friendship."},"relearn":"Scorekeeping to control you is a flag, not generosity.","persona":"any","source":"control / friendship-quality"},
  {"id":"ff-999","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"They copy my answers, then call me a teacher's pet. Funny, na?\"","myth":{"un":"A friend who uses your help then mocks you is just joking.","re":"Taking your help then putting you down is a frenemy flag.","why":"A real friend thanks you; they don't laugh at you for helping."},"relearn":"Using you and mocking you is a flag, even with a laugh.","persona":"Ananya","source":"relational aggression"},
  {"id":"ff-1000","cat":"frenemy-flags","type":"strike-rewrite","hook":"\"If a popular kid is mean to me, that's just how it goes.\"","myth":{"un":"Cool, popular kids are allowed to be unkind to you.","re":"Being popular never earns the right to hurt people.","why":"Kindness, not status, is what makes someone worth following."},"relearn":"No amount of cool makes a frenemy flag okay.","persona":"Reyansh","source":"status / values"},
  {"id":"ff-1001","cat":"frenemy-flags","type":"sort","hook":"Friend, or frenemy flag? Sort each.","items":[{"id":"a","text":"Cheers when you win"},{"id":"b","text":"Sulks when you win"},{"id":"c","text":"Keeps your secret"},{"id":"d","text":"Tells your secret for a laugh"},{"id":"e","text":"Likes a different game"},{"id":"f","text":"Drops you when you say no"}],"bins":[{"id":"friend","label":"Real friend","valence":"pos"},{"id":"flag","label":"Frenemy flag","valence":"neg"}],"key":{"a":"friend","b":"flag","c":"friend","d":"flag","e":"friend","f":"flag"},"relearn":"Cheering, keeping secrets and liking different things are friend signals; the rest are flags.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1002","cat":"frenemy-flags","type":"sort","hook":"Online 'friend' moves: sort each.","items":[{"id":"a","text":"Likes your post"},{"id":"b","text":"Group made to leave you out"},{"id":"c","text":"Tags you in fun stuff"},{"id":"d","text":"Shares your photo to shame you"},{"id":"e","text":"\"Reply now or you're out\""},{"id":"f","text":"Wishes you happy birthday"}],"bins":[{"id":"friend","label":"Real friend","valence":"pos"},{"id":"flag","label":"Frenemy flag","valence":"neg"}],"key":{"a":"friend","b":"flag","c":"friend","d":"flag","e":"flag","f":"friend"},"relearn":"Online, the same flags fly: cheering and tagging are friendship; excluding, shaming and threats are not.","persona":"Reyansh","source":"digital friendships"},
  {"id":"ff-1003","cat":"frenemy-flags","type":"sort","hook":"Control flag, or just normal? Sort fast.","items":[{"id":"a","text":"\"Do my homework or you're out\""},{"id":"b","text":"\"I'd rather play tag today\""},{"id":"c","text":"\"Sit only with me or we're done\""},{"id":"d","text":"\"Can we share the swing?\""},{"id":"e","text":"\"Give me that or I'll tell\""},{"id":"f","text":"\"I don't agree, but okay\""}],"bins":[{"id":"control","label":"Control flag","valence":"neg"},{"id":"ok","label":"Just normal","valence":"pos"}],"key":{"a":"control","b":"ok","c":"control","d":"ok","e":"control","f":"ok"},"relearn":"\"Do this or else\" is control; wanting different things and disagreeing kindly are normal.","persona":"any","source":"control / coercion"},
  {"id":"ff-1004","cat":"frenemy-flags","type":"sort","hook":"Teasing: friendly fun, or a flag? Sort each.","items":[{"id":"a","text":"You both laugh, it stops when you ask"},{"id":"b","text":"It keeps going after you say stop"},{"id":"c","text":"Gentle, you're both smiling"},{"id":"d","text":"Meant to hurt, not share a laugh"},{"id":"e","text":"Only ever about you, never them"},{"id":"f","text":"You can tease back, still kind"}],"bins":[{"id":"fun","label":"Friendly fun","valence":"pos"},{"id":"flag","label":"Frenemy flag","valence":"neg"}],"key":{"a":"fun","b":"flag","c":"fun","d":"flag","e":"flag","f":"fun"},"relearn":"Friendly teasing is shared and stops when you ask; mean teasing aims to hurt.","persona":"any","source":"teasing vs bullying"},
  {"id":"ff-1005","cat":"frenemy-flags","type":"sort","hook":"How did it leave you feeling? Sort the clue.","items":[{"id":"a","text":"Glad and relaxed"},{"id":"b","text":"Small and worn out"},{"id":"c","text":"Safe to be yourself"},{"id":"d","text":"Walking on eggshells"},{"id":"e","text":"Proud they cheered you"},{"id":"f","text":"Tense, waiting for a put-down"}],"bins":[{"id":"good","label":"Feels like a friend","valence":"pos"},{"id":"off","label":"Feels off","valence":"uhoh"}],"key":{"a":"good","b":"off","c":"good","d":"off","e":"good","f":"off"},"relearn":"How a friend leaves you feeling is a clue; glad and safe are good signs, small and tense are not.","persona":"any","source":"emotional cues"},
  {"id":"ff-1006","cat":"frenemy-flags","type":"sort","hook":"Sort the flag by what kind of move it is.","items":[{"id":"a","text":"\"Be my friend or I'll tell\""},{"id":"b","text":"\"Everyone's invited but you\""},{"id":"c","text":"Sweet today, cold tomorrow"},{"id":"d","text":"\"Do exactly what I say\""},{"id":"e","text":"\"You can't sit here, it's ours\""},{"id":"f","text":"Hot one day, cold the next"}],"bins":[{"id":"control","label":"Control","valence":"neg"},{"id":"exclude","label":"Leaving out","valence":"neg"},{"id":"hotcold","label":"Hot-and-cold","valence":"uhoh"}],"key":{"a":"control","b":"exclude","c":"hotcold","d":"control","e":"exclude","f":"hotcold"},"relearn":"Threats are control, shutting you out is exclusion, hot-and-cold keeps you guessing.","persona":"any","source":"relational aggression"},
  {"id":"ff-1007","cat":"frenemy-flags","type":"sort","hook":"Which include you, and which leave you out?","items":[{"id":"a","text":"\"Come sit with us\""},{"id":"b","text":"\"This seat's not for you\""},{"id":"c","text":"\"We saved you a turn\""},{"id":"d","text":"\"We started without you\""},{"id":"e","text":"\"Want to join our game?\""},{"id":"f","text":"\"You're not in our club\""}],"bins":[{"id":"in","label":"Includes you","valence":"pos"},{"id":"out","label":"Leaves you out","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"Real friends make room for you; leaving you out on purpose is an exclusion flag.","persona":"Ananya","source":"exclusion"},
  {"id":"ff-1008","cat":"frenemy-flags","type":"sort","hook":"A real friend's words, or a flag? Sort each.","items":[{"id":"a","text":"\"I'm so happy you got picked!\""},{"id":"b","text":"\"You got picked by luck\""},{"id":"c","text":"\"Tell me about your new friend\""},{"id":"d","text":"\"Drop her or lose me\""},{"id":"e","text":"\"I've got your back\""},{"id":"f","text":"\"Prove you're loyal first\""}],"bins":[{"id":"friend","label":"Real friend","valence":"pos"},{"id":"flag","label":"Frenemy flag","valence":"neg"}],"key":{"a":"friend","b":"flag","c":"friend","d":"flag","e":"friend","f":"flag"},"relearn":"Gladness and having your back are friend signals; put-downs, ultimatums and loyalty-tests are flags.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1009","cat":"frenemy-flags","type":"sort","hook":"A loyalty test, or fair friend stuff?","items":[{"id":"a","text":"\"Pick me or her, right now\""},{"id":"b","text":"\"I'd love it if you came too\""},{"id":"c","text":"\"Skip her party to prove it\""},{"id":"d","text":"\"Hang out whenever you can\""},{"id":"e","text":"\"Say you hate them or we're done\""},{"id":"f","text":"\"It's okay if you're busy\""}],"bins":[{"id":"test","label":"Loyalty test","valence":"neg"},{"id":"fair","label":"Fair and free","valence":"pos"}],"key":{"a":"test","b":"fair","c":"test","d":"fair","e":"test","f":"fair"},"relearn":"Making you prove loyalty by giving up other friends is a flag; real friends leave you free.","persona":"any","source":"control / loyalty tests"},
  {"id":"ff-1010","cat":"frenemy-flags","type":"sort","hook":"Does this build you up, or chip away?","items":[{"id":"a","text":"\"Your idea was great\""},{"id":"b","text":"\"That was a silly thing to say\""},{"id":"c","text":"\"You can do this, try again\""},{"id":"d","text":"Rolls eyes when you speak"},{"id":"e","text":"\"I like hanging out with you\""},{"id":"f","text":"\"No wonder no one picks you\""}],"bins":[{"id":"up","label":"Builds you up","valence":"pos"},{"id":"chip","label":"Chips away","valence":"neg"}],"key":{"a":"up","b":"chip","c":"up","d":"chip","e":"up","f":"chip"},"relearn":"A real friend builds you up; steady put-downs and eye-rolls chip away and are a flag.","persona":"Faizan","source":"belittling / self-worth"},
  {"id":"ff-1011","cat":"frenemy-flags","type":"sort","hook":"How does each move really treat you?","items":[{"id":"a","text":"Listens when you're upset"},{"id":"b","text":"Spills what you told them"},{"id":"c","text":"Shares the last biscuit"},{"id":"d","text":"Takes your things without asking"},{"id":"e","text":"Waits for you after class"},{"id":"f","text":"Ditches you for someone cooler"}],"bins":[{"id":"care","label":"Treats you well","valence":"pos"},{"id":"use","label":"Uses you","valence":"neg"}],"key":{"a":"care","b":"use","c":"care","d":"use","e":"care","f":"use"},"relearn":"Listening, sharing and waiting are care; spilling secrets and ditching you are using-you flags.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1012","cat":"frenemy-flags","type":"branch","hook":"\"Laugh at Faizan's drawing with me, or you're not my friend.\"","options":[{"text":"Laugh along so you don't lose them","consequence":"It hurts Faizan; they push further.","outcome":"gives-in"},{"text":"\"I won't. That's not how friends act.\"","consequence":"You keep your kindness and your own mind.","outcome":"assertive","best":true},{"text":"Go and sit with Faizan instead","consequence":"Faizan feels less alone.","outcome":"ally"}],"debrief":"\"Do this or you're out\" is a control flag.","relearn":"You can refuse an unkind dare and keep real friends.","persona":"Ananya","source":"coercion / bystander"},
  {"id":"ff-1013","cat":"frenemy-flags","type":"branch","hook":"Your friend goes cold whenever you talk to anyone else.","options":[{"text":"Stop talking to others to keep them happy","consequence":"Your circle shrinks.","outcome":"gives-in"},{"text":"\"I can have other friends too. That's okay.\"","consequence":"You name the flag calmly.","outcome":"assertive","best":true},{"text":"Go cold right back to get even","consequence":"A silent war; nobody wins.","outcome":"escalates"}],"debrief":"Going cold to control who you see is a flag.","relearn":"You're allowed many friends; a real one is glad your circle is wide.","persona":"any","source":"control / jealousy"},
  {"id":"ff-1014","cat":"frenemy-flags","type":"branch","hook":"In the class chat: \"send the answers or we'll kick you out.\"","options":[{"text":"Send the answers to stay in","consequence":"They threaten you again.","outcome":"gives-in"},{"text":"\"That's not okay,\" and tell a trusted adult","consequence":"The threat loses power.","outcome":"assertive","best":true},{"text":"Leave the chat without a word","consequence":"Safer, but the flag stays unnamed.","outcome":"avoids"}],"debrief":"Threatened exclusion in a chat is a flag.","relearn":"Being threatened with being kicked out is a flag; telling an adult is brave.","persona":"Reyansh","source":"digital control / safeguarding"},
  {"id":"ff-1015","cat":"frenemy-flags","type":"branch","hook":"A friend says your win 'didn't really count.'","options":[{"text":"Agree it didn't count, to keep peace","consequence":"You shrink; the put-downs continue.","outcome":"gives-in"},{"text":"\"My win counts too. We can both be proud.\"","consequence":"You hold your worth.","outcome":"assertive","best":true},{"text":"Snap that their win was just luck","consequence":"A put-down match; both feel worse.","outcome":"escalates"}],"debrief":"Shrinking your wins is a jealousy flag.","relearn":"A real friend can be glad for you both; competing with your wins is a flag.","persona":"Ananya","source":"jealousy"},
  {"id":"ff-1016","cat":"frenemy-flags","type":"branch","hook":"\"Give me your new pen or I'll tell everyone your secret.\"","options":[{"text":"Hand over the pen quietly","consequence":"It works once, so it happens again.","outcome":"gives-in"},{"text":"\"That's not how friends act,\" and tell an adult","consequence":"The secret stops being a weapon.","outcome":"assertive","best":true},{"text":"Threaten one of their secrets back","consequence":"Trust is gone.","outcome":"escalates"}],"debrief":"Using a secret to make you obey is control.","relearn":"A secret used to threaten you is a flag; telling an adult is brave.","persona":"any","source":"coercion / safeguarding"},
  {"id":"ff-1017","cat":"frenemy-flags","type":"branch","hook":"Your 'friend' started a rumour, then acts normal.","options":[{"text":"Stay quiet and pretend you didn't hear","consequence":"It festers and continues.","outcome":"avoids"},{"text":"Calmly ask them, and watch how they answer","consequence":"Their answer tells you a lot.","outcome":"assertive","best":true},{"text":"Start a rumour about them to get even","consequence":"Two rumours fly; hurt doubles.","outcome":"escalates"}],"debrief":"Hurting you behind your back is a flag.","relearn":"Two-faced moves are a flag; how they answer shows who they are.","persona":"any","source":"relational aggression"},
  {"id":"ff-1018","cat":"frenemy-flags","type":"reflect","hook":"After time with this friend, how do you usually feel?","prompt":"Just notice. There's no wrong answer.","options":["Lighter and glad","A bit small or tired","A real mix of both","I haven't noticed yet"],"affirm":"How a friend leaves you feeling is real information. Whatever you feel, it's worth listening to. 💛","relearn":"If someone often leaves you feeling small, that feeling is a clue worth trusting.","persona":"any","source":"emotional cues"},
  {"id":"ff-1019","cat":"frenemy-flags","type":"reflect","hook":"Lensy wonders: can someone be sweet one day, a frenemy the next?","prompt":"What feels true for you?","options":["Yes, and that switch is confusing","Real friends stay steady","I've felt that on-off before","Still figuring it out"],"affirm":"That on-off feeling is real and tiring, and you deserve friends who are steady-kind. 💛","relearn":"Hot-and-cold ties are stressful; steady kindness is worth holding out for.","persona":"any","source":"ambivalent ties"},
  {"id":"ff-1020","cat":"frenemy-flags","type":"reflect","hook":"Think of a time a friend was unkind. Whose choice was that?","prompt":"Sit with it gently.","options":["Their choice, not mine","I used to think it was my fault","I'm still not sure","It helps to hear it's not mine"],"affirm":"Unkindness is the other person's choice, never something you earned by being yourself. 💛","relearn":"How a friend treats you is about their choices, not your worth.","persona":"Faizan","source":"self-worth"},
  {"id":"ff-1021","cat":"frenemy-flags","type":"reflect","hook":"Reyansh asks: must real friends like all the same things?","prompt":"What do you reckon?","options":["No, different is fine","I worried different was bad","My friends like different stuff","Good to know it's okay"],"affirm":"Liking different games or colours is never a flag. Real friends make room for differences. 💛","relearn":"Disagreeing or liking different things isn't a flag; being used only when convenient is.","persona":"Reyansh","source":"friendship-quality"},
  {"id":"ff-1022","cat":"frenemy-flags","type":"reflect","hook":"When a friend's 'joke' stings, what do you usually do?","prompt":"No right answer, just notice your habit.","options":["Laugh even though it hurt","Go quiet and say nothing","Tell them it wasn't kind","It depends on the day"],"affirm":"Noticing the sting is the first step. You're allowed to say \"that wasn't kind.\" 💛","relearn":"A joke meant to hurt and that keeps going is a flag, even with a smile after.","persona":"any","source":"teasing vs bullying"},
  {"id":"ff-1023","cat":"frenemy-flags","type":"reflect","hook":"Picture a friend who's glad for your wins. How does it feel?","prompt":"Hold that picture a second.","options":["Safe and cheered on","Free to be myself","I want more friends like that","Warm, honestly"],"affirm":"That glad, safe feeling is what a real friend gives. You deserve a circle that feels like this. 💛","relearn":"A wide circle of people who leave you feeling good is a strong one.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1024","cat":"frenemy-flags","type":"match","hook":"Match each frenemy move to what it really is.","pairs":[{"left":"\"Only joking!\" after a dig","right":"Hurting, then hiding it"},{"left":"Sweet today, ignores you tomorrow","right":"Hot-and-cold control"},{"left":"Shares your secret for giggles","right":"Betraying trust"},{"left":"\"Do it or you're out\"","right":"Threatening to exclude you"},{"left":"Sulks when you do well","right":"Competing with your wins"}],"relearn":"Naming a frenemy move takes away its power to confuse you.","persona":"any","source":"relational aggression"},
  {"id":"ff-1025","cat":"frenemy-flags","type":"match","hook":"Match the flag to its move.","pairs":[{"left":"\"Drop your other friends for me\"","right":"Controlling who you see"},{"left":"\"Everyone's invited but you\"","right":"Leaving you out"},{"left":"\"You'd be nothing without me\"","right":"Belittling your worth"},{"left":"\"Lend it or I'll spread a rumour\"","right":"Threatening you"},{"left":"\"Nice when they want a favour\"","right":"Using you"}],"relearn":"Control, exclusion, belittling and threats are the flags to name.","persona":"any","source":"relational aggression"},
  {"id":"ff-1026","cat":"frenemy-flags","type":"match","hook":"Match the move to the feeling it leaves you with.","pairs":[{"left":"They cheer your win","right":"Proud"},{"left":"They mock you in front of others","right":"Small"},{"left":"They blow hot and cold","right":"On edge"},{"left":"They include you","right":"Welcome"},{"left":"They keep your secret safe","right":"Trusted"}],"relearn":"How a move leaves you feeling, proud or small, is a clue to friend or flag.","persona":"any","source":"emotional cues"},
  {"id":"ff-1027","cat":"frenemy-flags","type":"match","hook":"Match the frenemy line to the gentle truth.","pairs":[{"left":"\"You earned that teasing\"","right":"Unkindness is their choice"},{"left":"\"Real friends never fight\"","right":"Friends disagree and repair"},{"left":"\"Be loyal or you're out\"","right":"Real friends leave you free"},{"left":"\"Popular kids can be mean\"","right":"Status never earns hurting"},{"left":"\"Do what I say to stay friends\"","right":"You keep your own mind"}],"relearn":"Each frenemy line has a kinder truth: you stay yours.","persona":"any","source":"friendship-quality / values"},
  {"id":"ff-1028","cat":"frenemy-flags","type":"match","hook":"Match each move to real friend or frenemy flag.","pairs":[{"left":"Saves you a seat","right":"Real friend"},{"left":"Saves a seat then says it's taken","right":"Leaving you out"},{"left":"Keeps your secret","right":"Trustworthy friend"},{"left":"Trades your secret for a laugh","right":"Betraying trust"},{"left":"Glad when you're picked","right":"Cheering you on"}],"relearn":"The same kind word can be a friend move or a flag; watch what they actually do.","persona":"Ananya","source":"friendship-quality"},
  {"id":"ff-1029","cat":"frenemy-flags","type":"match","hook":"Match the online move to what it really is.","pairs":[{"left":"Likes and reposts your art","right":"Cheering you online"},{"left":"Makes a group to leave you out","right":"Online exclusion"},{"left":"Shares your photo to shame you","right":"Embarrassing you on purpose"},{"left":"\"Reply now or you're blocked\"","right":"Threatening to exclude you"},{"left":"Tags you in a fun meme","right":"Including you"}],"relearn":"Online flags match offline: cheering is friendship; threats are not.","persona":"Reyansh","source":"digital friendships"},
  {"id":"ff-1030","cat":"frenemy-flags","type":"match","hook":"Match the move to what it does to you.","pairs":[{"left":"\"Your idea was brilliant\"","right":"Builds you up"},{"left":"Eye-roll when you speak","right":"Chips away quietly"},{"left":"\"Try again, you've got this\"","right":"Cheers you on"},{"left":"\"No wonder you're left out\"","right":"Cuts you down"},{"left":"\"I'm proud of you\"","right":"Lifts you"}],"relearn":"A real friend builds you up; steady eye-rolls and put-downs chip away and are a flag.","persona":"Faizan","source":"belittling / self-worth"},
  {"id":"ff-1031","cat":"frenemy-flags","type":"build","hook":"Lensy: drop only the frenemy flags in the basket.","prompt":"Pick the frenemy flags.","pieces":["cheers your wins","sulks when you win","keeps your secret","spreads your secret","\"do this or you're out\"","includes you","leaves you out on purpose","listens when you're sad"],"mode":"assemble","key":["sulks when you win","spreads your secret","\"do this or you're out\"","leaves you out on purpose"],"relearn":"Sulking at wins, spilling secrets, ultimatums and leaving you out are flags.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1032","cat":"frenemy-flags","type":"build","hook":"Build the control-flag pile.","prompt":"Pick the controlling moves.","pieces":["\"do what I say or we're done\"","\"I'm happy you have other friends\"","\"drop her or you lose me\"","\"it's okay if you're busy\"","\"give me that or I'll tell\"","\"pick me over everyone, now\"","\"let's all play\"","\"I trust you\""],"mode":"assemble","key":["\"do what I say or we're done\"","\"drop her or you lose me\"","\"give me that or I'll tell\"","\"pick me over everyone, now\""],"relearn":"Ultimatums, threats and demands to drop others are control flags; trust and freedom are not.","persona":"any","source":"control / coercion"},
  {"id":"ff-1033","cat":"frenemy-flags","type":"build","hook":"Build the leaving-you-out pile.","prompt":"Pick the leaving-you-out moves.","pieces":["\"come sit with us\"","\"this seat's not for you\"","\"want to join the game?\"","\"we started without you\"","\"you're not in our club\"","\"we saved you a turn\"","\"everyone's invited but you\"","\"there's room for one more\""],"mode":"assemble","key":["\"this seat's not for you\"","\"we started without you\"","\"you're not in our club\"","\"everyone's invited but you\""],"relearn":"Making room for you is friendship; shutting you out on purpose is an exclusion flag.","persona":"Ananya","source":"exclusion"},
  {"id":"ff-1046","cat":"frenemy-flags","type":"build","hook":"Build the 'real friend' jar from these moves.","prompt":"Pick the moves that show a real friend.","pieces":["glad when you win","sulks at your win","keeps your secret","laughs to hurt you","includes you","drops you when you say no","tells the truth kindly","only nice when they need you"],"mode":"assemble","key":["glad when you win","keeps your secret","includes you","tells the truth kindly"],"relearn":"A real friend is glad for you, keeps your secrets, includes you and is honest-but-kind.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1034","cat":"frenemy-flags","type":"build","hook":"Which are jealousy flags? Build that pile.","prompt":"Pick the jealous moves.","pieces":["\"I'm so happy for you!\"","\"your win was just luck\"","sulks at your news","\"tell me all about it\"","downplays the good you do","\"you'll do great\"","competes with your wins","\"proud of you\""],"mode":"assemble","key":["\"your win was just luck\"","sulks at your news","downplays the good you do","competes with your wins"],"relearn":"A real friend celebrates your wins; sulking, downplaying and competing are jealousy flags.","persona":"Ananya","source":"jealousy"},
  {"id":"ff-1035","cat":"frenemy-flags","type":"build","hook":"Drop in the online frenemy flags.","prompt":"Pick the online flags.","pieces":["likes your post","group to exclude you","tags you in fun stuff","shares your photo to shame you","\"reply now or you're out\"","wishes you happy birthday","screenshots to embarrass you","cheers your art"],"mode":"assemble","key":["group to exclude you","shares your photo to shame you","\"reply now or you're out\"","screenshots to embarrass you"],"relearn":"Online flags match offline: excluding, shaming and threats, not likes and cheers.","persona":"Reyansh","source":"digital friendships"},
  {"id":"ff-1036","cat":"frenemy-flags","type":"build","hook":"Build the line that names a flag and keeps you steady.","prompt":"Put the words in order.","pieces":["That's","a control thing,","not friendship —","I keep","my own mind."],"mode":"sequence","key":["That's","a control thing,","not friendship —","I keep","my own mind."],"relearn":"Naming \"that's control, not friendship\" helps you keep your own mind.","persona":"any","source":"assertiveness"},
  {"id":"ff-1037","cat":"frenemy-flags","type":"build","hook":"Build the kind reminder: it's not your fault.","prompt":"Order the words.","pieces":["Their unkindness","is their choice —","not something","I earned","by being me."],"mode":"sequence","key":["Their unkindness","is their choice —","not something","I earned","by being me."],"relearn":"Unkindness is the other person's choice, not something you earn by being yourself.","persona":"Faizan","source":"self-worth"},
  {"id":"ff-1038","cat":"frenemy-flags","type":"role-play","hook":"\"Do my homework or you're out of our group.\"","setup":"Reyansh wants the steady line. Pick yours.","yourLine":[{"text":"\"That's a control thing, not friendship. No.\"","best":true},{"text":"Do it so they don't drop you"},{"text":"\"Fine, but you owe me\""}],"relearn":"\"Do this or you're out\" is a control flag; a calm no keeps your own mind.","persona":"Reyansh","source":"coercion / assertiveness"},
  {"id":"ff-1039","cat":"frenemy-flags","type":"role-play","hook":"Your friend sulks and snips every time you do well.","setup":"Say the calm, clear line.","yourLine":[{"text":"\"I'd love it if you were glad for me too.\"","best":true},{"text":"Stop telling them your good news"},{"text":"\"You're just jealous and sad\""}],"relearn":"You can say you want a friend who's glad for you, without an attack.","persona":"Ananya","source":"jealousy / assertiveness"},
  {"id":"ff-1040","cat":"frenemy-flags","type":"role-play","hook":"\"Drop your new friend or I won't talk to you.\"","setup":"What do you say back, calm and clear?","yourLine":[{"text":"\"I can have more than one friend. That's okay.\"","best":true},{"text":"Promise to drop the new friend"},{"text":"\"Then don't talk to me, see if I care!\""}],"relearn":"You're allowed many friends; naming that calmly answers a control flag.","persona":"any","source":"control / assertiveness"},
  {"id":"ff-1041","cat":"frenemy-flags","type":"role-play","hook":"A friend 'jokes' you're too poor to be in their group.","setup":"Faizan wants a line that holds his worth.","yourLine":[{"text":"\"That's not a joke, and it's not okay.\"","best":true},{"text":"Laugh along and feel awful inside"},{"text":"\"Well your jokes are stupid anyway\""}],"relearn":"A 'joke' meant to shame you is a flag; \"that's not okay\" is strong, not rude.","persona":"Faizan","source":"belittling / assertiveness"},
  {"id":"ff-1042","cat":"frenemy-flags","type":"role-play","hook":"\"Give me your snack or I'll tell everyone your secret.\"","setup":"Say the line that names it.","yourLine":[{"text":"\"That's not how friends act. I'm telling an adult.\"","best":true},{"text":"Hand over the snack and hope it stops"},{"text":"\"I'll tell YOUR secret then\""}],"relearn":"Using your secret to make you obey is a control flag; naming it and telling an adult is brave.","persona":"any","source":"coercion / safeguarding"},
  {"id":"ff-1043","cat":"frenemy-flags","type":"role-play","hook":"Sweet yesterday, freezing you out today.","setup":"Pick a calm, clear thing to say.","yourLine":[{"text":"\"This hot-and-cold is hard for me. Can we talk?\"","best":true},{"text":"Trail after them saying sorry for nothing"},{"text":"Freeze them out twice as hard"}],"relearn":"Naming the hot-and-cold and asking to talk beats chasing or revenge.","persona":"any","source":"hot-and-cold / assertiveness"},
  {"id":"ff-1044","cat":"frenemy-flags","type":"role-play","hook":"In the chat: \"agree with me or we'll kick you out.\"","setup":"What do you type back, calm and clear?","yourLine":[{"text":"\"I can disagree and still be your friend.\"","best":true},{"text":"Agree even though you don't, to stay in"},{"text":"\"Kick me then, losers\""}],"relearn":"Disagreeing isn't a flag; being threatened with exclusion for it is.","persona":"Reyansh","source":"digital control / assertiveness"},
  {"id":"ff-1045","cat":"frenemy-flags","type":"role-play","hook":"A classmate is told \"you can't sit with us, ever.\"","setup":"Be the ally. What do you say to the group?","yourLine":[{"text":"\"There's room for everyone. Come sit here.\"","best":true},{"text":"Stay quiet so they don't turn on you"},{"text":"\"You're all so mean!\" (and start a fight)"}],"relearn":"Leaving someone out on purpose is a flag; \"there's room for everyone\" includes without a war.","persona":"any","source":"exclusion / bystander"},
  {"id":"ff-1080","cat":"good-friend","type":"reflect","hook":"Lensy: a quiet check-in, just for you.","prompt":"When did you last cheer a friend's win?","options":["Today, easily","I had to try","I felt a sulk first","I'm not sure"],"affirm":"Just noticing is a good-friend move. We all sulk sometimes; the noticing is what grows you.","relearn":"Being a good friend includes checking your own moves, kindly.","persona":"any","source":"self-awareness"},
  {"id":"ff-1081","cat":"good-friend","type":"reflect","hook":"Lensy: think of your tiffin-break circle.","prompt":"Who leaves you feeling good after?","options":["My old buddy","A new classmate","A cousin","Still finding them"],"affirm":"Noticing who leaves you glad is how you find your steady-kind people. There's no wrong pick.","relearn":"A few kind, steady friends matter more than a big crowd.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1082","cat":"good-friend","type":"reflect","hook":"Lensy: a friend you used to play with drifted away.","prompt":"How does that sit with you?","options":["A little sad","Mostly okay","I still miss them","I made new ones"],"affirm":"All of those are fine. Friendships can fade and you still turned out fine and kind.","relearn":"Some friendships fade and that's a normal part of life.","persona":"any","source":"social development"},
  {"id":"ff-1083","cat":"good-friend","type":"reflect","hook":"Lensy: you joined a new section this term.","prompt":"What's one small step you could try?","options":["Say hi to someone","Share my colours","Join a game","Sit beside a new kid"],"affirm":"Any one of those is a brave first step. New friends start small, and you've got this.","relearn":"You can always make new friends, one small step at a time.","persona":"any","source":"loneliness / agency"},
  {"id":"ff-1084","cat":"good-friend","type":"reflect","hook":"Lensy: a friendship has been hard lately.","prompt":"Which would help you most right now?","options":["Talk it out","Ask a grown-up","Spend time with others","Take a quiet day"],"affirm":"You know yourself best. Each of these is a kind thing to do for you.","relearn":"Talking it out, asking for help and widening your circle all help.","persona":"any","source":"coping"},
  {"id":"ff-1085","cat":"good-friend","type":"reflect","hook":"Lensy: honest one, no shame.","prompt":"When a friend shines, your first feeling is?","options":["Happy for them","A pinch of envy","Both at once","Depends on the day"],"affirm":"Feeling a pinch is human. Choosing to cheer anyway is the good-friend muscle, and you're building it.","relearn":"Being a good friend includes checking your own moves, kindly.","persona":"any","source":"self-awareness"},
  {"id":"ff-1086","cat":"good-friend","type":"reflect","hook":"Lensy: think about your free time.","prompt":"What feels like richness to you?","options":["One close friend","A few good ones","A big group","My family too"],"affirm":"There's no winning number. Even one or two kind friends is real richness.","relearn":"A few kind, steady friends matter more than a big crowd.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1087","cat":"good-friend","type":"reflect","hook":"Lensy: one kid keeps being unkind to you.","prompt":"What does your gut say to do?","options":["Try once more","Take some space","Find kinder friends","Tell a grown-up"],"affirm":"Listen to that gut. Stepping back from steady unkindness is self-respect, never failing.","relearn":"You're allowed to step back from a friendship that keeps hurting you.","persona":"any","source":"boundaries / wellbeing"},
  {"id":"ff-1088","cat":"good-friend","type":"reflect","hook":"Lensy: you saw a new kid sitting alone at PT.","prompt":"What pull do you feel?","options":["Go say hi","Wave them over","Feel shy myself","Ask a friend to come too"],"affirm":"Every one of those can open a door. Including a lonely kid is one of the kindest moves there is.","relearn":"Widening your circle is a real good-friend skill.","persona":"any","source":"inclusion"},
  {"id":"ff-1089","cat":"good-friend","type":"reflect","hook":"Lensy: a friend keeps your secrets and is glad for you.","prompt":"What do you want to do back?","options":["Tell them thanks","Keep their secrets too","Cheer their wins","Just stay close"],"affirm":"Lovely. Tending a steady-kind friend back is exactly how good friendships last.","relearn":"A few kind, steady friends matter more than a big crowd.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1090","cat":"good-friend","type":"reflect","hook":"Lensy: you slipped and left someone out yesterday.","prompt":"What feels right today?","options":["Say sorry","Invite them in","Notice it next time","All of these"],"affirm":"We all slip. Owning it gently, with no shame, is what a real friend does.","relearn":"Being a good friend includes checking your own moves, kindly.","persona":"any","source":"self-awareness"},
  {"id":"ff-1091","cat":"good-friend","type":"reflect","hook":"Lensy: your best friend is moving cities.","prompt":"What might help the missing feeling?","options":["Make a card","Stay in touch","Try a new friend","Let myself be sad"],"affirm":"All of these are okay. You can miss them and still slowly find new friends.","relearn":"You can always make new friends, one small step at a time.","persona":"any","source":"loneliness / agency"},
  {"id":"ff-1092","cat":"good-friend","type":"reflect","hook":"Lensy: think of a friend who is honest-but-kind with you.","prompt":"How do they make you feel?","options":["Safe","Understood","Cared for","All of these"],"affirm":"That's a real friend. Notice that feeling; it's the clue to who's worth your time.","relearn":"A real friend leaves you feeling safe, glad and cared for.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1093","cat":"good-friend","type":"reflect","hook":"Lensy: a small worry about a friend has been bottling up.","prompt":"What could you do with it?","options":["Tell the friend","Tell a grown-up","Write it down","Talk to a cousin"],"affirm":"Letting a worry out, any of these ways, beats keeping it inside. You're being kind to yourself.","relearn":"Talking it out and asking for help beat bottling it up.","persona":"any","source":"coping"},
  {"id":"ff-1094","cat":"good-friend","type":"reflect","hook":"Lensy: you've learned a lot about friends.","prompt":"What will you carry home today?","options":["I can cheer wins","I can step back","I can include kids","I deserve kind friends"],"affirm":"Carry it proudly. You're growing into the kind of friend everyone is lucky to have.","relearn":"You can be a good friend and hold out for steady-kind people.","persona":"any","source":"consolidation"},
  {"id":"ff-1095","cat":"good-friend","type":"reflect","hook":"Lensy: Ananya wonders if she's a good friend.","prompt":"What makes you wonder too, sometimes?","options":["I tease a bit","I get jealous","I forget to listen","I'm pretty kind"],"affirm":"Wondering is the sign of a good friend, not a bad one. No shame, just a gentle nudge.","relearn":"Being a good friend includes checking your own moves, kindly.","persona":"Ananya","source":"self-awareness"},
  {"id":"ff-1096","cat":"good-friend","type":"reflect","hook":"Lensy: a friendship ended and you felt it was your fault.","prompt":"What's truer to tell yourself?","options":["People change","No one was bad","I can make new ones","I learned something"],"affirm":"All true. An ending isn't always a failure, and it doesn't make you a bad friend.","relearn":"Some friendships fade and that's a normal part of life.","persona":"any","source":"social development"},
  {"id":"ff-1097","cat":"good-friend","type":"reflect","hook":"Lensy: your crowd is big but no one feels close.","prompt":"What might you wish for instead?","options":["One real friend","A couple of close ones","To be heard","To feel safe"],"affirm":"That wish is wise. A few kind, steady friends beat a big crowd that doesn't see you.","relearn":"A few kind, steady friends matter more than a big crowd.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1098","cat":"good-friend","type":"branch","hook":"A kid you like keeps mocking you, then acts sweet, then mocks again.","options":[{"text":"Keep waiting for the sweet days","consequence":"The hot-and-cold keeps hurting you.","outcome":"stuck"},{"text":"Spend more time with steady-kind friends","consequence":"You feel calmer and safer now.","outcome":"wise","best":true}],"debrief":"Stepping back from hot-and-cold treatment isn't giving up; it's choosing your peace.","relearn":"You're allowed to step back from a friendship that keeps hurting you.","persona":"any","source":"boundaries / wellbeing"},
  {"id":"ff-1099","cat":"good-friend","type":"branch","hook":"You used to be close, but lately your friend rarely wants to play.","options":[{"text":"Decide they hate you and feel awful","consequence":"That feels heavy and may not be true.","outcome":"stuck"},{"text":"Give it time and also play with others","consequence":"Friendships shift; you stay open and stay okay.","outcome":"calm","best":true}],"debrief":"Some friendships fade as people change; that's normal, and you can make new ones.","relearn":"Some friendships fade and that's a normal part of life.","persona":"any","source":"social development"},
  {"id":"ff-1100","cat":"good-friend","type":"branch","hook":"A new girl just moved in and sits alone at lunch.","options":[{"text":"Wait, in case she's not nice","consequence":"She stays alone; you both miss a friend.","outcome":"missed"},{"text":"Ask her to share your bench and game","consequence":"She lights up; your circle just grew kinder.","outcome":"warm","best":true}],"debrief":"Including a lonely or new kid is one of the easiest ways to be a real friend.","relearn":"Widening your circle is a real good-friend skill.","persona":"any","source":"inclusion"},
  {"id":"ff-1101","cat":"good-friend","type":"branch","hook":"Your friend says they're being bullied, then says \"don't tell anyone.\"","options":[{"text":"Stay silent because they asked","consequence":"The bullying keeps going.","outcome":"risky"},{"text":"Tell a trusted grown-up so it can stop","consequence":"Caring; bullying needs grown-up help.","outcome":"caring","best":true}],"debrief":"For bullying, tell a trusted grown-up even if a friend asks you not to.","relearn":"For bullying, tell a trusted adult; it's brave, not tattling.","persona":"Faizan","source":"bullying"},
  {"id":"ff-1102","cat":"good-friend","type":"branch","hook":"You realise you've been a bit unkind to a quieter classmate.","options":[{"text":"Pretend you never noticed","consequence":"Nothing changes and the gap stays.","outcome":"stuck"},{"text":"Quietly say sorry and sit with them","consequence":"They feel seen; you feel lighter too.","outcome":"repair","best":true}],"debrief":"We all slip. Noticing your own move and mending it, with no shame, is a good-friend skill.","relearn":"Being a good friend includes checking your own moves, kindly.","persona":"any","source":"self-awareness"},
  {"id":"ff-1103","cat":"good-friend","type":"branch","hook":"You only have one friend and they're absent today.","options":[{"text":"Sit alone and decide you have no one","consequence":"The day feels lonely and stuck.","outcome":"stuck"},{"text":"Try joining one group game today","consequence":"One small step; you might find another friend.","outcome":"hopeful","best":true}],"debrief":"New friendships start with small, brave steps, even on a lonely day.","relearn":"You can always make new friends, one small step at a time.","persona":"any","source":"loneliness / agency"},
  {"id":"ff-1104","cat":"good-friend","type":"branch","hook":"A big group wants you, but they're mean to a kid you like.","options":[{"text":"Join them and stay quiet about it","consequence":"You fit in but feel uneasy inside.","outcome":"uneasy"},{"text":"Keep your few kind friends instead","consequence":"Smaller circle, but it feels honest and safe.","outcome":"steady","best":true}],"debrief":"A few kind, steady friends matter more than a big crowd you don't feel right in.","relearn":"A few kind, steady friends matter more than a big crowd.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1105","cat":"good-friend","type":"branch","hook":"A worry about a friend has been sitting in your chest for days.","options":[{"text":"Keep it all inside","consequence":"The worry grows heavier and stays stuck.","outcome":"stuck"},{"text":"Tell a parent or teacher you trust","consequence":"Saying it out loud makes it lighter and clearer.","outcome":"relief","best":true}],"debrief":"Talking it out and asking for help beat bottling it up when friendship is hard.","relearn":"Talking it out and asking for help beat bottling it up.","persona":"any","source":"coping"},
  {"id":"ff-1106","cat":"good-friend","type":"branch","hook":"Ananya notices she keeps interrupting her friend's stories.","options":[{"text":"Decide it's not a big deal","consequence":"Her friend slowly stops sharing.","outcome":"missed"},{"text":"Try really listening till they finish","consequence":"Her friend opens up more; they feel closer.","outcome":"closer","best":true}],"debrief":"Listening well is a good-friend move you can practise; noticing your own slip is the start.","relearn":"Being a good friend includes checking your own moves, kindly.","persona":"Ananya","source":"self-awareness"},
  {"id":"ff-1107","cat":"good-friend","type":"branch","hook":"A friend copies everything you do and gets upset if you say stop.","options":[{"text":"Drop them and feel guilty","consequence":"It feels harsh and the guilt lingers.","outcome":"harsh"},{"text":"Keep some space and stay kind","consequence":"You set a gentle limit, still kind.","outcome":"balanced","best":true}],"debrief":"You can keep a gentle limit and stay kind; a little space isn't being mean.","relearn":"You're allowed to step back from a friendship that keeps hurting you.","persona":"any","source":"boundaries / wellbeing"},
  {"id":"ff-1108","cat":"good-friend","type":"branch","hook":"Two of your friends fell out and each wants you to pick them.","options":[{"text":"Pick one and drop the other","consequence":"Now three of you feel hurt instead of two.","outcome":"hurt"},{"text":"Stay a kind friend to both","consequence":"You don't add to the fight; both feel your care.","outcome":"fair","best":true}],"debrief":"You don't have to pick a side to be a good friend to both when friends fall out.","relearn":"You can be a good friend to both when friends fall out.","persona":"any","source":"loyalty"},
  {"id":"ff-1109","cat":"good-friend","type":"branch","hook":"Your friend keeps getting picked on by an older kid in the lane.","options":[{"text":"Keep it secret to seem loyal","consequence":"The older kid keeps picking on them.","outcome":"risky"},{"text":"Tell a grown-up at home or school","consequence":"Caring; a bigger kid bullying needs adult help.","outcome":"caring","best":true}],"debrief":"For bullying, telling a trusted grown-up is how you truly help; it's brave, not tattling.","relearn":"For bullying, tell a trusted adult; it's brave, not tattling.","persona":"any","source":"bullying"},
  {"id":"ff-1110","cat":"good-friend","type":"branch","hook":"You feel left out as your two friends now do everything together.","options":[{"text":"Sulk and wait to be noticed","consequence":"You feel worse and more left out.","outcome":"stuck"},{"text":"Ask to join, and also meet others","consequence":"You speak up and widen your circle.","outcome":"open","best":true}],"debrief":"Speaking up gently and widening your circle both help when you feel lonely.","relearn":"Talking it out and widening your circle help when friendship is hard.","persona":"any","source":"coping"},
  {"id":"ff-1111","cat":"good-friend","type":"branch","hook":"A friend who moved away barely replies to your messages now.","options":[{"text":"Spam them till they answer","consequence":"They feel pushed and reply even less.","outcome":"pushy"},{"text":"Keep one warm message and make local friends","consequence":"You stay kind and also build friends nearby.","outcome":"wise","best":true}],"debrief":"Some friendships fade with distance; that's normal, and new friends can grow close to home.","relearn":"Some friendships fade and that's a normal part of life.","persona":"any","source":"social development"},
  {"id":"ff-1112","cat":"good-friend","type":"strike-rewrite","hook":"\"A good friend never needs a break from anyone.\"","myth":{"un":"If you step back from a friend, you're a bad friend.","re":"You're allowed to step back from a friendship that keeps hurting you.","why":"Caring for your own feelings is self-respect, and a real friendship doesn't keep hurting you."},"relearn":"Stepping back from steady unkindness is self-respect, not failing.","persona":"any","source":"boundaries / wellbeing"},
  {"id":"ff-1113","cat":"good-friend","type":"strike-rewrite","hook":"\"Real friends stay best friends forever, no matter what.\"","myth":{"un":"If a friendship changes or fades, something went wrong.","re":"Some friendships fade and that's a normal part of life.","why":"People grow and change as they get older, so friendships can shift without anyone being bad."},"relearn":"A friendship fading doesn't make you, or them, a bad friend.","persona":"any","source":"social development"},
  {"id":"ff-1114","cat":"good-friend","type":"strike-rewrite","hook":"\"Telling a grown-up about bullying is being a snitch.\"","myth":{"un":"Telling a grown-up your friend is bullied is tattling.","re":"For bullying, telling a trusted grown-up is how you truly help.","why":"Bullying is too big to fix alone, so getting a caring adult is brave, not tattling."},"relearn":"Help-seeking about bullying is brave, not tattling.","persona":"any","source":"bullying"},
  {"id":"ff-1115","cat":"good-friend","type":"strike-rewrite","hook":"\"You should keep every friend you've ever had.\"","myth":{"un":"A real friend holds on to all their friends forever.","re":"A few kind, steady friends matter more than a big crowd.","why":"How a friend treats you matters more than how many friends you count."},"relearn":"Even one or two kind friends is real richness.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1116","cat":"good-friend","type":"strike-rewrite","hook":"\"Once you've lost a friend, it's too late to make new ones.\"","myth":{"un":"If you lose a friend, you'll never find another.","re":"You can always make new friends, one small step at a time.","why":"A small kind move, like sharing or saying hi, is how most new friendships begin."},"relearn":"New friendships start with small, brave steps.","persona":"any","source":"loneliness / agency"},
  {"id":"ff-1117","cat":"good-friend","type":"strike-rewrite","hook":"\"Good kids are never unkind, so checking yourself means you're bad.\"","myth":{"un":"If you ever slip and act unkind, you're a bad friend.","re":"Being a good friend includes checking your own moves, kindly.","why":"Everyone slips sometimes, and noticing it with no shame is exactly what a real friend does."},"relearn":"We all slip; no shame, just a nudge.","persona":"any","source":"self-awareness"},
  {"id":"ff-1118","cat":"good-friend","type":"strike-rewrite","hook":"\"If you feel lonely, you should just keep it to yourself.\"","myth":{"un":"Talking about a friendship problem only makes it worse.","re":"Talking it out and asking for help beat bottling it up.","why":"Saying a worry out loud to someone you trust often makes it feel lighter and clearer."},"relearn":"Talking it out and asking for help beat bottling it up.","persona":"any","source":"coping"},
  {"id":"ff-1119","cat":"good-friend","type":"strike-rewrite","hook":"\"A kind kid should let friends treat them however they like.\"","myth":{"un":"Being kind means putting up with anything a friend does.","re":"You can be kind and still step back from treatment that keeps hurting you.","why":"Kindness includes kindness to yourself, and a real friend doesn't keep hurting you."},"relearn":"Stepping back from steady unkindness is self-respect.","persona":"any","source":"boundaries / wellbeing"},
  {"id":"ff-1120","cat":"good-friend","type":"strike-rewrite","hook":"\"You have to choose a side when two friends fight.\"","myth":{"un":"If two friends fall out, you must pick one of them.","re":"You can be a good friend to both when friends fall out.","why":"Staying kind to each one without joining the fight helps everyone calm down."},"relearn":"You don't have to pick a side to be a good friend.","persona":"any","source":"loyalty"},
  {"id":"ff-1121","cat":"good-friend","type":"sort","hook":"Sort each one: a quality friend, or just a crowd-filler?","items":[{"id":"a","text":"Stands by you in hard times"},{"id":"b","text":"Only around when it's fun"},{"id":"c","text":"Remembers what matters to you"},{"id":"d","text":"Forgets you when others are near"},{"id":"e","text":"Glad to see you do well"},{"id":"f","text":"Keeps a tally of favours"}],"bins":[{"id":"quality","label":"Quality friend","valence":"pos"},{"id":"crowd","label":"Just a crowd","valence":"uhoh"}],"key":{"a":"quality","b":"crowd","c":"quality","d":"crowd","e":"quality","f":"crowd"},"relearn":"A few kind, steady friends who stand by you beat a big crowd that drifts.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1122","cat":"good-friend","type":"sort","hook":"Sort each move: good-friend habit, or a slip to notice?","items":[{"id":"a","text":"Cheer a friend's win"},{"id":"b","text":"Sulk when they win"},{"id":"c","text":"Keep their secret"},{"id":"d","text":"Tease till it stings"},{"id":"e","text":"Include a lonely kid"},{"id":"f","text":"Leave someone out"}],"bins":[{"id":"habit","label":"Kind habit","valence":"pos"},{"id":"slip","label":"A slip","valence":"uhoh"}],"key":{"a":"habit","b":"slip","c":"habit","d":"slip","e":"habit","f":"slip"},"relearn":"Cheering, keeping secrets and including others are kind habits; the rest are slips to notice.","persona":"any","source":"self-awareness"},
  {"id":"ff-1123","cat":"good-friend","type":"sort","hook":"Sort each one: a true friend, or hard on your heart?","items":[{"id":"a","text":"Glad for your wins"},{"id":"b","text":"Mocks then acts sweet"},{"id":"c","text":"Listens when you're sad"},{"id":"d","text":"Only nice when alone"},{"id":"e","text":"Keeps your trust"},{"id":"f","text":"Sulks at your news"}],"bins":[{"id":"true","label":"True friend","valence":"pos"},{"id":"hard","label":"Hard on you","valence":"neg"}],"key":{"a":"true","b":"hard","c":"true","d":"hard","e":"true","f":"hard"},"relearn":"A true friend is glad for you, listens and keeps your trust; the rest leave you feeling small.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1124","cat":"good-friend","type":"sort","hook":"Sort each step you could take when a friend is bullied.","items":[{"id":"a","text":"Tell a trusted grown-up"},{"id":"b","text":"Keep it a secret"},{"id":"c","text":"Stay near your friend"},{"id":"d","text":"Laugh along to fit in"},{"id":"e","text":"Tell a teacher you trust"},{"id":"f","text":"Pretend you didn't see"}],"bins":[{"id":"helps","label":"Helps your friend","valence":"tell"},{"id":"leaves","label":"Leaves them alone","valence":"neg"}],"key":{"a":"helps","b":"leaves","c":"helps","d":"leaves","e":"helps","f":"leaves"},"relearn":"Telling a trusted grown-up and staying near help; secrets and pretending leave a friend alone.","persona":"any","source":"bullying"},
  {"id":"ff-1125","cat":"good-friend","type":"sort","hook":"Sort each thought when a friendship ends or fades.","items":[{"id":"a","text":"People grow and change"},{"id":"b","text":"It's all my fault"},{"id":"c","text":"I can make new friends"},{"id":"d","text":"I'll never have a friend"},{"id":"e","text":"I learned something"},{"id":"f","text":"I must be unlovable"}],"bins":[{"id":"kind","label":"Kind & true","valence":"pos"},{"id":"untrue","label":"Untrue & heavy","valence":"neg"}],"key":{"a":"kind","b":"untrue","c":"kind","d":"untrue","e":"kind","f":"untrue"},"relearn":"Fading friendships aren't your fault; people change, and you can make new friends.","persona":"any","source":"social development"},
  {"id":"ff-1126","cat":"good-friend","type":"sort","hook":"Sort each way to grow your circle of friends.","items":[{"id":"a","text":"Say hi to a new kid"},{"id":"b","text":"Wait to be invited"},{"id":"c","text":"Share your game"},{"id":"d","text":"Only stick to one friend"},{"id":"e","text":"Join a club at school"},{"id":"f","text":"Ignore everyone new"}],"bins":[{"id":"opens","label":"Opens doors","valence":"pos"},{"id":"closes","label":"Keeps you stuck","valence":"uhoh"}],"key":{"a":"opens","b":"closes","c":"opens","d":"closes","e":"opens","f":"closes"},"relearn":"Saying hi, sharing and joining in open doors; waiting and shutting out keep you stuck.","persona":"any","source":"inclusion"},
  {"id":"ff-1127","cat":"good-friend","type":"sort","hook":"Sort each one: self-respect, or just being unkind?","items":[{"id":"a","text":"Take space from steady cruelty"},{"id":"b","text":"Ignore a friend to punish them"},{"id":"c","text":"Choose calmer friends"},{"id":"d","text":"Spread mean stories"},{"id":"e","text":"Say a gentle no"},{"id":"f","text":"Drop a friend with no word"}],"bins":[{"id":"respect","label":"Self-respect","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"respect","b":"unkind","c":"respect","d":"unkind","e":"respect","f":"unkind"},"relearn":"Taking space from cruelty and choosing calmer friends is self-respect; payback and gossip aren't.","persona":"any","source":"boundaries / wellbeing"},
  {"id":"ff-1128","cat":"good-friend","type":"role-play","hook":"A new boy is standing alone by the wall at games period.","setup":"What's a warm way to bring him in?","yourLine":[{"text":"\"We're starting kho-kho, come join our team!\"","best":true},{"text":"\"You can play if you really want to, I guess.\""},{"text":"Wait and hope he joins on his own"}],"relearn":"A warm, specific invite is the kindest door to open for a lonely kid.","persona":"any","source":"inclusion"},
  {"id":"ff-1129","cat":"good-friend","type":"role-play","hook":"You snapped at your friend and now feel bad about it.","setup":"What's a good-friend thing to say?","yourLine":[{"text":"\"I'm sorry I snapped. That wasn't fair to you.\"","best":true},{"text":"\"You kind of made me do it, na.\""},{"text":"Say nothing and hope they forget"}],"relearn":"Owning your own slip, with no shame, is exactly what a good friend does.","persona":"any","source":"self-awareness"},
  {"id":"ff-1130","cat":"good-friend","type":"role-play","hook":"Your friend just won the class quiz and you feel a little jealous.","setup":"What could you choose to say?","yourLine":[{"text":"\"You were brilliant up there, well done!\"","best":true},{"text":"\"It was an easy quiz anyway.\""},{"text":"Stay quiet and look away"}],"relearn":"Choosing to cheer a friend's win, even past a jealous pinch, is the good-friend muscle.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1131","cat":"good-friend","type":"role-play","hook":"A friend keeps teasing you in a way that stings, then laughs it off.","setup":"What's a calm, self-respecting line?","yourLine":[{"text":"\"That's not funny to me. Please stop.\"","best":true},{"text":"\"Ha ha, yeah, whatever you say.\""},{"text":"Walk off without a word"}],"relearn":"A calm, clear line is self-respect; if it keeps hurting, you can step back too.","persona":"Reyansh","source":"boundaries / wellbeing"},
  {"id":"ff-1132","cat":"good-friend","type":"role-play","hook":"Your friend is upset that an older kid keeps bullying them.","setup":"What's a caring thing to say?","yourLine":[{"text":"\"Let's tell ma'am together, she can help.\"","best":true},{"text":"\"Just ignore it, maybe it'll stop.\""},{"text":"\"Don't tell anyone, it'll get worse.\""}],"relearn":"For bullying, going to a trusted grown-up together is how you truly help.","persona":"Faizan","source":"bullying"},
  {"id":"ff-1133","cat":"good-friend","type":"role-play","hook":"A new kid asks shyly if she can sit with you and your friends.","setup":"What's the warmest reply?","yourLine":[{"text":"\"Of course, there's room right here!\"","best":true},{"text":"\"Hmm, maybe, if there's space.\""},{"text":"Look at your friends and shrug"}],"relearn":"A warm yes makes a new kid feel they belong; that's an easy good-friend move.","persona":"any","source":"inclusion"},
  {"id":"ff-1134","cat":"good-friend","type":"role-play","hook":"You feel left out as your two friends pair up for everything.","setup":"What's a kind, honest line to try?","yourLine":[{"text":"\"I miss playing too. Can I join you both?\"","best":true},{"text":"\"Fine, I didn't want to play anyway.\""},{"text":"Sulk quietly and wait"}],"relearn":"Speaking up gently beats sulking when you feel left out.","persona":"any","source":"coping"},
  {"id":"ff-1135","cat":"good-friend","type":"build","hook":"Build your good-friend kit to carry to school.","prompt":"Pick the moves a real friend makes.","pieces":["cheer their wins","keep their secrets","include a lonely kid","tease till it stings","listen when they're sad","leave people out"],"mode":"assemble","key":["cheer their wins","keep their secrets","include a lonely kid","listen when they're sad"],"relearn":"Cheering, keeping trust, including others and listening are the moves of a real friend.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1136","cat":"good-friend","type":"build","hook":"Build a plan for when a friendship feels hard.","prompt":"Put the helpful steps in order.","pieces":["take a calm breath","name what's bothering you","talk it out or ask for help","choose a kind next step"],"mode":"sequence","key":["take a calm breath","name what's bothering you","talk it out or ask for help","choose a kind next step"],"relearn":"Cool down, name it, talk it out or ask for help, then choose a kind step.","persona":"any","source":"coping"},
  {"id":"ff-1137","cat":"good-friend","type":"build","hook":"Build your kit for welcoming a new kid.","prompt":"Pick the moves that help them belong.","pieces":["say hi by name","ask them to join","share your game","ignore them","share a snack","whisper about them"],"mode":"assemble","key":["say hi by name","ask them to join","share your game","share a snack"],"relearn":"Saying hi, inviting, sharing your game and a snack help a new kid belong.","persona":"any","source":"inclusion"},
  {"id":"ff-1138","cat":"good-friend","type":"build","hook":"Build a plan for helping a friend who's being bullied.","prompt":"Put the brave steps in order.","pieces":["stay close to your friend","tell them it's not their fault","go to a trusted grown-up","let the grown-up help"],"mode":"sequence","key":["stay close to your friend","tell them it's not their fault","go to a trusted grown-up","let the grown-up help"],"relearn":"Stay close, remind them it's not their fault, then bring in a trusted grown-up.","persona":"any","source":"bullying"},
  {"id":"ff-1139","cat":"good-friend","type":"build","hook":"Build a reminder for after a friendship ends.","prompt":"Pick the kind, true things to remember.","pieces":["people grow and change","it's not all my fault","I can make new friends","I must be unlovable","I'll never be liked again","no one was a bad kid"],"mode":"assemble","key":["people grow and change","it's not all my fault","I can make new friends","no one was a bad kid"],"relearn":"People change, it's not your fault, no one's a bad kid, and new friends can come.","persona":"any","source":"social development"},
  {"id":"ff-1140","cat":"good-friend","type":"build","hook":"Build your self-check for being a good friend.","prompt":"Pick the gentle questions worth asking.","pieces":["Did I cheer their win?","Did I really listen?","Did I include people?","How can I shame myself?","Did I keep their trust?","How do I win the most?"],"mode":"assemble","key":["Did I cheer their win?","Did I really listen?","Did I include people?","Did I keep their trust?"],"relearn":"A kind self-check asks about cheering, listening, including and trust, with no shame.","persona":"any","source":"self-awareness"},
  {"id":"ff-1141","cat":"good-friend","type":"build","hook":"Build a plan for taking gentle space from a hurtful friend.","prompt":"Put the steps in a kind order.","pieces":["notice it keeps hurting","tell yourself it's not my fault","spend more time with kind friends","stay polite, not cruel"],"mode":"sequence","key":["notice it keeps hurting","tell yourself it's not my fault","spend more time with kind friends","stay polite, not cruel"],"relearn":"Notice the hurt, drop the blame, lean on kind friends, and stay polite, not cruel.","persona":"any","source":"boundaries / wellbeing"},
  {"id":"ff-1142","cat":"good-friend","type":"match","hook":"Match each good-friend move to what it gives a friend.","pairs":[{"left":"Cheer their win","right":"They feel proud, not alone"},{"left":"Keep their secret","right":"They feel they can trust you"},{"left":"Include a new kid","right":"They feel they belong"},{"left":"Listen when they're sad","right":"They feel understood"},{"left":"Say a gentle sorry","right":"The fall-out can mend"}],"relearn":"Good-friend moves each give a friend something real.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1143","cat":"good-friend","type":"match","hook":"Match each tricky moment to a kind next step.","pairs":[{"left":"A friend keeps hurting you","right":"Take gentle space"},{"left":"A new kid sits alone","right":"Ask them to join"},{"left":"A friend is being bullied","right":"Tell a trusted grown-up"},{"left":"You snapped at a friend","right":"Say a real sorry"},{"left":"A worry is bottling up","right":"Talk it out with someone"}],"relearn":"Each tricky moment has a kind, doable next step.","persona":"any","source":"coping"},
  {"id":"ff-1144","cat":"good-friend","type":"match","hook":"Match each gentle truth to the worry it answers.","pairs":[{"left":"A friendship faded","right":"People grow and change"},{"left":"I slipped and was unkind","right":"We all slip; just notice it"},{"left":"My friend moved away","right":"I can make new friends slowly"},{"left":"My crowd feels empty","right":"A few kind friends is richness"},{"left":"I took space from a friend","right":"That's self-respect, not failing"}],"relearn":"A gentle truth eases each worry.","persona":"any","source":"social development"},
  {"id":"ff-1145","cat":"good-friend","type":"match","hook":"Match each friend you describe to how they leave you feeling.","pairs":[{"left":"Glad when you do well","right":"Proud and seen"},{"left":"Listens to your worries","right":"Understood"},{"left":"Keeps your secrets","right":"Safe to trust"},{"left":"Includes you every time","right":"You belong"},{"left":"Honest but always kind","right":"Cared for"}],"relearn":"A real friend leaves you feeling seen and safe.","persona":"any","source":"friendship-quality"},
  {"id":"ff-1146","cat":"good-friend","type":"match","hook":"Match each step of helping a bullied friend to why it matters.","pairs":[{"left":"Stay close to them","right":"They aren't alone"},{"left":"Say it's not your fault","right":"They stop blaming themselves"},{"left":"Tell a trusted grown-up","right":"It can actually stop"},{"left":"Keep being their friend","right":"They feel supported"},{"left":"Don't laugh along","right":"You don't add to the hurt"}],"relearn":"Each step of helping a bullied friend matters.","persona":"any","source":"bullying"},
  {"id":"ff-1147","cat":"good-friend","type":"match","hook":"Match each small step to the new friend it might bring.","pairs":[{"left":"Say hi to a new kid","right":"A first hello back"},{"left":"Share your colours","right":"A drawing buddy"},{"left":"Join a school club","right":"Friends with a shared hobby"},{"left":"Invite someone to play","right":"A teammate at break"},{"left":"Sit beside a quiet kid","right":"A calm, kind friend"}],"relearn":"Small friendly steps each open a new friend.","persona":"any","source":"inclusion"},
  {"id":"ff-1148","cat":"good-friend","type":"match","hook":"Match each thing you can carry to what it sounds like.","pairs":[{"left":"Cheer wins","right":"\"I'm so happy for you!\""},{"left":"Set a kind limit","right":"\"Please stop, I don't like that.\""},{"left":"Welcome someone","right":"\"Come sit with us!\""},{"left":"Ask for help","right":"\"Ma'am, my friend needs help.\""},{"left":"Repair a slip","right":"\"I'm sorry, that was unfair.\""}],"relearn":"Each kind move has words you can actually say.","persona":"any","source":"consolidation"},
  {"id":"ff-1149","cat":"good-friend","type":"match","hook":"Match each good-friend habit to a moment it fits.","pairs":[{"left":"Listen fully","right":"A friend shares bad news"},{"left":"Step back gently","right":"Someone keeps being cruel"},{"left":"Stay kind to both","right":"Two friends fall out"},{"left":"Make the first move","right":"A new kid stands alone"},{"left":"Check your own moves","right":"You wonder if you slipped"}],"relearn":"Each good-friend habit fits a real moment.","persona":"any","source":"self-awareness"},
  {"id":"ff-1170","cat":"real-friend","type":"build","persona":"any","source":"friendship-quality research","hook":"Lensy: pack a tiffin a real friend would share.","prompt":"Drop in what a real friend offers.","pieces":["saves you a roti","waits for you at the gate","laughs with you, not at you","copies your homework off you","cheers your kabaddi goal","only sits with you if no one cooler is free"],"mode":"assemble","key":["saves you a roti","waits for you at the gate","laughs with you, not at you","cheers your kabaddi goal"],"relearn":"A real friend shares, waits for you, and is glad when you do well."},
  {"id":"ff-1171","cat":"real-friend","type":"build","persona":"Ananya","source":"friendship-quality","hook":"Build the kind of friend you'd want on a bad day.","prompt":"Pick what helps when you're low.","pieces":["sits with you in silence","reminds you it'll pass","tells the whole class you cried","listens without fixing","keeps what you told them","teases you about it later"],"mode":"assemble","key":["sits with you in silence","reminds you it'll pass","listens without fixing","keeps what you told them"],"relearn":"In hard moments a real friend listens, stays, and keeps your trust."},
  {"id":"ff-1172","cat":"real-friend","type":"build","persona":"any","source":"inclusion","hook":"Make a game everyone can join.","prompt":"Pick the moves that widen the circle.","pieces":["ask the new girl to be on your team","explain the rules to her","start before she's ready","keep the slow runner in","change sides so it's fair","leave out whoever's bad at it"],"mode":"assemble","key":["ask the new girl to be on your team","explain the rules to her","keep the slow runner in","change sides so it's fair"],"relearn":"Including everyone, even the new or slower kid, is being a real friend."},
  {"id":"ff-1173","cat":"real-friend","type":"build","persona":"any","source":"friendship-quality","hook":"What makes a friend feel safe to be around?","prompt":"Pick what builds that safe feeling.","pieces":["they don't laugh at your mistakes","they keep your secret","they tell you if you mess up, kindly","they share your news with everyone","they stick up for you","they go cold when you say no"],"mode":"assemble","key":["they don't laugh at your mistakes","they keep your secret","they tell you if you mess up, kindly","they stick up for you"],"relearn":"A real friend leaves you feeling safe, understood and cared for."},
  {"id":"ff-1174","cat":"real-friend","type":"build","persona":"Faizan","source":"belonging","hook":"Lensy: a friend who'd have your back at school.","prompt":"Drop in the back-having moves.","pieces":["sits beside you when others won't","says 'he's with us' to the group","shares half a samosa","laughs when others tease you","lets you pick the game sometimes","copies your seat when teacher moves you"],"mode":"assemble","key":["sits beside you when others won't","says 'he's with us' to the group","shares half a samosa","lets you pick the game sometimes"],"relearn":"A real friend includes you and stands with you, even when others don't."},
  {"id":"ff-1175","cat":"real-friend","type":"build","persona":"any","source":"social development","hook":"Friends come in many kinds. Gather your circle.","prompt":"Pick people who can each be a real friend.","pieces":["your cricket buddy","your reading-corner friend","your cousin next door","only your one 'best' friend","the quiet kid you eat with","the bus-stop friend"],"mode":"assemble","key":["your cricket buddy","your reading-corner friend","your cousin next door","the quiet kid you eat with","the bus-stop friend"],"relearn":"You can have many friends of different kinds; a wide circle is a strong one."},
  {"id":"ff-1176","cat":"real-friend","type":"build","persona":"any","source":"prosocial skills","hook":"Build a 'glad for you' friend.","prompt":"Pick how a real friend reacts to your win.","pieces":["claps when you top the test","says 'teach me how'","sulks the rest of the day","tells everyone your good news","says 'mine was better'","high-fives you"],"mode":"assemble","key":["claps when you top the test","says 'teach me how'","tells everyone your good news","high-fives you"],"relearn":"A real friend is glad when good things happen to you, not jealous."},
  {"id":"ff-1177","cat":"real-friend","type":"build","persona":"Reyansh","source":"honesty in friendship","hook":"A real friend is honest, but kind. Build it.","prompt":"Pick honest-AND-kind moves.","pieces":["'your shirt's inside out, fix it before class'","'you sang flat' said in front of all","'I think you forgot your line, want help?'","laughs and points","'that wasn't fair to her, na?'","stays quiet to avoid trouble"],"mode":"assemble","key":["'your shirt's inside out, fix it before class'","'I think you forgot your line, want help?'","'that wasn't fair to her, na?'"],"relearn":"Real friends are honest in a kind way, not by mocking or by hiding the truth."},
  {"id":"ff-1178","cat":"real-friend","type":"build","persona":"any","source":"empathy / support","hook":"Lensy: a friend's pet ran away. Build your help.","prompt":"Pick what a real friend would do.","pieces":["help put up 'lost' posters","say 'I'm sorry, that's so sad'","say 'it was just a dog'","ask grown-ups in the lane","sit with them while they cry","change the subject fast"],"mode":"assemble","key":["help put up 'lost' posters","say 'I'm sorry, that's so sad'","ask grown-ups in the lane","sit with them while they cry"],"relearn":"A real friend shows up in the hard moments and takes your feelings seriously."},
  {"id":"ff-1179","cat":"real-friend","type":"match","persona":"any","source":"friendship-quality","hook":"What a real friend does, and how you feel after.","pairs":[{"left":"Saves you a place in line","right":"You feel remembered"},{"left":"Keeps the secret you told","right":"You feel trusted"},{"left":"Picks you for the team early","right":"You feel wanted"},{"left":"Asks how your nani is","right":"You feel cared for"},{"left":"Owns up when they were wrong","right":"You feel respected"}],"relearn":"Real friends leave you feeling remembered, trusted, wanted, cared for and respected."},
  {"id":"ff-1180","cat":"real-friend","type":"match","persona":"any","source":"empathy / support","hook":"A friend's having a hard time. Match a kind reply.","pairs":[{"left":"Didn't make the team","right":"\"Want to practise together?\""},{"left":"Grandad's in hospital","right":"\"I'm here if you want to talk.\""},{"left":"Got scolded by teacher","right":"\"Everyone slips. You okay?\""},{"left":"Lost their pencil box","right":"\"Let's go look for it.\""},{"left":"Nervous about the recital","right":"\"You've got this.\""}],"relearn":"Real friends show up most when you're struggling."},
  {"id":"ff-1181","cat":"real-friend","type":"match","persona":"any","source":"friendship-quality","hook":"Match the real-friend move to the moment.","pairs":[{"left":"You're new in the lane","right":"Shows you where to play"},{"left":"You forgot your tiffin","right":"Splits theirs with you"},{"left":"You're scared of the dog","right":"Walks on the dog's side"},{"left":"You can't read a word","right":"Sounds it out with you"},{"left":"You're left out","right":"Says 'let her play too'"}],"relearn":"A real friend notices what you need and quietly helps."},
  {"id":"ff-1182","cat":"real-friend","type":"match","persona":"Ananya","source":"social development","hook":"Different friends, different gifts. Match them.","pairs":[{"left":"The funny friend","right":"Good for a dull afternoon"},{"left":"The good listener","right":"Good when you're upset"},{"left":"The brave one","right":"Good when you're nervous"},{"left":"The patient one","right":"Good when you're learning"},{"left":"The honest one","right":"Good when you need the truth"}],"relearn":"Many kinds of friends; each is real in their own way."},
  {"id":"ff-1183","cat":"real-friend","type":"match","persona":"any","source":"prosocial skills","hook":"Match how a real friend handles YOUR good news.","pairs":[{"left":"You won the spelling bee","right":"\"Yes! You earned that.\""},{"left":"You got a new cycle","right":"\"Let's ride to the park!\""},{"left":"You made a new friend","right":"\"Tell me about them.\""},{"left":"You drew something nice","right":"\"Whoa, can you teach me?\""},{"left":"You finally touched your toes","right":"\"See, you kept at it!\""}],"relearn":"A real friend is glad for your wins and never tries to shrink them."},
  {"id":"ff-1184","cat":"real-friend","type":"match","persona":"any","source":"honesty in friendship","hook":"Match the kind-and-honest thing a friend might say.","pairs":[{"left":"Spinach in your teeth","right":"\"Psst, check your teeth.\""},{"left":"You were a bit bossy","right":"\"Can we take turns?\""},{"left":"Plot hole in your story","right":"\"What happens to the dog?\""},{"left":"You sang off-key","right":"\"Let's practise that bit.\""},{"left":"You forgot their birthday","right":"\"It's okay, wish me now.\""}],"relearn":"Honest-but-kind beats both mocking and saying nothing."},
  {"id":"ff-1185","cat":"real-friend","type":"sort","persona":"any","source":"friendship-quality","hook":"Sort what leaves you GLAD versus what leaves you small.","items":[{"id":"a","text":"They cheer when you win"},{"id":"b","text":"They roll their eyes at your idea"},{"id":"c","text":"They save you a seat"},{"id":"d","text":"They copy you, then mock you"},{"id":"e","text":"They ask how you're really doing"},{"id":"f","text":"They only call when they're bored"}],"bins":[{"id":"glad","label":"Leaves you glad","valence":"pos"},{"id":"small","label":"Leaves you small","valence":"neg"}],"key":{"a":"glad","b":"small","c":"glad","d":"small","e":"glad","f":"small"},"relearn":"Notice who leaves you feeling glad and safe; that's the clue to a real friend."},
  {"id":"ff-1186","cat":"real-friend","type":"sort","persona":"Ananya","source":"prosocial skills","hook":"Sort YOUR moves: real-friend, or just-okay?","items":[{"id":"a","text":"You share the swing"},{"id":"b","text":"You always have to be captain"},{"id":"c","text":"You own up when you're wrong"},{"id":"d","text":"You keep a tally of favours"},{"id":"e","text":"You wait for the slow runner"},{"id":"f","text":"You laugh when she trips"}],"bins":[{"id":"real","label":"Real-friend move","valence":"pos"},{"id":"nope","label":"Not really","valence":"neg"}],"key":{"a":"real","b":"nope","c":"real","d":"nope","e":"real","f":"nope"},"relearn":"Real-friend moves are sharing, owning your part and waiting; not bossing or scorekeeping."},
  {"id":"ff-1187","cat":"real-friend","type":"sort","persona":"any","source":"friendship-quality","hook":"A friend's words: warm, or a little chilly?","items":[{"id":"a","text":"\"Come sit with us!\""},{"id":"b","text":"\"This seat's taken... by no one you know.\""},{"id":"c","text":"\"You okay? You seem quiet.\""},{"id":"d","text":"\"Why are you even here?\""},{"id":"e","text":"\"I saved you the window seat.\""},{"id":"f","text":"\"We're full, find another group.\""}],"bins":[{"id":"warm","label":"Warm","valence":"pos"},{"id":"chilly","label":"A bit chilly","valence":"neg"}],"key":{"a":"warm","b":"chilly","c":"warm","d":"chilly","e":"warm","f":"chilly"},"relearn":"Warm words include you; chilly ones push you out. Real friends use warm ones."},
  {"id":"ff-1188","cat":"real-friend","type":"sort","persona":"any","source":"social development","hook":"Is each one a reason a friendship is real, or not?","items":[{"id":"a","text":"They like you for who you are"},{"id":"b","text":"They like you for your big house"},{"id":"c","text":"They stay when you're not useful"},{"id":"d","text":"They only stay while you give treats"},{"id":"e","text":"They want you to be happy"},{"id":"f","text":"They want you to look bad"}],"bins":[{"id":"real","label":"Real reason","valence":"pos"},{"id":"shaky","label":"Shaky reason","valence":"neg"}],"key":{"a":"real","b":"shaky","c":"real","d":"shaky","e":"real","f":"shaky"},"relearn":"A real friend likes you for you and wants you happy, not for what they can get."},
  {"id":"ff-1189","cat":"real-friend","type":"sort","persona":"any","source":"empathy / support","hook":"A friend is sad. Sort the helping moves from the not.","items":[{"id":"a","text":"Sit with them quietly"},{"id":"b","text":"Tell them to 'get over it'"},{"id":"c","text":"Ask if they want to talk"},{"id":"d","text":"Spread why they're upset"},{"id":"e","text":"Offer to walk them home"},{"id":"f","text":"Make it a joke"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"hurts","label":"Hurts","valence":"neg"}],"key":{"a":"helps","b":"hurts","c":"helps","d":"hurts","e":"helps","f":"hurts"},"relearn":"A real friend sits with your feelings; they don't rush, mock or gossip about them."},
  {"id":"ff-1190","cat":"real-friend","type":"sort","persona":"Faizan","source":"belonging","hook":"At a new school, sort who's being a real friend.","items":[{"id":"a","text":"Shows you where the water is"},{"id":"b","text":"Laughs at your old uniform"},{"id":"c","text":"Saves you a spot at lunch"},{"id":"d","text":"Copies your accent to tease"},{"id":"e","text":"Picks you for their team"},{"id":"f","text":"Ignores you when friends are near"}],"bins":[{"id":"friend","label":"Real friend","valence":"pos"},{"id":"not","label":"Not really","valence":"neg"}],"key":{"a":"friend","b":"not","c":"friend","d":"not","e":"friend","f":"not"},"relearn":"A real friend helps you belong and never makes you the joke to fit in."},
  {"id":"ff-1191","cat":"real-friend","type":"strike-rewrite","persona":"Reyansh","source":"social development","hook":"\"If you make a new friend, you're betraying your old one.\"","myth":{"un":"Making a new friend means dumping your old one.","re":"Your heart has room for more than one friend.","why":"Friendship isn't a pie that runs out when you share it."},"relearn":"You can welcome new friends and keep your old ones too."},
  {"id":"ff-1192","cat":"real-friend","type":"strike-rewrite","persona":"any","source":"friendship-quality","hook":"\"A real friend agrees with everything you say.\"","myth":{"un":"Real friends never disagree with you.","re":"A real friend can disagree and still care about you.","why":"Liking different things doesn't break a real friendship."},"relearn":"Friends can think differently and still be close."},
  {"id":"ff-1193","cat":"real-friend","type":"strike-rewrite","persona":"Ananya","source":"social development","hook":"\"The richest kid is everyone's real friend.\"","myth":{"un":"Whoever has the most toys is the best friend to have.","re":"A real friend is known by how they treat you, not what they own.","why":"Kindness, not stuff, is what makes a friendship real."},"relearn":"Look at how a friend treats you, not at what they have."},
  {"id":"ff-1194","cat":"real-friend","type":"strike-rewrite","persona":"any","source":"friendship-quality","hook":"\"Quiet kids can't be real friends.\"","myth":{"un":"You have to be loud and popular to be a good friend.","re":"A quiet kid can be one of the kindest, most loyal friends.","why":"Good friendship is about how you treat people, not how loud you are."},"relearn":"Real friends come in every kind, loud and quiet alike."},
  {"id":"ff-1195","cat":"real-friend","type":"strike-rewrite","persona":"any","source":"prosocial skills","hook":"\"If a friend does better than you, they're showing off.\"","myth":{"un":"A friend who wins is just trying to make you look bad.","re":"A friend can do well without it being about you at all.","why":"A real friend's win is something you can be glad about, not threatened by."},"relearn":"You can be happy for a friend's success and proud of your own."},
  {"id":"ff-1196","cat":"real-friend","type":"strike-rewrite","persona":"any","source":"boundaries in friendship","hook":"\"A real friend tells you everyone's secrets.\"","myth":{"un":"Good friends share every secret they hear.","re":"A real friend keeps your secret safe.","why":"Trust is what makes it safe to tell a friend things."},"relearn":"A friend who keeps your trust is one worth keeping."},
  {"id":"ff-1197","cat":"real-friend","type":"strike-rewrite","persona":"any","source":"honesty in friendship","hook":"\"Being honest means being harsh.\"","myth":{"un":"To be honest with a friend you have to be blunt and cutting.","re":"You can tell a friend the truth in a gentle, caring way.","why":"Honesty and kindness fit together; you don't pick one."},"relearn":"Real friends are honest-but-kind, not honest-and-mean."},
  {"id":"ff-1198","cat":"real-friend","type":"strike-rewrite","persona":"any","source":"social development","hook":"\"You have to have a 'best' friend or you're a loner.\"","myth":{"un":"Without one best friend, you have no real friends.","re":"A few kind, steady friends is real friendship too.","why":"Friendship isn't a contest with one winner at the top."},"relearn":"Many kinds of friends, or just a couple of steady ones, are all real."},
  {"id":"ff-1199","cat":"real-friend","type":"strike-rewrite","persona":"Faizan","source":"belonging","hook":"\"New kids have to earn their way in by doing favours.\"","myth":{"un":"A new kid must do favours before anyone will be their friend.","re":"A real friend welcomes you just for being you.","why":"You shouldn't have to buy a place in a real friendship."},"relearn":"You deserve friends who include you without you having to earn it."},
  {"id":"ff-1200","cat":"real-friend","type":"reflect","persona":"any","source":"reflection / friendship-quality","hook":"Think of a friend who makes a dull day better.","prompt":"What do they do that you like?","options":["They make me laugh","They include me","They listen to me","They're calm when I'm not"],"affirm":"That good, easy feeling is what a real friend gives. Notice it, and pass it on.","relearn":"The friend who lifts a dull day is showing you what a real friend feels like."},
  {"id":"ff-1201","cat":"real-friend","type":"reflect","persona":"Ananya","source":"reflection","hook":"Lensy: which friend would you call if you were scared?","prompt":"Picture them. Why them?","options":["They stay calm","They don't judge me","They take me seriously","They always pick up"],"affirm":"The friend you'd call in the dark is showing you what a real friend is.","relearn":"The friend you'd call when scared is a real one."},
  {"id":"ff-1202","cat":"real-friend","type":"reflect","persona":"any","source":"reflection / growth","hook":"What kind of friend do YOU want to be this term?","prompt":"Pick one to grow.","options":["A better listener","Quicker to include people","Quicker to say sorry","More honest-but-kind"],"affirm":"Choosing how you show up is how good friends are made, not born. Lovely pick.","relearn":"You can choose to grow into a better friend."},
  {"id":"ff-1203","cat":"real-friend","type":"reflect","persona":"any","source":"reflection / friendship-quality","hook":"When you're with your favourite friend, you feel...","prompt":"Pick the word that fits.","options":["Safe","Glad","Myself","Calm"],"affirm":"All of those are signs of a real friend. That feeling is the clue to trust.","relearn":"Feeling safe and yourself is the clue to a real friend."},
  {"id":"ff-1204","cat":"real-friend","type":"reflect","persona":"any","source":"reflection / social development","hook":"Friends can be many kinds. Who's in your circle?","prompt":"Pick one you're glad to have.","options":["A cousin","A neighbour","A classmate","A bus-stop buddy"],"affirm":"Every kind of friend counts. A wide circle is a strong, warm one.","relearn":"Friends come in many kinds, and each one counts."},
  {"id":"ff-1205","cat":"real-friend","type":"reflect","persona":"any","source":"reflection / empathy","hook":"A friend did something kind for you lately.","prompt":"What was it?","options":["Shared their tiffin","Stood up for me","Listened when I was sad","Waited for me"],"affirm":"Remembering kindness helps you spot and give it. That's a real friend at work.","relearn":"Recalling a friend's kindness helps you give it back."},
  {"id":"ff-1206","cat":"real-friend","type":"reflect","persona":"any","source":"reflection / prosocial","hook":"A friend got good news. How did you want to react?","prompt":"Pick the one that feels right.","options":["Cheer for them","Ask all about it","Tell others, proudly","Give a big high-five"],"affirm":"Being glad for a friend's win is one of the kindest things a real friend does.","relearn":"Cheering a friend's good news is real friendship."},
  {"id":"ff-1207","cat":"real-friend","type":"reflect","persona":"Faizan","source":"reflection / belonging","hook":"Think of a time someone made you feel you belonged.","prompt":"What did they do?","options":["Saved me a seat","Said 'come play'","Used my name","Stuck by me"],"affirm":"That belonging feeling is a gift. You can give it to the next kid who's alone.","relearn":"You can hand the feeling of belonging to someone else."},
  {"id":"ff-1208","cat":"real-friend","type":"reflect","persona":"any","source":"reflection / friendship-quality","hook":"Lensy: what's one thing you'd never want a friend to do?","prompt":"Pick what matters to you.","options":["Laugh at me","Spill my secret","Leave me out","Go cold suddenly"],"affirm":"Knowing what you won't accept helps you find the friends who treat you well.","relearn":"Knowing your limits helps you pick friends who respect them."},
  {"id":"ff-1209","cat":"real-friend","type":"branch","persona":"any","source":"inclusion","hook":"A quiet new kid stands alone at the edge of your game.","options":[{"text":"Wave them in and explain the rules","consequence":"They grin and join in.","outcome":"kind","best":true},{"text":"Hope someone else asks them","consequence":"They keep standing alone.","outcome":"missed"},{"text":"Say they'd slow the team down","consequence":"They hear, and walk off hurt.","outcome":"unkind"}],"debrief":"One small 'come play' can change a kid's day. That's real friendship.","relearn":"Including a lonely or new kid is an easy way to be a real friend."},
  {"id":"ff-1210","cat":"real-friend","type":"branch","persona":"any","source":"prosocial skills","hook":"Your friend won the race you both trained for.","options":[{"text":"Run over and cheer them","consequence":"They beam; you feel closer.","outcome":"glad","best":true},{"text":"Sulk and walk off","consequence":"They feel bad on their big day.","outcome":"jealous"},{"text":"Say 'I let you win'","consequence":"Their smile fades.","outcome":"unkind"}],"debrief":"Being glad for a friend's win is what real friends do; their joy isn't yours to lose.","relearn":"A real friend celebrates you and isn't jealous of your wins."},
  {"id":"ff-1211","cat":"real-friend","type":"branch","persona":"any","source":"honesty in friendship","hook":"Your friend's painting has the cat's tail backwards.","options":[{"text":"\"It's lovely; tail's the other way, though.\"","consequence":"They fix it, glad you told them.","outcome":"honest-kind","best":true},{"text":"Say nothing","consequence":"Teacher sees it; they feel silly.","outcome":"missed"},{"text":"Laugh, call it 'backwards cat'","consequence":"They go red, stop sharing art.","outcome":"unkind"}],"debrief":"Honest-and-kind helps; silence or mocking both let a friend down.","relearn":"Real friends tell the truth gently, so it helps, not stings."},
  {"id":"ff-1212","cat":"real-friend","type":"branch","persona":"Faizan","source":"belonging","hook":"Old friends ignore the new boy you sit with.","options":[{"text":"Introduce him: 'He's with us'","consequence":"They warm up; circle grows.","outcome":"include","best":true},{"text":"Drop him to keep old friends","consequence":"He's alone; you feel bad.","outcome":"missed"},{"text":"Keep the two groups apart","consequence":"Tiring; someone feels hidden.","outcome":"shaky"}],"debrief":"You needn't pick one friend over another; a real friend helps people belong.","relearn":"You can have many friends and help new ones feel included."},
  {"id":"ff-1213","cat":"real-friend","type":"branch","persona":"Ananya","source":"empathy / support","hook":"Your friend's crying; her grandmother is unwell.","options":[{"text":"Sit with her and listen","consequence":"She feels less alone.","outcome":"caring","best":true},{"text":"Tell her to stop, it's fine","consequence":"She feels brushed off, goes quiet.","outcome":"missed"},{"text":"Tell the class to cheer her up","consequence":"Her private worry got out.","outcome":"oops"}],"debrief":"A real friend takes your feelings seriously and stays, without spreading them.","relearn":"Real friends show up and listen in the hard moments."},
  {"id":"ff-1214","cat":"real-friend","type":"branch","persona":"any","source":"prosocial skills","hook":"You both want the last good cricket bat.","options":[{"text":"Suggest taking turns with it","consequence":"You both get a go.","outcome":"fair","best":true},{"text":"Grab it for all recess","consequence":"They feel cheated, stop playing.","outcome":"shaky"},{"text":"Say 'you take it' and sulk","consequence":"They can tell you're upset.","outcome":"missed"}],"debrief":"Real friends find a fair fix, so nobody has to lose for the other to be happy.","relearn":"Sharing and taking turns keeps a friendship fair and fun."},
  {"id":"ff-1215","cat":"real-friend","type":"branch","persona":"any","source":"friendship-quality","hook":"A popular kid: join us, but ditch your quiet friend.","options":[{"text":"\"No thanks, I'll keep my friend.\"","consequence":"You keep a true friend.","outcome":"loyal","best":true},{"text":"Ditch your friend to join","consequence":"Your friend is hurt.","outcome":"shaky"},{"text":"Keep both, but hide the friend","consequence":"They feel like a secret.","outcome":"oops"}],"debrief":"A friendship that asks you to drop a kind friend isn't worth the price.","relearn":"A few steady, kind friends matter more than a popular crowd."},
  {"id":"ff-1216","cat":"real-friend","type":"role-play","persona":"Reyansh","source":"social skills","hook":"You want to invite the new kid to play cricket at recess.","setup":"You walk over to them. What do you say?","yourLine":[{"text":"\"Hi, I'm Reyansh. Want to bat with us?\"","best":true},{"text":"Stand near them and hope they ask to join"},{"text":"\"You probably can't play, but okay, come.\""}],"relearn":"A warm, plain invite is the easiest way to include someone."},
  {"id":"ff-1217","cat":"real-friend","type":"role-play","persona":"any","source":"social skills","hook":"Your friend just told you they topped the class.","setup":"They look at you to see how you'll react.","yourLine":[{"text":"\"That's brilliant! You worked so hard for it.\"","best":true},{"text":"\"Lucky. The paper was easy this time.\""},{"text":"Shrug and change the subject"}],"relearn":"Being glad for a friend's win, not jealous, is real friendship."},
  {"id":"ff-1218","cat":"real-friend","type":"role-play","persona":"any","source":"empathy / support","hook":"Your friend looks down and won't say why.","setup":"You sit beside them at the back of the bus.","yourLine":[{"text":"\"I'm here if you want to talk. No rush.\"","best":true},{"text":"\"Whatever it is, just get over it.\""},{"text":"Pretend you didn't notice"}],"relearn":"Offering to listen, no pressure, helps a low friend most."},
  {"id":"ff-1219","cat":"real-friend","type":"role-play","persona":"any","source":"honesty in friendship","hook":"Your friend is about to go on stage with chalk on their face.","setup":"There are a few seconds before they walk out.","yourLine":[{"text":"\"Quick, wipe your cheek, there's chalk.\"","best":true},{"text":"Let them go; someone else can tell them"},{"text":"Snap a photo to show the others first"}],"relearn":"A quick, kind heads-up saves a friend from embarrassment."},
  {"id":"ff-1220","cat":"real-friend","type":"role-play","persona":"Faizan","source":"belonging","hook":"Kids are picking teams and the new boy is left till last.","setup":"It's your turn to pick. He's still standing there.","yourLine":[{"text":"\"I'll take him, come on, you're with me.\"","best":true},{"text":"Pick someone better and let him wait"},{"text":"\"Ugh, fine, I guess I have to take him.\""}],"relearn":"Picking the left-out kid warmly turns a hard moment kind."},
  {"id":"ff-1221","cat":"real-friend","type":"role-play","persona":"any","source":"social skills","hook":"Your friend shared a secret with you yesterday.","setup":"Another kid asks you, 'So what did she tell you?'","yourLine":[{"text":"\"That's hers to share, not mine.\"","best":true},{"text":"Tell them a little bit; it's only one kid"},{"text":"Tell them the whole thing for fun"}],"relearn":"A friend's secret is theirs to share, not yours."},
  {"id":"ff-1222","cat":"real-friend","type":"role-play","persona":"any","source":"prosocial skills","hook":"You and a friend both want to be in goal.","setup":"You're standing by the posts, deciding.","yourLine":[{"text":"\"You go first half, I'll go second?\"","best":true},{"text":"\"It's mine, I called it first.\""},{"text":"Give up and quietly feel cheated"}],"relearn":"Offering to share the turn keeps the game and the friendship fair."},
  {"id":"ff-1223","cat":"real-friend","type":"sort","persona":"any","source":"friendship-quality","hook":"Sort these into what you'd want, or wouldn't, from a friend.","items":[{"id":"a","text":"Keeps their promises to you"},{"id":"b","text":"Breaks plans for someone better"},{"id":"c","text":"Defends you when you're not there"},{"id":"d","text":"Joins in when others tease you"},{"id":"e","text":"Remembers what matters to you"},{"id":"f","text":"Forgets you the moment you leave"}],"bins":[{"id":"want","label":"Want this","valence":"pos"},{"id":"dont","label":"Don't want this","valence":"neg"}],"key":{"a":"want","b":"dont","c":"want","d":"dont","e":"want","f":"dont"},"relearn":"Real friends keep promises, defend you, and remember what matters."},
  {"id":"ff-1224","cat":"real-friend","type":"match","persona":"any","source":"social development","hook":"Match the friend to where you might meet them.","pairs":[{"left":"Your tuition friend","right":"You met over homework"},{"left":"Your festival friend","right":"You met at a Diwali mela"},{"left":"Your team friend","right":"You met at football practice"},{"left":"Your building friend","right":"You met on the stairs"},{"left":"Your library friend","right":"You met over the same book"}],"relearn":"Real friends turn up in all sorts of places; your circle can be wide."},
  {"id":"ff-1260","cat":"repair","type":"strike-rewrite","hook":"\"If we fight once, the friendship is over.\"","myth":{"un":"One argument means the friendship is finished.","re":"One fight doesn't end a friendship; making up does the mending.","why":"Disagreeing is normal, and repair is the skill that keeps friends."},"relearn":"A single fight is not the end; how you make up is what counts.","persona":"any","source":"conflict / repair"},
  {"id":"ff-1261","cat":"repair","type":"strike-rewrite","hook":"\"Sorry only counts if you cry.\"","myth":{"un":"A sorry isn't real unless you cry while saying it.","re":"A real sorry is owning what you did, not how much you cry.","why":"Repair is about taking responsibility, not putting on a show."},"relearn":"A true sorry names your part calmly; tears are not the test.","persona":"any","source":"repair / sincerity"},
  {"id":"ff-1262","cat":"repair","type":"strike-rewrite","hook":"\"Whoever forgives first is weak.\"","myth":{"un":"The one who forgives first has lost.","re":"Choosing to forgive is your strength, not a loss.","why":"Repair isn't a contest; letting go of a hurt frees you."},"relearn":"Forgiving when you're ready is a strong choice, not defeat.","persona":"Reyansh","source":"repair / values"},
  {"id":"ff-1263","cat":"repair","type":"strike-rewrite","hook":"\"If they were really sorry, they'd buy me something.\"","myth":{"un":"A friend has to give you a gift to prove they're sorry.","re":"A real sorry is words and changed behaviour, not a present.","why":"Repair is trust rebuilt by actions, not paid for with things."},"relearn":"A sorry shows in how they act next, not in a gift.","persona":"any","source":"repair / sincerity"},
  {"id":"ff-1264","cat":"repair","type":"strike-rewrite","hook":"\"Saying sorry means admitting it was all my fault.\"","myth":{"un":"To apologise is to take all the blame.","re":"You can own just your part of a fight without taking all the blame.","why":"Most fights have two sides; owning your bit is enough to start repair."},"relearn":"Sorry for your part isn't sorry for everything.","persona":"Ananya","source":"accountability"},
  {"id":"ff-1265","cat":"repair","type":"strike-rewrite","hook":"\"Once trust breaks, it can never come back.\"","myth":{"un":"A broken trust can never be mended.","re":"Trust can grow back slowly when a friend keeps their word again.","why":"Small kept promises over time rebuild what one mistake cracked."},"relearn":"Broken trust can heal, step by step, with steady actions.","persona":"any","source":"repair / trust"},
  {"id":"ff-1266","cat":"repair","type":"strike-rewrite","hook":"\"Making up means pretending it never happened.\"","myth":{"un":"To make up, you must act like the hurt never happened.","re":"Making up means talking it through, not hiding what hurt.","why":"Naming the hurt kindly is what stops it coming back later."},"relearn":"Real repair talks it out; it doesn't sweep it under the mat.","persona":"any","source":"repair / honesty"},
  {"id":"ff-1267","cat":"repair","type":"strike-rewrite","hook":"\"You should never say sorry to someone younger than you.\"","myth":{"un":"Big kids don't apologise to little ones.","re":"You say sorry to anyone you hurt, younger or older.","why":"A hurt feels the same at any age; fairness doesn't skip the small ones."},"relearn":"Saying sorry to a younger friend is fair, not below you.","persona":"any","source":"repair / fairness"},
  {"id":"ff-1268","cat":"repair","type":"strike-rewrite","hook":"\"If I wait long enough, they'll forget I was mean.\"","myth":{"un":"Waiting it out makes a hurt disappear on its own.","re":"Waiting hides the hurt; a kind sorry is what clears it.","why":"Ignored hurts tend to grow quiet but stay; talking heals them."},"relearn":"Time alone doesn't repair; a real sorry does the mending.","persona":"any","source":"repair / accountability"},
  {"id":"ff-1269","cat":"repair","type":"strike-rewrite","hook":"\"Apologising on chat doesn't count, only in person.\"","myth":{"un":"A sorry only matters if it's said face to face.","re":"A heartfelt sorry on a message counts too, if you mean it.","why":"What matters is the honest words, not only where you say them."},"relearn":"A real sorry counts on chat or in person, as long as you mean it.","persona":"any","source":"repair / online"},
  {"id":"ff-1270","cat":"repair","type":"build","hook":"You snapped at a friend in class. Build a calm sorry.","prompt":"Put the parts of a good apology in order.","pieces":["catch them at a calm moment","say what you did","say you're sorry","ask how to make it right","let them answer"],"mode":"sequence","key":["catch them at a calm moment","say what you did","say you're sorry","ask how to make it right","let them answer"],"relearn":"A good sorry: pick the moment, name it, mean it, then listen.","persona":"any","source":"apology steps"},
  {"id":"ff-1271","cat":"repair","type":"build","hook":"You broke a friend's pencil box and hid it. Build the fix.","prompt":"Order the steps to set it right.","pieces":["own up that you broke it","say sorry for hiding it","offer to fix or replace it","ask if you're okay now"],"mode":"sequence","key":["own up that you broke it","say sorry for hiding it","offer to fix or replace it","ask if you're okay now"],"relearn":"Owning a mistake and offering to fix it repairs more than hiding ever can.","persona":"any","source":"accountability"},
  {"id":"ff-1272","cat":"repair","type":"build","hook":"Two friends are arguing in the playground. Build a calm-down plan.","prompt":"Pick the moves that help you both cool off.","pieces":["take a few deep breaths","step apart for a minute","get a drink of water","shout louder to win","come back and talk"],"mode":"assemble","key":["take a few deep breaths","step apart for a minute","get a drink of water","come back and talk"],"relearn":"Cooling down first makes the talking-it-out part go much better.","persona":"any","source":"cool-down"},
  {"id":"ff-1273","cat":"repair","type":"build","hook":"Build an 'I felt' sentence to open a hard talk.","prompt":"Put the parts of an 'I felt' line in order.","pieces":["I felt","sad","when you","left me out","at lunch"],"mode":"sequence","key":["I felt","sad","when you","left me out","at lunch"],"relearn":"\"I felt ... when you ...\" shares your side without blaming.","persona":"Ananya","source":"I-statements"},
  {"id":"ff-1274","cat":"repair","type":"build","hook":"You and a friend want to make up. Build the things a fair fix needs.","prompt":"Pick what a fair fix includes.","pieces":["both of you agree to it","each gives a little","it's clear and simple","one person decides it all","you can keep it"],"mode":"assemble","key":["both of you agree to it","each gives a little","it's clear and simple","you can keep it"],"relearn":"A fair fix is one you both agree on and can actually keep.","persona":"any","source":"compromise"},
  {"id":"ff-1275","cat":"repair","type":"build","hook":"A friend said sorry. Build a kind way to accept it.","prompt":"Order a warm, honest reply to a sorry.","pieces":["thank them for saying sorry","say how it made you feel","say you'd like to move on","plan something fun together"],"mode":"sequence","key":["thank them for saying sorry","say how it made you feel","say you'd like to move on","plan something fun together"],"relearn":"You can accept a sorry, share your feeling, and still move forward.","persona":"any","source":"repair / honesty"},
  {"id":"ff-1276","cat":"repair","type":"build","hook":"You both said hurtful things. Build the order of a real make-up.","prompt":"Put a two-sided make-up in order.","pieces":["cool down apart","each say your part","each say sorry","agree what to do next time","go play again"],"mode":"sequence","key":["cool down apart","each say your part","each say sorry","agree what to do next time","go play again"],"relearn":"When you both slipped, you both share and both say sorry.","persona":"any","source":"conflict resolution"},
  {"id":"ff-1277","cat":"repair","type":"role-play","hook":"You forgot your friend's turn on the swing and they're cross.","setup":"Pick the line that starts repair.","yourLine":[{"text":"\"You're being silly, it's just a swing.\""},{"text":"\"I'm sorry I forgot your turn, let's swap now.\"","best":true},{"text":"Pretend you didn't hear them"}],"relearn":"Owning a small slip quickly stops it growing into a big fight.","persona":"any","source":"apology"},
  {"id":"ff-1278","cat":"repair","type":"role-play","hook":"A friend is sulking and you're not sure what you did.","setup":"What do you say?","yourLine":[{"text":"\"Tell me if I hurt you, I'd like to fix it.\"","best":true},{"text":"\"Fine, sulk then.\""},{"text":"Sulk back at them"}],"relearn":"Asking openly beats matching their mood or guessing in silence.","persona":"Ananya","source":"perspective-taking"},
  {"id":"ff-1279","cat":"repair","type":"role-play","hook":"You teased a friend and they walked off upset.","setup":"You go after them. What do you say?","yourLine":[{"text":"\"I went too far, I'm sorry, that wasn't kind.\"","best":true},{"text":"\"It was only a joke, relax.\""},{"text":"\"Everyone laughed though.\""}],"relearn":"Naming that you crossed a line repairs more than 'it was a joke'.","persona":"any","source":"accountability"},
  {"id":"ff-1280","cat":"repair","type":"role-play","hook":"Your friend says sorry but you still feel a bit hurt.","setup":"Pick the honest, kind reply.","yourLine":[{"text":"\"Thanks. I'm still a bit sad, but I want to be okay.\"","best":true},{"text":"\"It's totally fine.\" (but you stay cold)"},{"text":"\"You always do this.\""}],"relearn":"You can take a sorry and still say how you really feel.","persona":"any","source":"repair / honesty"},
  {"id":"ff-1281","cat":"repair","type":"role-play","hook":"You want your turn back in a fair way after a squabble.","setup":"Say the line that asks fairly.","yourLine":[{"text":"\"Can we take turns so we both get a go?\"","best":true},{"text":"\"Give it to me, it's mine!\""},{"text":"Grab it and run off"}],"relearn":"Asking for a fair turn settles squabbles without a winner and loser.","persona":"any","source":"compromise"},
  {"id":"ff-1282","cat":"repair","type":"role-play","hook":"You spread a rumour about a friend and feel bad.","setup":"You find them. What do you say?","yourLine":[{"text":"\"I told others your secret. I'm sorry, that was wrong.\"","best":true},{"text":"\"Someone else started it, not me.\""},{"text":"Say nothing and hope they don't find out"}],"relearn":"Owning a rumour you spread is hard, but it's how trust starts mending.","persona":"any","source":"accountability"},
  {"id":"ff-1283","cat":"repair","type":"role-play","hook":"A friend apologises and you're ready to make up.","setup":"Pick the warm way to accept.","yourLine":[{"text":"\"Thank you for saying that. Friends again?\"","best":true},{"text":"\"You should be sorry.\""},{"text":"Shrug and turn away"}],"relearn":"A warm 'thank you, friends again?' lets the make-up land gently.","persona":"any","source":"repair / forgiveness"},
  {"id":"ff-1284","cat":"repair","type":"role-play","hook":"You blamed a friend for something they didn't do.","setup":"You realise your mistake. What do you say?","yourLine":[{"text":"\"I was wrong to blame you, I'm really sorry.\"","best":true},{"text":"\"Well, it looked like you.\""},{"text":"Stay quiet so you don't look silly"}],"relearn":"Admitting a wrong blame clears your friend's name and your own conscience.","persona":"any","source":"accountability"},
  {"id":"ff-1285","cat":"repair","type":"role-play","hook":"On the class chat you and a friend argued in front of everyone.","setup":"You want to cool it down. What do you type?","yourLine":[{"text":"\"Let's not do this here, can we talk tomorrow?\"","best":true},{"text":"\"You started it, everyone saw.\""},{"text":"Send an angry sticker"}],"relearn":"Taking a hot argument out of the group chat gives repair a chance.","persona":"Reyansh","source":"repair / online"},
  {"id":"ff-1286","cat":"repair","type":"role-play","hook":"You said something unkind in front of the whole group.","setup":"You want to make it right. What do you say?","yourLine":[{"text":"\"I was unkind earlier, I'm sorry I said that.\"","best":true},{"text":"\"I didn't really mean it, chill.\""},{"text":"Wait for them to bring it up"}],"relearn":"A sorry said as openly as the hurt was helps your friend feel seen.","persona":"any","source":"apology"},
  {"id":"ff-1287","cat":"repair","type":"branch","hook":"You called your friend a name in the heat of a game.","options":[{"text":"Say \"you call me names too\"","consequence":"Now you're both keeping score, not making up.","outcome":"scorekeep"},{"text":"Say \"sorry I called you that, it was unkind\"","consequence":"They feel respected and you both relax.","outcome":"repair","best":true}],"debrief":"A quick, clear sorry for a name beats trading blame.","relearn":"Owning an unkind word, without 'but you too', is what repairs it.","persona":"any","source":"accountability"},
  {"id":"ff-1288","cat":"repair","type":"branch","hook":"You promised to save a seat for a friend and forgot.","options":[{"text":"Blame the teacher for moving you","consequence":"They can tell it's an excuse, and feel let down.","outcome":"excuse"},{"text":"Say \"I forgot and I'm sorry, sit with me now?\"","consequence":"Honesty mends it and you're together again.","outcome":"repair","best":true}],"debrief":"Owning a forgotten promise repairs faster than an excuse.","relearn":"\"I forgot, I'm sorry\" beats blaming something else.","persona":"any","source":"repair / honesty"},
  {"id":"ff-1289","cat":"repair","type":"branch","hook":"Your friend apologised, but you find it hard to let the hurt go.","options":[{"text":"Say you forgive but keep reminding them","consequence":"They feel they can never make it right.","outcome":"avoids"},{"text":"Tell them you forgive them and mean it","consequence":"Letting go lightens you both.","outcome":"repair","best":true}],"debrief":"Forgiving means setting the hurt down, not keeping it as a weapon.","relearn":"Real forgiving lets the hurt rest, not get raised again.","persona":"any","source":"repair / forgiveness"},
  {"id":"ff-1290","cat":"repair","type":"branch","hook":"You and a friend both want to be team captain and start arguing.","options":[{"text":"Refuse to play unless you're captain","consequence":"You sit out and miss the fun.","outcome":"stuck"},{"text":"Take turns being captain each match","consequence":"You both lead and the team stays whole.","outcome":"fair","best":true}],"debrief":"Sharing the role by turns settles a 'who's in charge' fight.","relearn":"Taking turns to lead lets two friends both win.","persona":"any","source":"compromise"},
  {"id":"ff-1291","cat":"repair","type":"branch","hook":"A friend snapped at you because they were having a bad day.","options":[{"text":"Snap back twice as hard","consequence":"A bad day becomes a real fight.","outcome":"escalate"},{"text":"Stay calm and ask \"rough day? what's up?\"","consequence":"They soften and the snap melts away.","outcome":"repair","best":true}],"debrief":"Meeting a snap with calm curiosity often ends it right there.","relearn":"A friend's bad-day snap usually needs care, not payback.","persona":"any","source":"perspective-taking"},
  {"id":"ff-1292","cat":"repair","type":"branch","hook":"You hurt a friend and they need space before they can talk.","options":[{"text":"Message them again and again","consequence":"The pushing makes them want more space.","outcome":"pushy"},{"text":"Say sorry once and give them room","consequence":"Space plus your sorry lets them come round.","outcome":"patient","best":true}],"debrief":"After a real sorry, patience is part of the repair.","relearn":"Giving a hurt friend the space they ask for is also repair.","persona":"any","source":"repair / patience"},
  {"id":"ff-1293","cat":"repair","type":"branch","hook":"A misunderstanding by text made you both upset.","options":[{"text":"Keep typing angry replies","consequence":"Written in heat, words land even harder.","outcome":"escalate"},{"text":"Say \"this is muddled, can we call?\"","consequence":"Hearing each other clears the mix-up fast.","outcome":"repair","best":true}],"debrief":"When text gets tangled, voices untangle it quicker.","relearn":"A quick call can fix a muddle text keeps worsening.","persona":"Reyansh","source":"repair / online"},
  {"id":"ff-1294","cat":"repair","type":"branch","hook":"Your friend says sorry but doesn't seem to get why you were hurt.","options":[{"text":"Accept it and bury the real reason","consequence":"The same hurt can happen all over again.","outcome":"avoids"},{"text":"Gently explain what actually stung","consequence":"Now they understand and can really change.","outcome":"repair","best":true}],"debrief":"A sorry sticks better when your friend understands the why.","relearn":"Kindly explaining what hurt helps a sorry truly land.","persona":"Ananya","source":"repair / honesty"},
  {"id":"ff-1295","cat":"repair","type":"branch","hook":"Two friends of yours fell out and both want you to pick a side.","options":[{"text":"Pick the louder friend's side","consequence":"The other feels betrayed; now there are two fights.","outcome":"stuck"},{"text":"Stay kind to both and not take a side","consequence":"You keep both friends and help them cool off.","outcome":"fair","best":true}],"debrief":"You can be a good friend to both without choosing a side.","relearn":"Helping two friends repair isn't picking one to win.","persona":"any","source":"dilemmas / repair"},
  {"id":"ff-1296","cat":"repair","type":"branch","hook":"You and a friend keep arguing over whose turn it is on the cycle.","options":[{"text":"Whoever grabs it first keeps it","consequence":"It becomes a grabbing race every time.","outcome":"stuck"},{"text":"Agree on a count of ten, then swap","consequence":"A simple rule ends the daily fight.","outcome":"fair","best":true}],"debrief":"A small agreed rule can repair a fight that keeps repeating.","relearn":"Agreeing a fair rule together stops the same squabble.","persona":"any","source":"compromise"},
  {"id":"ff-1297","cat":"repair","type":"branch","hook":"You apologised, your friend forgave you, but you keep apologising again.","options":[{"text":"Keep saying sorry over and over","consequence":"It starts to feel heavy for both of you.","outcome":"pushy"},{"text":"Thank them, then let it rest and play","consequence":"You both move on lighter.","outcome":"repair","best":true}],"debrief":"Once a sorry is accepted, repair means letting it rest.","relearn":"After forgiveness lands, repeating sorry isn't needed.","persona":"any","source":"repair / forgiveness"},
  {"id":"ff-1298","cat":"repair","type":"branch","hook":"Your friend was unkind, said sorry, but did the same the next day.","options":[{"text":"Accept the sorry and stay silent again","consequence":"Nothing changes, and you keep getting hurt.","outcome":"avoids"},{"text":"Say \"sorry counts when it stops, please change\"","consequence":"You ask for real change, not just words.","outcome":"repair","best":true}],"debrief":"A sorry that keeps repeating without change can be named, kindly.","relearn":"You can accept a sorry and still ask the unkindness to stop.","persona":"any","source":"repair / boundaries"},
  {"id":"ff-1299","cat":"repair","type":"branch","hook":"You laughed when others teased your friend, and now feel guilty.","options":[{"text":"Say \"everyone was laughing\"","consequence":"Blaming the crowd dodges your own part.","outcome":"excuse"},{"text":"Tell them \"I shouldn't have laughed, I'm sorry\"","consequence":"Owning it begins to rebuild their trust.","outcome":"repair","best":true}],"debrief":"Owning that your laugh hurt is braver than hiding in the crowd.","relearn":"Sorry for joining in unkindness helps a friend feel safe.","persona":"any","source":"accountability"},
  {"id":"ff-1300","cat":"repair","type":"branch","hook":"After a fight, your friend wants to make up but you're still angry.","options":[{"text":"Yell that you're not ready","consequence":"The anger spills and hurts them more.","outcome":"escalate"},{"text":"Say \"I need time, but I do want to make up\"","consequence":"Honest words keep the door open.","outcome":"repair","best":true}],"debrief":"You can need time and still tell a friend you want to repair.","relearn":"It's okay to say \"I need time\" and keep the door open.","persona":"any","source":"repair / honesty"},
  {"id":"ff-1301","cat":"repair","type":"branch","hook":"You borrowed a friend's book and lost it, and they're upset.","options":[{"text":"Say they shouldn't have lent it","consequence":"Blaming them stings and grows the fight.","outcome":"escalate"},{"text":"Say sorry and offer to replace it","consequence":"Owning and fixing it settles the upset.","outcome":"repair","best":true}],"debrief":"Owning a lost thing and offering to fix it repairs the trust.","relearn":"Sorry plus offering to make it right beats blaming or hiding.","persona":"any","source":"accountability"},
  {"id":"ff-1302","cat":"repair","type":"branch","hook":"A friend ignored you all day, then waved like nothing happened.","options":[{"text":"Ignore them right back tomorrow","consequence":"Now you're both playing cold games.","outcome":"escalate"},{"text":"Say \"that stung today, can we talk?\"","consequence":"Naming it gently opens a real make-up.","outcome":"repair","best":true}],"debrief":"Naming a hurt kindly is how hot-and-cold gets sorted.","relearn":"Gently saying \"that stung\" invites repair, not more silence.","persona":"any","source":"repair / honesty"},
  {"id":"ff-1303","cat":"repair","type":"branch","hook":"You and your friend disagree about which game to play and dig in.","options":[{"text":"Keep arguing until break ends","consequence":"You waste the whole break and play nothing.","outcome":"stuck"},{"text":"Play one game now, the other after","consequence":"You both get a turn and stay together.","outcome":"fair","best":true}],"debrief":"A small 'this now, that next' fixes lots of friendly stand-offs.","relearn":"Doing one then the other lets two friends both win.","persona":"Ananya","source":"compromise"},
  {"id":"ff-1304","cat":"repair","type":"branch","hook":"You said sorry but your friend rolled their eyes and stayed cross.","options":[{"text":"Say \"fine, be like that then\"","consequence":"Your snap undoes the sorry you just gave.","outcome":"escalate"},{"text":"Stay calm and give them a little time","consequence":"Your steadiness lets them come around.","outcome":"patient","best":true}],"debrief":"A friend may need a moment after a sorry; staying calm helps.","relearn":"If a sorry isn't taken at once, calm patience often wins.","persona":"any","source":"repair / patience"},
  {"id":"ff-1305","cat":"repair","type":"branch","hook":"You realise you've been the one being a bit of a frenemy lately.","options":[{"text":"Blame your mood and carry on","consequence":"The hurt keeps happening.","outcome":"excuse"},{"text":"Notice it, own it, and start being kinder","consequence":"Small kind moves rebuild the friendship.","outcome":"repair","best":true}],"debrief":"Catching your own frenemy moves and changing them is real repair.","relearn":"Noticing and owning your unkind moves lets you do better.","persona":"any","source":"accountability"},
  {"id":"ff-1306","cat":"repair","type":"branch","hook":"After making up, you're tempted to tell others all about the fight.","options":[{"text":"Tell everyone the juicy details","consequence":"Your friend feels betrayed all over again.","outcome":"escalate"},{"text":"Keep the make-up private between you two","consequence":"Trust deepens because you kept it safe.","outcome":"repair","best":true}],"debrief":"Keeping a repaired fight private is part of the repair.","relearn":"What you fix together stays between you; gossip undoes it.","persona":"any","source":"repair / trust"},
  {"id":"ff-1307","cat":"repair","type":"reflect","hook":"Lensy: think of a small fight you've had with a friend.","prompt":"What made it easier to make up?","options":["A calm moment","A genuine sorry","Some time to cool off","A fair fix you both liked"],"affirm":"Whatever helped, you already know one way to repair. Keep it close.","relearn":"You've found a way to make up before; you can find it again.","persona":"any","source":"reflection"},
  {"id":"ff-1308","cat":"repair","type":"reflect","hook":"Lensy: imagine a friend has just said sorry to you.","prompt":"How do you tend to feel inside?","options":["Relieved","Still a little sad","Glad they tried","Ready to play again"],"affirm":"Every feeling here is okay; you get to make up at your own pace.","relearn":"There's no one right way to feel when a friend says sorry.","persona":"any","source":"reflection"},
  {"id":"ff-1309","cat":"repair","type":"reflect","hook":"Lensy: a fight is over but a little hurt is still there.","prompt":"What might help that last bit settle?","options":["A bit more time","Saying how you feel","Doing something fun together","A quiet hug"],"affirm":"Whatever you pick, healing the last bit your own way is just fine.","relearn":"The last of a hurt can settle in its own time and its own way.","persona":"any","source":"reflection"},
  {"id":"ff-1310","cat":"repair","type":"reflect","hook":"Lensy: think about saying sorry first after a fight.","prompt":"What helps you be the one to go first?","options":["Remembering it's brave","Wanting the friend back","Knowing it's not losing","A deep breath"],"affirm":"Going first is a strong, kind choice; you can do it your way.","relearn":"Choosing to repair first is a strength you can grow.","persona":"Reyansh","source":"reflection"},
  {"id":"ff-1311","cat":"repair","type":"reflect","hook":"Lensy: a friend needs time before they can make up with you.","prompt":"What helps you wait kindly?","options":["Trusting they'll come round","Keeping busy","Staying gentle","Reminding yourself it's normal"],"affirm":"Waiting with kindness is part of repair; whatever steadies you works.","relearn":"Giving a friend time is a caring part of making up.","persona":"any","source":"reflection"},
  {"id":"ff-1312","cat":"repair","type":"reflect","hook":"Lensy: imagine forgiving a friend who hurt you.","prompt":"What does forgiving feel like for you?","options":["Setting down something heavy","A bit scary","A fresh start","Lighter inside"],"affirm":"However it feels, forgiving when you're ready is your own brave choice.","relearn":"Forgiving, in your own time, can set a heavy feeling down.","persona":"any","source":"reflection"},
  {"id":"ff-1313","cat":"repair","type":"reflect","hook":"Lensy: think of a friend you'd like to make up with.","prompt":"What small first step feels doable?","options":["A simple hello","Sitting nearby","A short sorry","Asking to talk"],"affirm":"Any small step counts; you get to choose the one that fits you.","relearn":"Repair can start with one small, doable step.","persona":"any","source":"reflection"},
  {"id":"ff-1314","cat":"repair","type":"match","hook":"Match the repair word to what it really means.","pairs":[{"left":"Cool down","right":"Wait till you're calm before you talk"},{"left":"Say sorry","right":"Own the part that was yours"},{"left":"Listen","right":"Hear their side without cutting in"},{"left":"Fair fix","right":"A plan you both agree on"},{"left":"Move on","right":"Let the hurt rest, not raise it again"}],"relearn":"Cool down, sorry, listen, fair fix, move on, that's the repair toolkit.","persona":"any","source":"conflict resolution"},
  {"id":"ff-1315","cat":"repair","type":"match","hook":"Match the start of a make-up line to how it lands.","pairs":[{"left":"\"I felt sad when...\"","right":"Opens a door to talk"},{"left":"\"You always...\"","right":"Slams the door shut"},{"left":"\"Can we talk?\"","right":"Invites a calm chat"},{"left":"\"Whatever.\"","right":"Stops repair before it starts"},{"left":"\"Sorry for my part.\"","right":"Owns your bit honestly"}],"relearn":"How you start a make-up shapes whether the door opens or shuts.","persona":"Ananya","source":"I-statements"},
  {"id":"ff-1316","cat":"repair","type":"match","hook":"Match each fix to the friend-fight it suits.","pairs":[{"left":"Both want the same toy","right":"Take turns with it"},{"left":"A muddled text fight","right":"Talk it out by call"},{"left":"You forgot a promise","right":"Own it and say sorry"},{"left":"Friend needs space","right":"Give them a little time"},{"left":"You spread a rumour","right":"Tell them and apologise"}],"relearn":"Different friend-fights have different fair fixes.","persona":"any","source":"conflict resolution"},
  {"id":"ff-1317","cat":"repair","type":"match","hook":"Match the repair step to what it sounds like.","pairs":[{"left":"Owning your part","right":"\"I was wrong to snap.\""},{"left":"Sharing a feeling","right":"\"That really hurt me.\""},{"left":"Checking in","right":"\"Are we okay now?\""},{"left":"Offering a fix","right":"\"How can I make it right?\""},{"left":"Making up","right":"\"Friends again?\""}],"relearn":"Each repair step has its own simple, honest words.","persona":"any","source":"apology steps"},
  {"id":"ff-1318","cat":"repair","type":"match","hook":"Match the move to whether it mends or breaks.","pairs":[{"left":"Listening to their side","right":"Mends the friendship"},{"left":"Bringing up old fights","right":"Reopens old hurts"},{"left":"Saying sorry sincerely","right":"Starts to rebuild trust"},{"left":"Giving silent treatment","right":"Freezes things over"},{"left":"Finding a fair fix","right":"Settles it for good"}],"relearn":"Some moves mend a friendship; scorekeeping and silence don't.","persona":"any","source":"conflict resolution"},
  {"id":"ff-1319","cat":"repair","type":"match","hook":"Match the feeling after a fight to a kind thing to do.","pairs":[{"left":"Still angry","right":"Take a little time to cool off"},{"left":"Sad and quiet","right":"Tell a friend how you feel"},{"left":"Ready to make up","right":"Go and say a gentle sorry"},{"left":"Confused why they're cross","right":"Ask them to help you understand"},{"left":"Guilty you were unkind","right":"Own it and apologise"}],"relearn":"Whatever you feel after a fight, there's a kind next step.","persona":"any","source":"perspective-taking"},
  {"id":"ff-1320","cat":"repair","type":"match","hook":"Match the unhelpful habit to the repair move that beats it.","pairs":[{"left":"Keeping score","right":"Owning just your own part"},{"left":"Going silent","right":"Saying how you feel out loud"},{"left":"Gossiping about it","right":"Keeping the make-up private"},{"left":"Blaming them","right":"Asking for a fair fix together"},{"left":"Rushing them","right":"Giving them a little time"}],"relearn":"For every habit that breaks trust, there's a move that rebuilds it.","persona":"any","source":"conflict resolution"},
  {"id":"ff-1321","cat":"repair","type":"match","hook":"Match the repair idea to the true thing it teaches.","pairs":[{"left":"All friends disagree","right":"Fighting sometimes is normal"},{"left":"Going first to say sorry","right":"Is brave, not losing"},{"left":"Repair needs time","right":"You can't force someone ready"},{"left":"Accept a sorry","right":"You can still be honest"},{"left":"A fair fix","right":"Works only if you both keep it"}],"relearn":"Repair truths: fights are normal, sorry is brave, it takes time.","persona":"any","source":"conflict / repair"},
  {"id":"ff-1322","cat":"repair","type":"sort","hook":"After a fight: which words open repair, which shut it down?","items":[{"id":"a","text":"\"I felt hurt when that happened.\""},{"id":"b","text":"\"You always ruin everything.\""},{"id":"c","text":"\"Can we talk about it?\""},{"id":"d","text":"\"It's all your fault.\""},{"id":"e","text":"\"Sorry for my part in it.\""},{"id":"f","text":"\"Whatever, forget it.\""}],"bins":[{"id":"open","label":"Opens repair","valence":"pos"},{"id":"shut","label":"Shuts it down","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"\"I felt...\" and \"can we talk\" open a door; blame and \"whatever\" slam it.","persona":"Ananya","source":"I-statements"},
  {"id":"ff-1323","cat":"repair","type":"sort","hook":"Sort each move: does it rebuild trust or break it more?","items":[{"id":"a","text":"Keep your next promise"},{"id":"b","text":"Tell others their secret"},{"id":"c","text":"Listen when they share"},{"id":"d","text":"Bring up the fight daily"},{"id":"e","text":"Own your mistake"},{"id":"f","text":"Give silent treatment"}],"bins":[{"id":"build","label":"Rebuilds trust","valence":"pos"},{"id":"break","label":"Breaks it more","valence":"neg"}],"key":{"a":"build","b":"break","c":"build","d":"break","e":"build","f":"break"},"relearn":"Kept promises, listening and owning rebuild; gossip and silence break.","persona":"any","source":"repair / trust"},
  {"id":"ff-1324","cat":"repair","type":"sort","hook":"Sort the steps: which come before the make-up talk?","items":[{"id":"a","text":"Take a few deep breaths"},{"id":"b","text":"Say sorry for your part"},{"id":"c","text":"Step away to cool off"},{"id":"d","text":"Agree on a fair fix"},{"id":"e","text":"Let your temper settle"},{"id":"f","text":"Listen to their side"}],"bins":[{"id":"cool","label":"Cool-down first","valence":"neutral"},{"id":"talk","label":"During the talk","valence":"pos"}],"key":{"a":"cool","b":"talk","c":"cool","d":"talk","e":"cool","f":"talk"},"relearn":"Cool down first, then share, listen, sorry and a fair fix.","persona":"any","source":"cool-down"},
  {"id":"ff-1325","cat":"repair","type":"sort","hook":"Sort each reply to a friend's sorry: kind-and-honest, or unkind?","items":[{"id":"a","text":"\"Thanks, I'm still a bit sad.\""},{"id":"b","text":"\"You should be sorry.\""},{"id":"c","text":"\"Thank you, friends again?\""},{"id":"d","text":"\"Took you long enough.\""},{"id":"e","text":"\"I forgive you, let's move on.\""},{"id":"f","text":"\"I'll never forget this.\""}],"bins":[{"id":"kind","label":"Kind and honest","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"You can take a sorry warmly and still say how you feel.","persona":"any","source":"repair / forgiveness"},
  {"id":"ff-1326","cat":"repair","type":"sort","hook":"Sort each: is it a real sorry, or a fake one?","items":[{"id":"a","text":"\"I'm sorry I hurt you.\""},{"id":"b","text":"\"Sorry, but you started it.\""},{"id":"c","text":"\"I was wrong, I'll change.\""},{"id":"d","text":"\"Sorry you're so sensitive.\""},{"id":"e","text":"\"I'm sorry, how can I fix it?\""},{"id":"f","text":"\"Sorry, okay? Drop it.\""}],"bins":[{"id":"real","label":"Real sorry","valence":"pos"},{"id":"fake","label":"Not a real sorry","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"A real sorry owns the hurt; \"sorry but...\" just shifts the blame.","persona":"any","source":"repair / sincerity"},
  {"id":"ff-1327","cat":"repair","type":"sort","hook":"Sort each habit: does it help a friendship heal or keep it sore?","items":[{"id":"a","text":"Talking it out kindly"},{"id":"b","text":"Bottling it all up"},{"id":"c","text":"Asking a calm question"},{"id":"d","text":"Gossiping to others"},{"id":"e","text":"Giving a true sorry"},{"id":"f","text":"Keeping a tally of wrongs"}],"bins":[{"id":"heal","label":"Helps it heal","valence":"pos"},{"id":"sore","label":"Keeps it sore","valence":"neg"}],"key":{"a":"heal","b":"sore","c":"heal","d":"sore","e":"heal","f":"sore"},"relearn":"Talking, asking and a true sorry heal; bottling and tallying don't.","persona":"any","source":"conflict resolution"},
  {"id":"ff-1328","cat":"repair","type":"sort","hook":"Sort each fall-out: what's a fair next move?","items":[{"id":"a","text":"You forgot a promise"},{"id":"b","text":"You both want the swing"},{"id":"c","text":"You lost their pencil"},{"id":"d","text":"You snapped on a bad day"},{"id":"e","text":"You both want to bat first"},{"id":"f","text":"You spread a secret"}],"bins":[{"id":"own","label":"Own it and say sorry","valence":"pos"},{"id":"share","label":"Share it fairly","valence":"neutral"}],"key":{"a":"own","b":"share","c":"own","d":"own","e":"share","f":"own"},"relearn":"When it's your slip, own it; when it's a clash, find a fair share.","persona":"any","source":"conflict resolution"},
  {"id":"ff-1350","cat":"stand-up","type":"role-play","hook":"A classmate keeps calling you a baby in front of everyone.","setup":"Say the calm, clear line.","yourLine":[{"text":"\"Stop. I don't like being called that.\"","best":true},{"text":"Pretend you didn't hear"},{"text":"Call them a worse name"}],"relearn":"A calm, clear \"stop, I don't like that\" is strong, not rude.","persona":"Faizan","source":"assertiveness"},
  {"id":"ff-1351","cat":"stand-up","type":"role-play","hook":"Someone says \"only boys can play cricket\" at the maidan.","setup":"Reyansh wants a line that wins it tomorrow. Pick yours.","yourLine":[{"text":"\"Games are for everyone. Let's pick teams.\"","best":true},{"text":"Walk off the maidan"},{"text":"\"You're so stupid!\""}],"relearn":"\"Games are for everyone\" is a comeback you can really use.","persona":"Reyansh","source":"gender norms / comebacks"},
  {"id":"ff-1352","cat":"stand-up","type":"role-play","hook":"A new girl is standing alone at the edge of the kho-kho game.","setup":"Be the one who includes her. What do you say?","yourLine":[{"text":"\"Come on, you can be on our team.\"","best":true},{"text":"Look away"},{"text":"\"We're full, find someone else.\""}],"relearn":"Inviting a left-out kid in is one of the easiest ally moves.","persona":"any","source":"inclusion / ally"},
  {"id":"ff-1353","cat":"stand-up","type":"role-play","hook":"Kids are chanting a nickname to make your friend cry.","setup":"Give your friend an exit. What do you say?","yourLine":[{"text":"\"Come on, let's go get water.\"","best":true},{"text":"Join the chant"},{"text":"Stand and stare"}],"relearn":"Giving a friend an exit (\"come on, let's go\") helps them step away.","persona":"any","source":"ally / exit-line"},
  {"id":"ff-1354","cat":"stand-up","type":"role-play","hook":"Someone starts a rumour that your friend cheated in the test.","setup":"What do you say when kids repeat it to you?","yourLine":[{"text":"\"I won't pass that on, it's not kind.\"","best":true},{"text":"Tell three more people"},{"text":"\"Really? Tell me more!\""}],"relearn":"Refusing to pass a rumour on helps it die out.","persona":"Ananya","source":"rumours / bystander"},
  {"id":"ff-1355","cat":"stand-up","type":"role-play","hook":"A bigger kid keeps cutting the lunch line ahead of you.","setup":"Say the line that holds your spot, calmly.","yourLine":[{"text":"\"I was here first. Please wait your turn.\"","best":true},{"text":"Give up your place"},{"text":"Shove them out"}],"relearn":"\"I was here first, please wait\" claims your turn without a fight.","persona":"any","source":"assertiveness"},
  {"id":"ff-1356","cat":"stand-up","type":"role-play","hook":"Your friend's drawing is being laughed at by the group.","setup":"Stand beside your friend. What do you say?","yourLine":[{"text":"\"I think it's lovely. Let's see yours then.\"","best":true},{"text":"Laugh along quietly"},{"text":"Snatch the drawing away"}],"relearn":"Backing a friend out loud tells them they're not alone.","persona":"Faizan","source":"ally / support"},
  {"id":"ff-1357","cat":"stand-up","type":"role-play","hook":"A kid says \"girls can't do maths\" when Ananya answers fast.","setup":"Ananya wants a calm comeback. Pick it.","yourLine":[{"text":"\"Anyone can do maths. I just did.\"","best":true},{"text":"Get the next one wrong on purpose"},{"text":"\"Shut up, you fail everything!\""}],"relearn":"A calm \"anyone can do this\" flips a silly playground rule.","persona":"Ananya","source":"gender norms / comebacks"},
  {"id":"ff-1358","cat":"stand-up","type":"role-play","hook":"Someone keeps poking your back during assembly to annoy you.","setup":"Say the quiet boundary line.","yourLine":[{"text":"\"Please stop poking me.\"","best":true},{"text":"Poke them back harder"},{"text":"Move and say nothing, again"}],"relearn":"\"Please stop\" said calmly is a strong boundary, not rudeness.","persona":"any","source":"assertiveness"},
  {"id":"ff-1359","cat":"stand-up","type":"role-play","hook":"Your team is mocking a slower runner on sports day.","setup":"Be the ally for the runner. What do you call out?","yourLine":[{"text":"\"Keep going, you've got this!\"","best":true},{"text":"Mock them too"},{"text":"Say nothing"}],"relearn":"Cheering instead of mocking turns a crowd kind.","persona":"any","source":"ally / encouragement"},
  {"id":"ff-1360","cat":"stand-up","type":"role-play","hook":"A friend is dared to throw chalk at the teacher's chair.","setup":"Help your friend say no. What do you say?","yourLine":[{"text":"\"You don't have to. Let's go play.\"","best":true},{"text":"\"Do it, do it!\""},{"text":"Film it on a phone"}],"relearn":"Helping a friend say no to a dare is the strong move.","persona":"any","source":"peer pressure / ally"},
  {"id":"ff-1361","cat":"stand-up","type":"role-play","hook":"Kids tease Faizan because his shoes are old.","setup":"Be the one who stands with him. What do you say?","yourLine":[{"text":"\"His shoes are fine. Let's just play.\"","best":true},{"text":"Giggle along"},{"text":"Point at the shoes too"}],"relearn":"Standing with a teased friend says the teasing isn't okay.","persona":"Faizan","source":"ally / belonging"},
  {"id":"ff-1362","cat":"stand-up","type":"role-play","hook":"Someone says \"pink tiffin is for girls\" about your box.","setup":"Reyansh wants a line for tomorrow. Pick yours.","yourLine":[{"text":"\"Colours are for everyone.\"","best":true},{"text":"Hide the tiffin"},{"text":"\"No it's NOT!\" (just louder)"}],"relearn":"\"Colours are for everyone\" is a comeback you can actually use.","persona":"Reyansh","source":"gender norms / comebacks"},
  {"id":"ff-1363","cat":"stand-up","type":"role-play","hook":"A friend keeps repeating a secret you asked them to keep.","setup":"Say the honest, calm line.","yourLine":[{"text":"\"That was private. Please don't share it.\"","best":true},{"text":"Pretend you don't mind"},{"text":"Spill one of their secrets"}],"relearn":"Naming a broken confidence calmly is fair, not a fight.","persona":"any","source":"boundaries"},
  {"id":"ff-1364","cat":"stand-up","type":"role-play","hook":"The group won't let one boy join because he \"cries too much.\"","setup":"Speak up for everyone playing. What do you say?","yourLine":[{"text":"\"Everyone plays here. Come on in.\"","best":true},{"text":"Shrug and join the game"},{"text":"\"Yeah, cry-baby, go away.\""}],"relearn":"One voice for \"everyone plays\" can change the whole game.","persona":"any","source":"inclusion / ally"},
  {"id":"ff-1365","cat":"stand-up","type":"role-play","hook":"A kid keeps calling your accent \"funny\" and copying it.","setup":"Say the line that stops it, calmly.","yourLine":[{"text":"\"That's how I talk. Please stop copying me.\"","best":true},{"text":"Stop talking in class"},{"text":"Mock their voice back"}],"relearn":"Calmly naming what to stop is assertive, not aggressive.","persona":"Faizan","source":"assertiveness / belonging"},
  {"id":"ff-1366","cat":"stand-up","type":"role-play","hook":"Someone is being left out of the WhatsApp study group on purpose.","setup":"Be the ally in the chat. What do you type?","yourLine":[{"text":"\"Let's add Meera, she's in our class too.\"","best":true},{"text":"Say nothing in the chat"},{"text":"\"Yeah, leave her out, lol\""}],"relearn":"Speaking up online to include someone counts just as much.","persona":"any","source":"online / inclusion"},
  {"id":"ff-1367","cat":"stand-up","type":"role-play","hook":"A friend froze when teased and couldn't say anything.","setup":"Check on them after. What do you say?","yourLine":[{"text":"\"You okay? That wasn't fair to you.\"","best":true},{"text":"\"Why didn't you say something?\""},{"text":"Pretend nothing happened"}],"relearn":"A quiet \"you okay?\" tells someone they're not alone.","persona":"Faizan","source":"support / empathy"},
  {"id":"ff-1368","cat":"stand-up","type":"role-play","hook":"Older kids tell you to give up your swing or \"else.\"","setup":"Say the firm line, then plan your next step.","yourLine":[{"text":"\"I'm using it now. You can have it after.\"","best":true},{"text":"Hand it over scared"},{"text":"Scream and push them"}],"relearn":"Holding your turn calmly is allowed; you don't owe \"or else.\"","persona":"any","source":"assertiveness"},
  {"id":"ff-1369","cat":"stand-up","type":"role-play","hook":"A classmate is being mocked for stammering when they read aloud.","setup":"Be the ally. What do you say to the class?","yourLine":[{"text":"\"Take your time. We're listening.\"","best":true},{"text":"Finish their words for them"},{"text":"Laugh with the others"}],"relearn":"Patience said out loud turns a hard moment kind.","persona":"any","source":"ally / empathy"},
  {"id":"ff-1370","cat":"stand-up","type":"role-play","hook":"Someone says \"that game is babyish, stop playing it.\"","setup":"Keep your own mind. Say your line.","yourLine":[{"text":"\"I like it, so I'll play it.\"","best":true},{"text":"Throw the game away"},{"text":"\"Yours is babyish too!\""}],"relearn":"You can keep your own taste; liking different things is fine.","persona":"Reyansh","source":"autonomy / comebacks"},
  {"id":"ff-1371","cat":"stand-up","type":"role-play","hook":"A kid keeps grabbing your homework to copy it every day.","setup":"Say the kind-but-clear line.","yourLine":[{"text":"\"I'll help you understand it, not copy it.\"","best":true},{"text":"Hand it over again"},{"text":"\"You're a cheater!\" loudly"}],"relearn":"Offering to help, not hand over, is a fair and kind line.","persona":"any","source":"boundaries / honesty"},
  {"id":"ff-1372","cat":"stand-up","type":"role-play","hook":"Your friend is being teased for liking dolls, said \"that's girly.\"","setup":"Stand with your friend. What do you say?","yourLine":[{"text":"\"Toys are for everyone. Let's play.\"","best":true},{"text":"Move away from your friend"},{"text":"\"Yeah, that's so girly!\""}],"relearn":"\"Toys are for everyone\" includes a friend without a fight.","persona":"any","source":"gender norms / ally"},
  {"id":"ff-1373","cat":"stand-up","type":"role-play","hook":"A loud kid keeps interrupting your idea in the group project.","setup":"Claim your turn calmly.","yourLine":[{"text":"\"Let me finish, then I want to hear you.\"","best":true},{"text":"Go silent for the rest"},{"text":"Talk louder over them"}],"relearn":"\"Let me finish, then your turn\" shares the space fairly.","persona":"Ananya","source":"assertiveness"},
  {"id":"ff-1374","cat":"stand-up","type":"role-play","hook":"Kids are passing around a mean drawing of a classmate.","setup":"Refuse to be part of it. What do you say?","yourLine":[{"text":"\"I won't pass this on. It's unkind.\"","best":true},{"text":"Add a meaner caption"},{"text":"Quietly pass it along"}],"relearn":"Refusing to pass it on stops a mean thing from spreading.","persona":"any","source":"bystander / rumours"},
  {"id":"ff-1375","cat":"stand-up","type":"role-play","hook":"A friend whispers to ditch another friend \"to teach her a lesson.\"","setup":"Say no to the freeze-out. What do you say?","yourLine":[{"text":"\"I'm not going to ignore her. That's not fair.\"","best":true},{"text":"Go along to keep the peace"},{"text":"\"Yeah, let's freeze her out.\""}],"relearn":"Saying no to a freeze-out keeps you a friend to both.","persona":"Ananya","source":"exclusion / values"},
  {"id":"ff-1376","cat":"stand-up","type":"role-play","hook":"Someone keeps mimicking the way your friend walks.","setup":"Step in for your friend. What do you say?","yourLine":[{"text":"\"Cut it out. That's not funny.\"","best":true},{"text":"Copy the walk too"},{"text":"Look at the floor"}],"relearn":"A clear \"cut it out\" names the behaviour without a brawl.","persona":"any","source":"ally / assertiveness"},
  {"id":"ff-1377","cat":"stand-up","type":"role-play","hook":"A kid says \"long hair on boys is weird\" about your friend.","setup":"Reyansh wants a calm comeback. Pick it.","yourLine":[{"text":"\"Hair is hair. It's nobody's rule.\"","best":true},{"text":"Agree to fit in"},{"text":"\"Your face is weird!\""}],"relearn":"A calm comeback can flip a silly \"that's not allowed\" rule.","persona":"Reyansh","source":"gender norms / comebacks"},
  {"id":"ff-1378","cat":"stand-up","type":"role-play","hook":"Your friend is too scared to tell the teacher about a bully.","setup":"Offer to go with them. What do you say?","yourLine":[{"text":"\"I'll come with you to tell Ma'am.\"","best":true},{"text":"\"Just ignore it forever.\""},{"text":"Tell them they're being a baby"}],"relearn":"Offering to go along makes the brave step-two easier.","persona":"any","source":"help-seeking / ally"},
  {"id":"ff-1379","cat":"stand-up","type":"role-play","hook":"Kids dare you to repeat a swear word about a teacher.","setup":"Say no for yourself. What's your line?","yourLine":[{"text":"\"No thanks, I'm not doing that.\"","best":true},{"text":"Say it to fit in"},{"text":"Dare someone smaller instead"}],"relearn":"A simple \"no thanks\" is enough; a dare doesn't cancel right.","persona":"any","source":"peer pressure"},
  {"id":"ff-1380","cat":"stand-up","type":"role-play","hook":"A classmate keeps \"jokingly\" hiding your school bag.","setup":"Say the calm boundary line.","yourLine":[{"text":"\"It's not funny to me. Please give it back.\"","best":true},{"text":"Hide theirs next time"},{"text":"Laugh so they don't see you mind"}],"relearn":"\"It's not funny to me\" names your line without anger.","persona":"any","source":"assertiveness"},
  {"id":"ff-1381","cat":"stand-up","type":"role-play","hook":"Your friend is being blamed for something they didn't do.","setup":"Speak up with the truth. What do you say?","yourLine":[{"text":"\"That wasn't her. I saw what happened.\"","best":true},{"text":"Stay quiet to avoid trouble"},{"text":"Let them take the blame"}],"relearn":"Speaking a true word for a friend is exactly your business.","persona":"Ananya","source":"fairness / ally"},
  {"id":"ff-1382","cat":"stand-up","type":"role-play","hook":"A kid keeps saying \"you're not really our friend\" to control you.","setup":"Keep your own mind. Say your line.","yourLine":[{"text":"\"I'm allowed my own friends too.\"","best":true},{"text":"Drop your other friends"},{"text":"\"Fine, I hate you!\""}],"relearn":"You can keep your own mind; \"or you're out\" is a control flag.","persona":"any","source":"control / autonomy"},
  {"id":"ff-1383","cat":"stand-up","type":"branch","hook":"You said your calm line and the name-calling didn't stop.","options":[{"text":"Put up with it and say nothing","consequence":"It keeps going and you feel worse.","outcome":"stuck"},{"text":"Walk away and tell a trusted adult","consequence":"Grown-ups can step in when words aren't enough.","outcome":"help","best":true}],"debrief":"Speaking up is step one; telling a trusted adult is the brave step two.","relearn":"If standing up doesn't work, telling a trusted adult is the next move, not a fail.","persona":"Faizan","source":"escalation / help-seeking"},
  {"id":"ff-1384","cat":"stand-up","type":"branch","hook":"In the class chat, kids pile mean replies onto one classmate.","options":[{"text":"Scroll past so nobody turns on you","consequence":"The pile-on grows; they read every line.","outcome":"stuck"},{"text":"Message them privately and screenshot it for a teacher","consequence":"They feel less alone; an adult can step in.","outcome":"help","best":true}],"debrief":"A private check-in plus saved proof counts as stepping in.","relearn":"Stand up in a chat by reaching the target privately and saving proof.","persona":"any","source":"bystander / online"},
  {"id":"ff-1385","cat":"stand-up","type":"branch","hook":"A group keeps shutting one kid out of every game at break.","options":[{"text":"Join the game and ignore it","consequence":"Easier, but that kid stays alone.","outcome":"stuck"},{"text":"Say \"everyone plays\" and invite them in","consequence":"One voice can open the whole game up.","outcome":"include","best":true}],"debrief":"When a group excludes, one voice for \"everyone plays\" can change the moment.","relearn":"A bystander who says \"everyone plays\" can turn exclusion around.","persona":"any","source":"exclusion / ally"},
  {"id":"ff-1386","cat":"stand-up","type":"branch","hook":"After you reported a teammate's cheating, they call you a snitch.","options":[{"text":"Apologise and take the report back","consequence":"The cheating stands; you feel worse.","outcome":"doubt"},{"text":"Hold your ground; fairness beat their approval","consequence":"Teammates who want a fair game back you.","outcome":"values","best":true}],"debrief":"Being called a name for a fair act stings, but the label isn't the truth.","relearn":"Choosing fairness can cost popularity and still be right.","persona":"Ananya","source":"values / fairness"},
  {"id":"ff-1387","cat":"stand-up","type":"branch","hook":"Kids keep daring you to skip class with them or \"you're not cool.\"","options":[{"text":"Skip class so they stay your friends","consequence":"You break a rule and still feel uneasy.","outcome":"regret"},{"text":"Say no and keep your own mind","consequence":"Real friends don't make you choose wrong to belong.","outcome":"values","best":true}],"debrief":"A dare doesn't cancel right and wrong; saying no is the strong move.","relearn":"Real friends won't make you pick between them and doing what's right.","persona":"any","source":"peer pressure"},
  {"id":"ff-1388","cat":"stand-up","type":"branch","hook":"A friend asks you NOT to tell anyone a bully keeps hurting them.","options":[{"text":"Keep it secret because they asked","consequence":"The hurting carries on with no help.","outcome":"stuck"},{"text":"Tell a trusted adult, even though it's hard","consequence":"That's how you truly help a friend.","outcome":"help","best":true}],"debrief":"For bullying, tell a trusted adult, even if a friend asks you not to.","relearn":"Telling a trusted adult about bullying is how you really help, not betrayal.","persona":"any","source":"bullying / help-seeking"},
  {"id":"ff-1389","cat":"stand-up","type":"branch","hook":"You froze and didn't speak up when a kid was being teased today.","options":[{"text":"Decide you're just no good at this","consequence":"You feel ashamed and try even less.","outcome":"shame"},{"text":"Plan one small line to try next time","consequence":"Bravery grows with practice, no shame in slipping.","outcome":"growth","best":true}],"debrief":"Freezing once doesn't mean you failed; you can plan a line for next time.","relearn":"Standing up is a skill; it gets easier each time you try.","persona":"any","source":"self-efficacy"},
  {"id":"ff-1390","cat":"stand-up","type":"branch","hook":"A kid in the group chat is threatened: \"reply or you're out.\"","options":[{"text":"Stay quiet so you're not next","consequence":"The threat works and the kid feels alone.","outcome":"stuck"},{"text":"Message the kid kindly and tell an adult","consequence":"Online meanness needs grown-up help too.","outcome":"help","best":true}],"debrief":"Threatened exclusion online is a control flag; telling an adult helps.","relearn":"Frenemy flags appear online too; speak up and get help.","persona":"any","source":"online / help-seeking"},
  {"id":"ff-1391","cat":"stand-up","type":"branch","hook":"Your friend wants you to help ignore a kid you actually like.","options":[{"text":"Ignore the kid to keep your friend happy","consequence":"You hurt someone to please someone.","outcome":"regret"},{"text":"Stay kind to both and say so","consequence":"You can be a good friend to more than one person.","outcome":"values","best":true}],"debrief":"You don't have to pick a side or freeze someone out to keep a friend.","relearn":"You can be a good friend to both without joining a freeze-out.","persona":"Ananya","source":"exclusion / values"},
  {"id":"ff-1392","cat":"stand-up","type":"branch","hook":"A bigger kid takes your snack and says \"tell anyone and you'll see.\"","options":[{"text":"Hand it over in silence each day","consequence":"It keeps happening and you dread break.","outcome":"stuck"},{"text":"Tell a trusted adult, threat or not","consequence":"Threats are exactly when to get help.","outcome":"help","best":true}],"debrief":"A \"tell anyone and you'll see\" threat is a reason TO tell, not to hide it.","relearn":"When someone threatens you to stay silent, telling an adult is brave.","persona":"Faizan","source":"safety / help-seeking"},
  {"id":"ff-1393","cat":"stand-up","type":"branch","hook":"You hear kids planning to gang up on someone after school.","options":[{"text":"Mind your own business and go home","consequence":"Someone gets hurt and you knew.","outcome":"stuck"},{"text":"Tell a trusted adult before it happens","consequence":"Telling beforehand can stop it; that's brave.","outcome":"help","best":true}],"debrief":"Telling a trusted adult to PREVENT harm is brave, not tattling.","relearn":"Warning a trusted adult before someone gets hurt is the brave thing.","persona":"any","source":"bystander / help-seeking"},
  {"id":"ff-1394","cat":"stand-up","type":"branch","hook":"A classmate teases you and laughs harder when you ask them to stop.","options":[{"text":"Tease back even harder","consequence":"It becomes a fight and you both get in trouble.","outcome":"escalate"},{"text":"Say your line once, then walk away and get help","consequence":"Calm plus help beats a shouting match.","outcome":"help","best":true}],"debrief":"If a calm line is mocked, you can walk away and tell an adult.","relearn":"When your words are ignored, walking away and telling an adult is next.","persona":"any","source":"escalation"},
  {"id":"ff-1395","cat":"stand-up","type":"strike-rewrite","hook":"\"Telling a teacher about a bully is tattling.\"","myth":{"un":"Telling a grown-up about a bully is just tattling.","re":"Getting help for bullying is brave, not tattling; it's how you stop real harm.","why":"Tattling is to get someone in trouble; this is to keep someone safe."},"relearn":"For bullying, telling a trusted adult is the brave step, not tattling.","persona":"any","source":"help-seeking"},
  {"id":"ff-1396","cat":"stand-up","type":"strike-rewrite","hook":"\"Standing up for someone is none of my business.\"","myth":{"un":"If it isn't happening to me, it's none of my business.","re":"A bystander who speaks up can stop it; staying silent lets it grow.","why":"Friends look out for each other, and for those with no one."},"relearn":"Speaking up for someone else is exactly a friend's business.","persona":"any","source":"bystander research"},
  {"id":"ff-1397","cat":"stand-up","type":"strike-rewrite","hook":"\"Being assertive means being rude.\"","myth":{"un":"Saying \"stop, I don't like that\" is rude and mean.","re":"A calm, clear \"stop\" is assertive, not aggressive; you can be firm and kind.","why":"Assertive says what you need; rude attacks the other person."},"relearn":"A calm, clear boundary line is strong, not rude.","persona":"any","source":"assertiveness"},
  {"id":"ff-1398","cat":"stand-up","type":"strike-rewrite","hook":"\"If you can't beat the teasing with a comeback, you lose.\"","myth":{"un":"If you don't win the comeback war, you've lost.","re":"Walking away or getting help isn't losing; it's a smart, safe choice.","why":"There's no scoreboard; staying calm and safe is the real win."},"relearn":"Walking away or getting help is a strong move, not a loss.","persona":"Reyansh","source":"comebacks / values"},
  {"id":"ff-1399","cat":"stand-up","type":"strike-rewrite","hook":"\"Passing on a rumour is just sharing news.\"","myth":{"un":"Repeating a rumour is only sharing the news.","re":"Refusing to pass a rumour on helps it die out instead of spreading hurt.","why":"A rumour grows only when people repeat it; you can stop it."},"relearn":"Refusing to pass on a rumour helps it die out.","persona":"any","source":"rumours"},
  {"id":"ff-1400","cat":"stand-up","type":"strike-rewrite","hook":"\"A real friend would never make you say no to them.\"","myth":{"un":"If they're a real friend, you should never refuse them.","re":"Real friends respect your no; \"do it or you're out\" is a control flag.","why":"Saying no when something's wrong is allowed, even with a friend."},"relearn":"You can say no to a friend; that's your own mind, not betrayal.","persona":"any","source":"control / autonomy"},
  {"id":"ff-1401","cat":"stand-up","type":"strike-rewrite","hook":"\"Only big kids or teachers can stop bullying.\"","myth":{"un":"Stopping unkindness is only for big kids and grown-ups.","re":"Even one kid's voice or an invite to play can change a mean moment.","why":"Small, calm actions from a bystander really do help."},"relearn":"One kid speaking up, or fetching an adult, can change the moment.","persona":"Faizan","source":"bystander / efficacy"},
  {"id":"ff-1402","cat":"stand-up","type":"reflect","hook":"Lensy: which is hardest for you, saying stop, or backing up a friend?","prompt":"Be honest with yourself, there's no wrong answer.","options":["Saying stop for me","Backing up someone else","Both are hard","I'm getting braver"],"affirm":"Naming the hard one is how you practise it; bravery grows with reps.","relearn":"Naming the hard one is how you practise it; bravery grows with reps.","persona":"any","source":"self-efficacy"},
  {"id":"ff-1403","cat":"stand-up","type":"reflect","hook":"Lensy: when a friend is teased, what feels most like you?","prompt":"Just notice what's true for you today.","options":["I speak up right away","I check on them after","I freeze and feel bad","I want to but I'm scared"],"affirm":"Every honest answer is a real starting point; there's no wrong one.","relearn":"Every honest answer is a real starting point; there's no wrong one.","persona":"any","source":"empathy"},
  {"id":"ff-1404","cat":"stand-up","type":"reflect","hook":"Lensy: what kind of comeback feels right to you?","prompt":"Pick the one that fits you.","options":["A calm clear line","A funny line","Just walking away","Getting a friend to help"],"affirm":"All of these can be brave; the best one is the one you'll actually use.","relearn":"All of these can be brave; the best one is the one you'll actually use.","persona":"Reyansh","source":"comebacks"},
  {"id":"ff-1405","cat":"stand-up","type":"reflect","hook":"Lensy: who would you tell if standing up didn't work?","prompt":"Think of your trusted grown-up.","options":["A parent","A teacher","An older sibling","I'm not sure yet"],"affirm":"Knowing who you'd tell makes the brave step two easier when you need it.","relearn":"Knowing who you'd tell makes the brave step two easier when you need it.","persona":"any","source":"help-seeking"},
  {"id":"ff-1406","cat":"stand-up","type":"reflect","hook":"Lensy: how do you feel after you stand up for someone?","prompt":"Notice the feeling, whatever it is.","options":["Proud","Shaky but glad","Worried they're mad","A bit of everything"],"affirm":"Brave things can feel shaky and proud at once; both are okay.","relearn":"Brave things can feel shaky and proud at once; both are okay.","persona":"Ananya","source":"self-reflection"},
  {"id":"ff-1407","cat":"stand-up","type":"reflect","hook":"Lensy: what stops you from saying the line out loud?","prompt":"Be kind and honest with yourself.","options":["Scared of what they'll do","Worried I'll get it wrong","Don't want a fight","Nothing, I just go for it"],"affirm":"Spotting what stops you is the first step to getting past it.","relearn":"Spotting what stops you is the first step to getting past it.","persona":"Faizan","source":"self-efficacy"},
  {"id":"ff-1408","cat":"stand-up","type":"reflect","hook":"Lensy: when someone's unkind to you, what do you remind yourself?","prompt":"Choose the thought that helps you.","options":["It's their choice, not my fault","I can ask for help","I'm allowed to walk away","I'm braver than I feel"],"affirm":"All of these are true; unkindness is their choice, not your worth.","relearn":"All of these are true; unkindness is their choice, not your worth.","persona":"any","source":"self-worth"},
  {"id":"ff-1409","cat":"stand-up","type":"build","hook":"Lensy: build a brave stand-up plan, in order.","prompt":"Put the steps for standing up in order.","pieces":["Say a calm clear line","Give the kid an exit","Walk away if it keeps up","Tell a trusted adult","Tease them back","Cry and give in"],"mode":"sequence","key":["Say a calm clear line","Give the kid an exit","Walk away if it keeps up","Tell a trusted adult"],"relearn":"Stand-up plan: say the line, offer an exit, walk away, then tell an adult.","persona":"any","source":"escalation / plan"},
  {"id":"ff-1410","cat":"stand-up","type":"build","hook":"Build a kit of good comebacks you could actually use.","prompt":"Pick the comebacks that include, not start a war.","pieces":["\"Colours are for everyone.\"","\"Let's all play.\"","\"Anyone can do this.\"","\"Games are for everyone.\"","\"You're so stupid!\"","\"I'll fight you!\""],"mode":"assemble","key":["\"Colours are for everyone.\"","\"Let's all play.\"","\"Anyone can do this.\"","\"Games are for everyone.\""],"relearn":"Good comebacks include people; they don't start a war.","persona":"Reyansh","source":"comebacks"},
  {"id":"ff-1411","cat":"stand-up","type":"build","hook":"Build the steps to be an ally when you see teasing.","prompt":"Put the ally moves in order.","pieces":["Stand near the teased kid","Say \"that's not okay\"","Give them an exit line","Check on them after","Join the teasing","Film it for fun"],"mode":"sequence","key":["Stand near the teased kid","Say \"that's not okay\"","Give them an exit line","Check on them after"],"relearn":"Ally steps: stand close, name it, give an exit, then check in after.","persona":"any","source":"bystander / ally"},
  {"id":"ff-1412","cat":"stand-up","type":"build","hook":"Build your \"who to tell\" list of trusted grown-ups.","prompt":"Pick the people you could go to for help.","pieces":["A parent","A teacher","An older sibling","A school counsellor","The bully's friend","A stranger online"],"mode":"assemble","key":["A parent","A teacher","An older sibling","A school counsellor"],"relearn":"Trusted grown-ups to tell: a parent, teacher, older sibling or counsellor.","persona":"any","source":"help-seeking"},
  {"id":"ff-1413","cat":"stand-up","type":"build","hook":"Build a calm boundary line, piece by piece.","prompt":"Pick the parts that make a kind, clear boundary.","pieces":["\"Stop\"","\"I don't like that\"","\"please\"","said calmly","shouted in their face","with a shove"],"mode":"assemble","key":["\"Stop\"","\"I don't like that\"","\"please\"","said calmly"],"relearn":"A boundary line is calm and clear: \"Stop, I don't like that, please.\"","persona":"any","source":"assertiveness"},
  {"id":"ff-1414","cat":"stand-up","type":"build","hook":"Build the plan for when a friend is too scared to tell.","prompt":"Put the steps in order.","pieces":["Listen to your friend","Offer to go with them","Walk to a trusted adult together","Stay with them after","Tell them to forget it","Spread it around"],"mode":"sequence","key":["Listen to your friend","Offer to go with them","Walk to a trusted adult together","Stay with them after"],"relearn":"Help a scared friend: listen, offer to go along, tell an adult together, stay close.","persona":"any","source":"ally / help-seeking"},
  {"id":"ff-1415","cat":"stand-up","type":"build","hook":"Build a kit of brave moves a bystander can make.","prompt":"Pick the moves that help, not the ones that hurt.","pieces":["Invite the kid to play","Say \"everyone plays\"","Refuse to pass a rumour","Fetch a trusted adult","Laugh along","Pass the mean note on"],"mode":"assemble","key":["Invite the kid to play","Say \"everyone plays\"","Refuse to pass a rumour","Fetch a trusted adult"],"relearn":"Bystander moves: invite in, say \"everyone plays,\" stop rumours, fetch help.","persona":"any","source":"bystander"},
  {"id":"ff-1416","cat":"stand-up","type":"build","hook":"Build the order for handling a dare you don't want to do.","prompt":"Put the steps in order.","pieces":["Say \"no thanks\" calmly","Suggest something else fun","Walk away if they push","Tell an adult if it's unsafe","Just do the dare","Dare someone smaller"],"mode":"sequence","key":["Say \"no thanks\" calmly","Suggest something else fun","Walk away if they push","Tell an adult if it's unsafe"],"relearn":"Handle a dare: say no, offer a swap, walk away, tell an adult if it's unsafe.","persona":"any","source":"peer pressure / plan"},
  {"id":"ff-1417","cat":"stand-up","type":"match","hook":"Match the unkind moment to a calm comeback.","pairs":[{"left":"\"Pink is for girls\"","right":"\"Colours are for everyone.\""},{"left":"\"You can't do maths\"","right":"\"Anyone can. Watch.\""},{"left":"\"Only boys play here\"","right":"\"Games are for everyone.\""},{"left":"A kid left out","right":"\"Come on, let's all play.\""},{"left":"A whispered rumour","right":"\"I won't pass that on.\""}],"relearn":"Each unkind line has a calm comeback that includes, not fights.","persona":"Reyansh","source":"comebacks"},
  {"id":"ff-1418","cat":"stand-up","type":"match","hook":"Match the situation to the brave next step.","pairs":[{"left":"Your calm line was ignored","right":"Walk away and tell an adult"},{"left":"A friend is too scared to tell","right":"Offer to go with them"},{"left":"A kid is left out of a game","right":"Say \"everyone plays\""},{"left":"Someone repeats a rumour","right":"Refuse to pass it on"},{"left":"A bully threatens you to stay quiet","right":"Tell a trusted grown-up"}],"relearn":"Every stand-up moment has a brave, doable next step.","persona":"any","source":"escalation"},
  {"id":"ff-1419","cat":"stand-up","type":"match","hook":"Match the ally move to what it does for a friend.","pairs":[{"left":"Standing close by","right":"They feel less alone"},{"left":"Saying \"that's not okay\"","right":"The teasing is named"},{"left":"\"Come on, let's go\"","right":"They get an easy exit"},{"left":"\"You okay?\" after","right":"They feel checked on"},{"left":"Fetching a teacher","right":"A grown-up can step in"}],"relearn":"Small ally moves each do something real for a struggling friend.","persona":"any","source":"ally"},
  {"id":"ff-1420","cat":"stand-up","type":"match","hook":"Match assertive to aggressive, see the difference.","pairs":[{"left":"\"Please stop, I don't like that\"","right":"Assertive and calm"},{"left":"Shoving them away","right":"Aggressive, starts a fight"},{"left":"\"Let me finish, then your turn\"","right":"Fair and firm"},{"left":"Screaming insults back","right":"Aggressive, not a boundary"},{"left":"Walking away and telling an adult","right":"Smart and safe"}],"relearn":"Assertive is calm and clear; aggressive attacks and escalates.","persona":"any","source":"assertiveness"},
  {"id":"ff-1421","cat":"stand-up","type":"match","hook":"Match the worry to the thought that helps you.","pairs":[{"left":"\"It's my fault they're mean\"","right":"Their unkindness is their choice"},{"left":"\"I'll lose if I don't win it\"","right":"Walking away can be the win"},{"left":"\"Telling is tattling\"","right":"Getting help is brave"},{"left":"\"I have to obey my friend\"","right":"I can keep my own mind"},{"left":"\"I froze, I'm hopeless\"","right":"Bravery grows with practice"}],"relearn":"A helpful thought turns a worry into a brave step.","persona":"any","source":"self-talk"},
  {"id":"ff-1422","cat":"stand-up","type":"match","hook":"Match who's being unkind to a kind thing you could say.","pairs":[{"left":"Mocking a slow runner","right":"\"Keep going, you've got this!\""},{"left":"Laughing at a drawing","right":"\"I think it's lovely.\""},{"left":"Teasing a stammer","right":"\"Take your time, we're listening.\""},{"left":"Copying an accent","right":"\"That's how they talk, stop.\""},{"left":"Hiding a bag \"for fun\"","right":"\"Please give it back.\""}],"relearn":"Each unkind moment has a kind, clear thing you can say.","persona":"any","source":"ally / comebacks"},
  {"id":"ff-1423","cat":"stand-up","type":"match","hook":"Match the online moment to the right move.","pairs":[{"left":"A kid left off the group chat","right":"Add them back in"},{"left":"\"Reply or you're out\"","right":"Tell an adult, it's a control flag"},{"left":"A mean photo being shared","right":"Don't forward it"},{"left":"A friend being ganged up on","right":"Message them kindly"},{"left":"A rumour spreading in chat","right":"Refuse to pass it on"}],"relearn":"Stand-up moves work online too, including telling an adult.","persona":"any","source":"online"},
  {"id":"ff-1424","cat":"stand-up","type":"match","hook":"Match the brave step to when you'd use it.","pairs":[{"left":"Say a calm line","right":"First, when it just started"},{"left":"Give a friend an exit","right":"When they're stuck and scared"},{"left":"Walk away","right":"When your words are mocked"},{"left":"Tell a trusted adult","right":"When it keeps happening"},{"left":"Bring a friend as backup","right":"When stepping in alone feels unsafe"}],"relearn":"Different brave steps fit different moments; you can choose.","persona":"any","source":"escalation"},
  {"id":"ff-1425","cat":"stand-up","type":"sort","hook":"Sort each line: a calm stand-up, or a fight-starter?","items":[{"id":"a","text":"\"Please stop, I don't like that.\""},{"id":"b","text":"\"You're so stupid!\""},{"id":"c","text":"\"Let's all play.\""},{"id":"d","text":"Shoving them hard"},{"id":"e","text":"\"I'd like a turn too.\""},{"id":"f","text":"Screaming insults back"}],"bins":[{"id":"calm","label":"Calm stand-up","valence":"pos"},{"id":"fight","label":"Fight-starter","valence":"neg"}],"key":{"a":"calm","b":"fight","c":"calm","d":"fight","e":"calm","f":"fight"},"relearn":"Calm, clear lines stand up; insults and shoving start fights.","persona":"any","source":"assertiveness"},
  {"id":"ff-1426","cat":"stand-up","type":"sort","hook":"Sort each move: helps a teased friend, or makes it worse?","items":[{"id":"a","text":"Standing beside them"},{"id":"b","text":"Laughing along"},{"id":"c","text":"Saying \"that's not okay\""},{"id":"d","text":"Joining the teasing"},{"id":"e","text":"Checking \"you okay?\" after"},{"id":"f","text":"Filming it for fun"}],"bins":[{"id":"helps","label":"Helps your friend","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"helps","b":"worse","c":"helps","d":"worse","e":"helps","f":"worse"},"relearn":"Standing close, naming it and checking in help; laughing along hurts.","persona":"any","source":"ally"},
  {"id":"ff-1427","cat":"stand-up","type":"sort","hook":"Sort each one: tell a grown-up, or handle it yourself?","items":[{"id":"a","text":"A bully keeps hurting you"},{"id":"b","text":"A small spat over a turn"},{"id":"c","text":"Someone threatens you to stay quiet"},{"id":"d","text":"A friend liked a different game"},{"id":"e","text":"Someone planning to hurt a kid"},{"id":"f","text":"You both want one swing"}],"bins":[{"id":"tell","label":"Tell a grown-up","valence":"tell"},{"id":"self","label":"Handle it yourself","valence":"neutral"}],"key":{"a":"tell","b":"self","c":"tell","d":"self","e":"tell","f":"self"},"relearn":"Bullying, threats and planned harm need a grown-up; small spats you can sort.","persona":"any","source":"help-seeking"},
  {"id":"ff-1428","cat":"stand-up","type":"sort","hook":"Sort each comeback: includes everyone, or splits boys and girls?","items":[{"id":"a","text":"\"Colours are for everyone.\""},{"id":"b","text":"\"That's only for boys.\""},{"id":"c","text":"\"Games are for everyone.\""},{"id":"d","text":"\"Dolls are just for girls.\""},{"id":"e","text":"\"Anyone can play this.\""},{"id":"f","text":"\"Boys can't like pink.\""}],"bins":[{"id":"include","label":"Includes everyone","valence":"pos"},{"id":"split","label":"Splits kids up","valence":"neg"}],"key":{"a":"include","b":"split","c":"include","d":"split","e":"include","f":"split"},"relearn":"Toys, games and colours are for everyone; \"only for boys/girls\" splits kids.","persona":"Reyansh","source":"gender norms"},
  {"id":"ff-1429","cat":"stand-up","type":"sort","hook":"Sort each thought: helps you stay brave, or makes you give up?","items":[{"id":"a","text":"\"Their unkindness is their choice\""},{"id":"b","text":"\"It must be my fault\""},{"id":"c","text":"\"I can ask for help\""},{"id":"d","text":"\"I just have to put up with it\""},{"id":"e","text":"\"Bravery grows with practice\""},{"id":"f","text":"\"I'm hopeless at this\""}],"bins":[{"id":"brave","label":"Keeps you brave","valence":"pos"},{"id":"giveup","label":"Makes you give up","valence":"uhoh"}],"key":{"a":"brave","b":"giveup","c":"brave","d":"giveup","e":"brave","f":"giveup"},"relearn":"Kind, true thoughts keep you brave; blame makes you give up.","persona":"any","source":"self-talk"},
  {"id":"ff-1430","cat":"stand-up","type":"sort","hook":"Sort each one: a real stand-up move, or just being mean back?","items":[{"id":"a","text":"Refusing to pass a rumour"},{"id":"b","text":"Spreading a meaner rumour"},{"id":"c","text":"Saying \"everyone plays\""},{"id":"d","text":"Freezing them out in revenge"},{"id":"e","text":"Telling an adult about a bully"},{"id":"f","text":"Daring a smaller kid instead"}],"bins":[{"id":"standup","label":"Real stand-up","valence":"pos"},{"id":"mean","label":"Mean back","valence":"neg"}],"key":{"a":"standup","b":"mean","c":"standup","d":"mean","e":"standup","f":"mean"},"relearn":"Standing up includes and protects; \"mean back\" just passes the hurt on.","persona":"Ananya","source":"values"},
  {"id":"ff-1431","cat":"stand-up","type":"sort","hook":"Sort each online move: a kind ally move, or a careful-now flag?","items":[{"id":"a","text":"Adding a left-out kid to the chat"},{"id":"b","text":"Forwarding a mean photo"},{"id":"c","text":"Messaging a ganged-up kid kindly"},{"id":"d","text":"\"Reply or you're out\""},{"id":"e","text":"Refusing to share a rumour"},{"id":"f","text":"Posting to embarrass someone"}],"bins":[{"id":"ally","label":"Kind ally move","valence":"pos"},{"id":"flag","label":"Careful, a flag","valence":"uhoh"}],"key":{"a":"ally","b":"flag","c":"ally","d":"flag","e":"ally","f":"flag"},"relearn":"Online you can include and refuse to spread; threats are flags.","persona":"any","source":"online"},
  {"id":"ff-1432","cat":"stand-up","type":"sort","hook":"Sort each step: a brave next step, or a stuck choice?","items":[{"id":"a","text":"Telling a trusted adult"},{"id":"b","text":"Putting up with it in silence"},{"id":"c","text":"Bringing a friend as backup"},{"id":"d","text":"Wishing you'd stayed quiet"},{"id":"e","text":"Planning a line for next time"},{"id":"f","text":"Deciding you're just no good"}],"bins":[{"id":"brave","label":"Brave next step","valence":"pos"},{"id":"stuck","label":"Stuck choice","valence":"uhoh"}],"key":{"a":"brave","b":"stuck","c":"brave","d":"stuck","e":"brave","f":"stuck"},"relearn":"Telling, backup and planning move you forward; silence and self-blame keep you stuck.","persona":"any","source":"escalation"},
];

